// ===== src/js/core/config.js =====
/* ---------- módulos: turma, disciplina, código, formador, designação, ano letivo ---------- */
const isDisc=c=>/^\d{4}\s*-\s*\S/.test(String(c).trim());
const isTurma=c=>/\(\s*\d{2,4}\s*[-\/]\s*\d{2,4}\s*\)/.test(c);
const isModName=c=>{const n=norm(c);return /^(modulo|mod\.?|ufcd)\s*[a-z0-9]/.test(n)||/^uc\s*\d/.test(n)};
const discCode=d=>(String(d||"").match(/^\s*(\d{3,5})/)||[])[1]||norm(d);
const discShort=d=>String(d||"").replace(/^\s*\d+\s*-\s*/,"");
// chave do módulo: "Módulo 1" = "Módulo 01" = "Módulo 001" → "1"; "UFCD 0349 (nome)" → "349"; "UC03611 - nome" → "uc3611"
const modKey=c=>{let n=norm(c),uc=false;
  if(/^uc\s*\d/.test(n)){uc=true;n=n.replace(/^uc\s*/,"")}else n=n.replace(/^(modulo|mod\.?|ufcd)\s*/,"");
  const m=n.match(/^0*(\d+)(?=$|[\s\-–(:.,_])/);if(m)return (uc?"uc":"")+m[1];
  return (uc?"uc":"")+n.replace(/^0+(?=[a-z0-9])/,"")};
// código curto (sem o nome) e nome tirado da própria pasta: "UFCD 0349 (Ambiente)" → "UFCD 0349" + "Ambiente"
const COD_RE=/^\s*((?:m[oó]dulo|mod\.?|ufcd|uc)\s*[a-z]{0,2}\s*\d+|[a-z]?\d{3,6})/i;
const codCurto=c=>{const m=String(c||"").match(COD_RE);return m?m[1].trim():String(c||"")};
const nomeDaPasta=c=>{const m=String(c||"").match(COD_RE);if(!m)return "";return String(c).slice(m[0].length).replace(/^[\s\-–:.)]+/,"").replace(/^\((.*)\)$/,"$1").trim()};
// ano letivo tirado do nome de uma pasta (ex.: "DTP 2025.2026" → "2025/2026")
const anoDe=p=>{const m=String(p||"").match(/(20\d\d)\s*[.\-\/_ ]\s*(20\d\d)/);return m&&+m[2]===+m[1]+1?m[1]+"/"+m[2]:""};
// a grelha turma × disciplina é guardada por ano letivo; as atribuições antigas (sem ano) servem de valor por omissão
const legKey=m=>norm(m.turma)+"|"+discCode(m.disc);
const gridKey=m=>(m.ano?m.ano+"|":"")+legKey(m);
const gridGet=m=>{const k=gridKey(m);if(k in cfg.grid)return cfg.grid[k]||"";return (m.ano&&cfg.grid[legKey(m)])||""};
const pastaDe=m=>[m.anoDir,m.turma,m.disc,m.cod].filter(Boolean).join(" / ");
function fillModFields(m){
  if(m.disc&&m.cod)return;
  const parts=String(m.pasta||"").split("/").map(x=>x.trim()).filter(Boolean);
  if(!m.disc)m.disc=parts.find(isDisc)||(parts.length>=2?parts[parts.length-2]:"");
  if(!m.cod)m.cod=parts.filter(p=>p!==m.disc&&p!==m.turma&&!isTurma(p)).pop()||m.nome||"";
}
/* 0.9.52: Box360 ← Plano Curricular — quem dá cada disciplina a cada turma (o formador com mais horas no plano desse ano letivo)
   vale como atribuição enquanto a Direção não escolher outro na grelha. Nada é gravado: é só o que se usa quando a grelha está vazia. */
var PLP=null;
function planoMapa(){const k=String(cfgRev);if(PLP&&PLP.k===k)return PLP.m;const M=new Map();
  try{const E=escData(),anoN=new Map(E.anos.map(a=>[a.id,a.nome])),tById=new Map(E.turmas.map(t=>[t.id,t]));
    for(const p of pcPlanos()){const t=tById.get(p.turmaId),an=anoN.get(p.anoId);if(!t||!an||!t.cod)continue;const h=new Map();
      for(const l of p.linhas||[]){if(!l||!l.f||!l.disc)continue;const kk=an+"|"+norm(t.cod)+"|"+discCode(l.disc);const o=h.get(kk)||new Map();o.set(l.f,(o.get(l.f)||0)+(+l.h||0));h.set(kk,o)}
      for(const [kk,o] of h){let best="",mx=-1;for(const [f,v] of o)if(v>mx){mx=v;best=f}if(best)M.set(kk,best)}}}catch(e){}
  PLP={k,m:M};return M}
function planoProf(m){if(!m||!m.ano)return"";const M=planoMapa();if(!M.size)return"";const tc=norm(m.turma),dc=discCode(m.disc);let v=M.get(m.ano+"|"+tc+"|"+dc);
  if(!v){const t0=tc.split(/[\s\-–—]+/)[0];if(t0&&t0!==tc)v=M.get(m.ano+"|"+t0+"|"+dc)}
  return v&&cfg.profs.some(p=>p.id===v)?v:""}
const gridEf=m=>gridGet(m)||planoProf(m);
const profOf=m=>m.profId||gridEf(m)||"";
const isExc=m=>!!m.profId&&m.profId!==gridEf(m);
const profName=id=>(cfg.profs.find(p=>p.id===id)||{}).nome||"";
const desigOf=m=>cfg.desig[discCode(m.disc)+"|"+modKey(m.cod)]||cfg.desig["*|"+modKey(m.cod)]||snqDesig(m)||nomeDaPasta(m.cod)||"";
const modTitle=m=>(m.cod?codCurto(m.cod):(m.nome||"(módulo)"))+(desigOf(m)?" — "+desigOf(m):"");
const modLabel=m=>[discShort(m.disc),modTitle(m),m.turma].filter(Boolean).join(" · ");

/* ---------- atualização da configuração antiga ---------- */
function migrate(){
  cfg.grid=cfg.grid||{};cfg.desig=cfg.desig||{};cfg.envios=cfg.envios||[];cfg.snq=cfg.snq||{};
  if(!cfg.keyV2){const d={};for(const k in cfg.desig){const i=k.indexOf("|");d[k.slice(0,i)+"|"+modKey(k.slice(i+1))]=cfg.desig[k]}cfg.desig=d;cfg.keyV2=1}
  cfg.qual=Object.assign({min:40,dup:true},cfg.qual||{});
  cfg.mail=Object.assign({subj:MAIL_SUBJ,prazo:"",ano:"",body:MAIL_BODY,relatorio_para:""},cfg.mail||{});
  cfg.mods.forEach(fillModFields);
  const s0=cfg.schema||1;
  if(s0<2){
    ponto("Antes da atualização para a v"+VERSAO);
    const old=["Planificação","Recursos didáticos / fichas","Teste / prova do módulo"];
    if(cfg.docTypes.length===3&&cfg.docTypes.every((d,i)=>d.nome===old[i])){cfg.docTypes=dtpTypes();cfg.mods.forEach(m=>m.docs=cfg.docTypes.map(d=>d.id))}
    if(cfg.mail.body===OLD_BODY)cfg.mail.body=MAIL_BODY;
    if(cfg.mail.subj==="Documentação em falta na Box")cfg.mail.subj=MAIL_SUBJ;
    // atribuições feitas módulo a módulo → grelha (quando todos os módulos da turma/disciplina têm o mesmo formador)
    const g=new Map();cfg.mods.forEach(m=>{const k=gridKey(m);if(!g.has(k))g.set(k,[]);g.get(k).push(m)});
    for(const [k,list] of g){const ids=[...new Set(list.map(m=>m.profId||""))];
      if(ids.length===1&&ids[0]&&!cfg.grid[k]){cfg.grid[k]=ids[0];list.forEach(m=>m.profId="")}}
    cfg.schema=2;
  }
  if(s0<3){
    if(s0===2&&cfg.mods.length)ponto("Antes da atualização para a v"+VERSAO);
    cfg.schema=3;
  }
  acertos094();
  // "o texto deve conter": valores por omissão para os documentos do modelo DTP EPISJ
  cfg.docTypes.forEach(d=>{if(d.conteudo===undefined){const p=DTP_TYPES.find(x=>x[0]===d.nome);d.conteudo=p?p[2]:""}});
}
/* 0.9.94: (a) a regra antiga da Matriz pedia uma pasta «008 / Matrizes», que não existe na Box da escola — passa a procurar
   «matriz» no nome do ficheiro ou da pasta, dentro da Avaliação (só uma vez; se a Direção voltar a mudar, fica como escolheu);
   (b) o mesmo módulo detetado em dois computadores ficava duas vezes (ids diferentes) e o relatório repetia as linhas:
   juntam-se num só, sem perder nada (formador, designação, documentos — o que estiver preenchido numa das cópias fica) */
function juntarModsRepetidos(c){if(!c||!Array.isArray(c.mods)||c.mods.length<2)return 0;
  const env=new Set();(c.envios||[]).forEach(v=>Object.values(v.miss||{}).forEach(L=>(L||[]).forEach(k=>env.add(String(k).split("|")[0]))));
  const by=new Map(),out=[];let n=0;
  for(const m of c.mods){const k=(m.ano||"")+"|"+norm(m.turma)+"|"+discCode(m.disc)+"|"+modKey(m.cod);const i=by.get(k);if(i===undefined){by.set(k,out.length);out.push(m);continue}
    n++;const a=out[i],ka=env.has(a.id)||!env.has(m.id)?a:m,kb=ka===a?m:a; // fica o id que consta dos envios
    for(const f in kb){const v=ka[f];if(v===undefined||v===null||v==="")ka[f]=kb[f]}
    if(Array.isArray(kb.docs)&&(!Array.isArray(ka.docs)||!ka.docs.length))ka.docs=kb.docs.slice();
    out[i]=ka}
  if(n)c.mods=out;return n}
/* 0.9.96: cada computador que começou do zero criou a sua lista de documentos exigidos (ids diferentes) e, ao juntar,
   ficaram todas — cada módulo pedia várias vezes «Matrizes», «Enunciados…» e o relatório repetia as linhas.
   Juntam-se pelo nome; os ids antigos passam para o que fica nos módulos, nos prazos e nos envios registados (nada se perde). */
function juntarDocsRepetidos(c){const L=c&&c.docTypes;if(!Array.isArray(L)||L.length<2)return 0;
  const envD=new Set();(c.envios||[]).forEach(v=>Object.values(v.miss||{}).forEach(K=>(K||[]).forEach(k=>envD.add(String(k).split("|")[1]))));
  const by=new Map(),map={},out=[];
  for(const d of L){if(!d||typeof d!=="object")continue;const k=norm(d.nome||"");const i=by.get(k);if(i===undefined){by.set(k,out.length);out.push(d);continue}
    const a=out[i];if(envD.has(d.id)&&!envD.has(a.id)){map[a.id]=d.id;out[i]=d}else map[d.id]=a.id}
  const n=L.length-out.length;if(!n)return 0;
  const R=id=>{let x=id,g=0;while(map[x]&&g++<50)x=map[x];return x},fix=A=>Array.isArray(A)?[...new Set(A.map(R))]:A;
  c.docTypes=out;(c.mods||[]).forEach(m=>{m.docs=fix(m.docs)});(c.prazos||[]).forEach(p=>{if(p&&p.docs)p.docs=fix(p.docs)});
  (c.envios||[]).forEach(v=>{for(const pid in v.miss||{})v.miss[pid]=[...new Set((v.miss[pid]||[]).map(k=>{const q=String(k).split("|");return q.length===2?q[0]+"|"+R(q[1]):k}))]});
  return n}
function acertos094(){let mud=0;
  const nd=juntarDocsRepetidos(cfg);if(nd){mud++;console.info("EPISJ 360: "+nd+" documento(s) exigido(s) repetido(s) juntado(s)")}
  // 0.9.96: corre sempre (não só uma vez) — um computador com uma versão antiga aberta podia repor «008 / Matrizes» ao gravar
  for(const d of cfg.docTypes||[])if(String(d.subpasta||"").split("/").map(norm).filter(Boolean).join("/")==="008/matrizes"&&!String(d.palavras||"").trim()){
    if(!mud)ponto("Antes da correção da regra das Matrizes");d.subpasta="008";d.palavras="matriz";mud++}
  cfg.acerto094=1;
  const n=juntarModsRepetidos(cfg);if(n){mud++;console.info("EPISJ 360: "+n+" módulo(s) repetido(s) juntado(s)")}
  if(mud)cfgRev++;return mud}
migrate();persist();lastJSON=JSON.stringify(cfg);

// ===== src/js/box/armazenamento.js =====
/* ---------- 0.9.148: armazenamento grande só em memória (textos dos documentos, listagens, contagens, dados dos módulos) ----------
   Nada fica no computador: estas cópias vivem enquanto a página está aberta e vêm do Supabase ao entrar.
   Na primeira abertura depois da atualização, o que versões antigas deixaram no IndexedDB «boxcheck» deste computador passa
   para a memória (para não se perder nada que ainda não esteja na nuvem); legadoLimpar() apaga-o depois de confirmado na nuvem.
   As cópias são guardadas e devolvidas clonadas (como fazia o IndexedDB), para quem as lê não mexer na que está guardada. */
const DB=(()=>{const S={textos:new Map(),listagens:new Map(),kv:new Map()};let L=null;
  const clone=v=>{if(v===undefined||v===null||typeof v!=="object")return v;try{return structuredClone(v)}catch(e){return v}};
  // 0.9.152: nunca fica à espera para sempre — se o IndexedDB antigo não responder (por exemplo, apagado com outro separador
  // ainda aberto, o que deixa o pedido parado), ao fim de 5 s segue sem ele (a nuvem tem o resto)
  const legado=()=>L||(L=new Promise(async ok=>{setTimeout(()=>{if(!DB.legadoOk)console.warn("IndexedDB antigo sem resposta: segue sem ele");ok()},5000);try{if(!window.indexedDB)return ok();
      if(indexedDB.databases){const D=await Promise.race([indexedDB.databases(),new Promise(r=>setTimeout(()=>r([{name:"boxcheck"}]),2500))]);if(!D.some(d=>d&&d.name==="boxcheck"))return ok()}
      const r=indexedDB.open("boxcheck");let novo=false;r.onupgradeneeded=()=>{novo=true};
      r.onsuccess=()=>{const d=r.result;const st=[...d.objectStoreNames].filter(n=>S[n]);if(novo||!st.length){d.close();return ok()}
        const t=d.transaction(st,"readonly");st.forEach(n=>{const q=t.objectStore(n).openCursor();q.onsuccess=()=>{const c=q.result;if(c){if(!S[n].has(c.key)){S[n].set(c.key,c.value);DB.legado++}c.continue()}}});
        t.oncomplete=()=>{d.close();DB.legadoOk=1;ok()};t.onerror=t.onabort=()=>{try{d.close()}catch(e){}ok()}};
      r.onerror=r.onblocked=()=>ok()}catch(e){ok()}}));
  return{legado:0,carregarLegado:legado,
    get:async(s,k)=>{await legado();return S[s]?clone(S[s].get(k)):undefined},
    put:async(s,k,v)=>{await legado();if(!S[s])return false;S[s].set(k,clone(v));return true},
    all:async s=>{await legado();return S[s]?[...S[s].values()].map(clone):[]},
    del:async(s,k)=>{await legado();if(S[s])S[s].delete(k)}}})();
// 0.9.35: ao abrir, se a cópia no IndexedDB for mais recente do que a do localStorage (por exemplo, porque o localStorage estava cheio), junta-se
DB.get("kv","cfgCopia").then(c=>{if(!c||!c.s||RO||LIMPAR)return;const lt=+(localStorage.getItem(KEY+"_t")||0);
  if(c.t>lt+500&&c.s!==lastStored){try{const o=JSON.parse(c.s);cfg=juntarCfg(o,cfg);try{migrate()}catch(e){}lastJSON=JSON.stringify(cfg);cfgRev++;persist(lastJSON);try{refreshAll()}catch(e){}}catch(e){console.warn("cópia",e)}}}).catch(()=>{});


/* ---------- análise do texto de um documento: palavras, enchimento e "impressão" para comparar textos ---------- */
const TX=new Map(); // sha1 -> {sha1, n: início do texto normalizado, w: n.º de palavras, u, top, lorem, rep, sig} (w=null: a Box não tem texto)
function fnv(s){let h=0x811c9dc5;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,0x01000193)}return h>>>0}
const MH=64,MHA=new Uint32Array(MH),MHB=new Uint32Array(MH);{let x=12345;const r=()=>{x=(Math.imul(x^(x>>>15),0x2c1b3c6d)+0x297a2d39)>>>0;return x};for(let i=0;i<MH;i++){MHA[i]=r()|1;MHB[i]=r()}}
function analisarTexto(raw){
  const full=norm(String(raw||"")).slice(0,60000);
  const tk=full.match(/[a-z0-9]{2,}/g)||[];const w=tk.length;
  const freq=new Map();for(const t of tk)freq.set(t,(freq.get(t)||0)+1);
  let mx=0;for(const v of freq.values())if(v>mx)mx=v;
  const top=w?mx/w:0,u=w?freq.size/w:0;
  const lorem=/lorem ipsum|dolor sit amet|consectetur adipiscing/.test(full);
  const rep=/(.)\1{11,}/.test(full.replace(/[\s._\-=*|]/g,""))||/\b([a-z0-9]{2,})(\s+\1\b){5,}/.test(full);
  // impressão do texto (minhash sobre sequências de 5 palavras): dois textos quase iguais têm impressões quase iguais
  const sig=new Uint32Array(MH).fill(0xffffffff);const lim=Math.min(w,5000),k=lim>=5?5:Math.max(1,lim);
  const th=new Uint32Array(lim);for(let i=0;i<lim;i++)th[i]=fnv(tk[i]);
  for(let i=0;i+k<=lim;i++){let h=th[i];for(let q=1;q<k;q++)h=Math.imul(h^th[i+q],0x01000193)>>>0;
    for(let j=0;j<MH;j++){const v=(Math.imul(MHA[j],h)+MHB[j])>>>0;if(v<sig[j])sig[j]=v}}
  return{n:full.slice(0,8000),w,u,top,lorem,rep,sig};
}
const simSig=(a,b)=>{let s=0;for(let i=0;i<MH;i++)if(a[i]===b[i])s++;return s/MH};
const bandKeys=t=>t.bk||(t.bk=Array.from({length:16},(_,b)=>b+":"+t.sig[b*4]+","+t.sig[b*4+1]+","+t.sig[b*4+2]+","+t.sig[b*4+3]));
const textosProntos=DB.all("textos").then(all=>{const lim=Date.now()-7*864e5;
  for(const r of all){if(!r||!r.sha1)continue;if(r.w==null){if((r.t||0)>lim)TX.set(r.sha1,r)}else if(r.sig)TX.set(r.sha1,r)}
  txRev++});
async function guardarTexto(sha1,txt){const a=analisarTexto(txt);a.sha1=sha1;TX.set(sha1,a);txRev++;await DB.put("textos",sha1,a)}
async function guardarSemTexto(sha1){const a={sha1,w:null,t:Date.now()};TX.set(sha1,a);await DB.put("textos",sha1,a)}

/* ---------- listagens guardadas por pasta analisada, e contagens (pontos de comparação) ---------- */
const lsJ=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k)||"null");return v==null?d:v}catch(e){return d}};
const resumos=()=>lsJ("box_resumos",{});
async function guardarListagem(j){
  const ok=await DB.put("listagens","L|"+j.rootId,j);
  const r=resumos();r[j.rootId]={pasta:j.pasta,quando:j.quando,t:j.t,tFull:j.tFull||j.t,pos:!!j.pos,n:j.nF,np:j.nP};
  try{localStorage.setItem("box_resumos",JSON.stringify(r));localStorage.setItem("box_last_root",j.rootId);
    if(ok)localStorage.removeItem("box_last_listing")}catch(e){}
  if(!ok){try{localStorage.setItem("box_last_listing",JSON.stringify(j))}catch(e){}}
  setTimeout(renderAnalises,0);
  return ok}
async function lerListagem(rootId){let j=await DB.get("listagens","L|"+rootId);
  if(!j){const o=lsJ("box_last_listing",null);if(o&&o.itens&&(o.rootId||"legacy")===rootId)j=o}
  return j||null}
const basesIdx=()=>lsJ("box_bases",{});
// uma contagem guarda só os ficheiros (é com ela que o painel Alterações compara o estado atual)
async function criarBase(j,label){
  const b={rootId:j.rootId,t:Date.now(),quando:j.quando,pasta:j.pasta,label,
    itens:j.itens.filter(x=>x.type!=="folder").map(x=>({id:x.id,path:x.path,name:x.name,size:x.size??null,sha1:x.sha1||"",modified_at:x.modified_at||""}))};
  if(!await DB.put("listagens","B|"+j.rootId+"|"+b.t,b))return null;
  const idx=basesIdx(),l=(idx[j.rootId]=idx[j.rootId]||[]);l.unshift({t:b.t,quando:b.quando,label,n:b.itens.length});
  while(l.length>12){const old=l.pop();DB.del("listagens","B|"+j.rootId+"|"+old.t)}
  try{localStorage.setItem("box_bases",JSON.stringify(idx))}catch(e){}
  setTimeout(()=>nuvemBases(j.rootId),0);
  return b}
const lerBase=(rootId,t)=>DB.get("listagens","B|"+rootId+"|"+t);
// análise guardada pelas versões anteriores (no armazenamento pequeno do navegador): passa para a base de dados local
const migrarListagem=(async()=>{try{const o=lsJ("box_last_listing",null);if(!o||!o.itens)return;
  if(!o.rootId)o.rootId="legacy";o.nP=o.itens.filter(x=>x.type==="folder").length;o.nF=o.itens.length-o.nP;
  if(await guardarListagem(o)&&!(basesIdx()[o.rootId]||[]).length)await criarBase(o,"Análise de "+o.quando)}catch(e){console.warn(e)}})();

function download(name,text,type){
  try{const b=text instanceof Blob?text:new Blob([text],{type:type||"text/plain;charset=utf-8"});const a=document.createElement("a");a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
  catch(e){toast("Não foi possível descarregar — use Copiar")}}
const hoje=()=>{const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}; // 0.9.110: data local (nos Açores, entre as 23h e a meia-noite, a data em UTC já era a do dia seguinte)
const dataPT=t=>new Date(t).toLocaleDateString("pt-PT");
function toast(m){const t=$("#toast");t.textContent=m;t.classList.add("on");clearTimeout(t._h);t._h=setTimeout(()=>t.classList.remove("on"),2200)}
async function copy(txt){try{await navigator.clipboard.writeText(txt);toast("Copiado")}catch(e){toast("Não foi possível copiar — selecione o texto e use Ctrl+C")}}

// ===== src/js/core/modulos.js =====
/* ---------- módulos da EPISJ 360 ---------- */
const MODULOS=[{id:"escola",nome:"Escola360",inicio:"esc"},{id:"boxcheck",nome:"Box360",inicio:"box"},{id:"eduschedule",nome:"Horários360",inicio:(()=>{try{return localStorage.getItem("h360_modo")==="completa"?"esch":"hsSem"}catch(e){return "hsSem"}})()},{id:"roomcheck",nome:"Sala360",inicio:"rcMapa"},{id:"crono",nome:"Crono360",inicio:"crPs"},{id:"social",nome:"Social360",inicio:"s3feed"},{id:"pap",nome:"PAP360",inicio:"papInicio"},{id:"pass",nome:"Pass360",inicio:"pwCofre"},{id:"folder",nome:"Folder360",inicio:"foInicio"},{id:"econo",nome:"Econo360",inicio:"ecoInicio"}]; // novos módulos entram aqui, com um grupo .mgrp[data-m] no menu lateral
/* ---------- 0.9.133: módulos carregados só quando são abertos (PAP360, Pass360, Folder360, Econo360) ----------
   Os dados destes módulos (estado, nuvem, cópias, widgets) vêm sempre com a app (ficheiros *-dados.js); o ecrã de cada um
   está num ficheiro à parte (app/m/<id>.js), carregado na primeira vez que o módulo é aberto. Quem não tem acesso nunca o descarrega. */
const MOD_LAZY={pap:"app/m/pap.js",pass:"app/m/pass.js",folder:"app/m/folder.js",econo:"app/m/econo.js"};
const MOD_P={};
function modCarregado(m){return MOD_P[m]&&MOD_P[m].ok===true}
function modCarregar(m){if(!MOD_LAZY[m])return Promise.resolve();if(MOD_P[m])return MOD_P[m].p;
  const r={ok:false};r.p=new Promise((ok,ko)=>{const s=document.createElement("script");s.src=MOD_LAZY[m]+"?v="+encodeURIComponent(VERSAO);s.async=true;
    s.onload=()=>{r.ok=true;ok()};
    s.onerror=()=>{delete MOD_P[m];s.remove();ko(new Error("Não foi possível carregar este módulo. Verifique a ligação à Internet e tente outra vez."))};
    document.head.appendChild(s)});MOD_P[m]=r;return r.p}
// o primeiro desenho de um destes módulos carrega o ficheiro e depois chama o desenho verdadeiro (que substitui este)
function modStub(m,nome){const st=function(...a){return modCarregar(m).then(()=>{const f=window[nome];if(typeof f!=="function"||f===st)throw new Error("O módulo "+m+" não arrancou.");return f.apply(this,a)})
  .catch(e=>{console.warn(e);try{toast(e.message||String(e))}catch(x){}})};return st}
var papRender=modStub("pap","papRender"),pwRender=modStub("pass","pwRender"),foRender=modStub("folder","foRender"),ecoRender=modStub("econo","ecoRender");
// depois de a app abrir, quem pode ver estes módulos (Direção, Economato) recebe-os em segundo plano, para abrirem logo
function modPreCarregar(){try{const ir=()=>{for(const m of Object.keys(MOD_LAZY)){const M=MODULOS.find(x=>x.id===m);if(M&&podeVer(M.inicio))modCarregar(m).catch(()=>{})}};
  (window.requestIdleCallback||(f=>setTimeout(f,1500)))(ir,{timeout:8000})}catch(e){}}
let curMod=(()=>{try{const m=localStorage.getItem("guide_mod");return MODULOS.some(x=>x.id===m)?m:MODULOS[0].id}catch(e){return MODULOS[0].id}})();
function mostrarModulo(id,abrir){curMod=id;try{localStorage.setItem("guide_mod",id)}catch(e){}
  document.querySelectorAll("#mods button").forEach(b=>b.classList.toggle("on",b.dataset.m===id));
  document.querySelectorAll("#nav .mgrp[data-m]").forEach(g=>g.hidden=g.dataset.m!==id);
  if(abrir){const t=primeiroPermitido(id);if(t)show(t)}}
// separador → módulo (pelo grupo do menu lateral); o primeiro separador que o perfil pode abrir em cada módulo
function modDeTab(t){const b=document.querySelector(`#nav button[data-t="${t}"]`);const g=b&&b.closest(".mgrp[data-m]");return g?g.dataset.m:null}
function primeiroPermitido(m){const M=MODULOS.find(x=>x.id===m);if(M&&podeVer(M.inicio))return M.inicio;
  const b=[...document.querySelectorAll(`#nav .mgrp[data-m="${m}"] button[data-t]`)].find(x=>podeVer(x.dataset.t));return b?b.dataset.t:null}
function visAtual(){if(PREV&&UTI)return new Set(UTI.loja.vis[PREV]||UTI.visOmissao[PREV]||[]);if(!EU||!EU.vis)return null;return new Set(EU.vis)}
// 0.9.19: módulos desligados pelo administrador — ninguém os vê, só os administradores (e não na pré-visualização de um perfil)
function modEscondido(m){return !!m&&MODS_OFF.includes(m)&&!!EU&&(!EU.admin||!!PREV)}
// 0.9.28: enquanto o serviço da Cloudflare não conhecer os separadores novos, vê-os quem vê o separador "pai" (e cada formador a sua DSD)
const TAB_PAI={pc:"tur",dsd:"prof"};
function podeVer(t){if(t==="per")return podeVer("uti"); // 0.9.176: «Perfis» saiu de «Utilizadores e perfis» — vê-o quem vê Utilizadores
if(t==="esch"&&!h3EschOk())return false; // 0.9.136: o editor completo só na versão completa do Horários360 (ou a importar do Untis)
  if(/^pw/.test(t))return pwPode()&&!(MODS_OFF.length&&modEscondido("pass"))&&!visNeg(t); // 0.9.98: Pass360 — só a Direção, sempre
  const v=visAtual();if(MODS_OFF.length&&modEscondido(modDeTab(t)))return false;if(!v||v.has(t))return true;
  if(v.has("!"+t))return false; // 0.9.182: desmarcado em Perfis › O que cada perfil vê — vale mais do que a regra por omissão dos separadores novos
  if(TAB_PAI[t]&&!Object.keys(TAB_PAI).some(k=>v.has(k))&&!tabSrv(t))return v.has(TAB_PAI[t])||(t==="dsd"&&perfilAtual()==="prof");{const r=tabNovo(t,v);if(r!==null)return r}return false} // 0.9.183: pc/dsd pelo «pai» só enquanto o servidor não os conhecer
// 0.9.54: separadores novos (Calendário Escolar, Crono360) — enquanto o servidor não os conhecer, vê-os quem tem o perfil certo
/* 0.9.182: em Perfis, desmarcar um separador grava «!separador» na lista do perfil: assim o desmarcado é respeitado mesmo nos
   separadores que o servidor ainda não conhece (que, sem marca, seguem a regra por omissão de tabNovo) */
/* 0.9.183: separadores que o servidor (Supabase, g360_const().separadores) já conhece — para estes vale só o que está marcado
   em Perfis. A lista vem de UTI quando há (administradores); para as outras contas usa-se esta cópia (o g360_eu não a devolve). */
var TAB_SRV0=["esc","anos","cal","cur","tur","pc","prof","dsd","for","box","alt","pas","config","rel","est","env","pra","cop","meu","esch","mh","rcMapa","rcLista","rcEsp","crPs","crCron","crCump","crHist","crDef","ecoInicio","ecoMovs","ecoReq","ecoCompras","ecoInv","ecoCustos","ecoDef","def"];
function tabSrv(t){let srv=null;try{srv=UTI&&UTI.separadores||(EU&&EU.separadores)}catch(e){}if(!Array.isArray(srv))srv=TAB_SRV0;return srv.includes(t)}
function visNeg(t){const v=visAtual();return !!(v&&v.has("!"+t))}
function tabNovo(t,v,pfX){
  /* 0.9.183: revisto a pente fino. Antes, «v.has("esc")» servia para saber se era Direção — mas o Formador também pode ter
     o Dashboard (esc) e passava a ver Comunicar, Folder360, PAP360, Social360 e o Cumprimento/Definições do Crono360.
     Agora: se o servidor já conhece o separador, vale só o que está marcado em Perfis (null = não há regra extra);
     para os separadores que o servidor ainda não conhece, a regra por omissão é pelo perfil (Direção = Executiva/Pedagógica/administrador). */
  if(t==="esc")return (pfX||perfilAtual())!=="econ"; // 0.9.184: cada perfil tem o seu Dashboard (desmarcar em Perfis esconde-o); o Economato só vê o Econo360 (o seu painel é o Início do Econo360)
  if(tabSrv(t))return null;
  const PF=()=>pfX||perfilAtual(),DIR=()=>pfX?(pfX==="dexec"||pfX==="dped"):podePublicar(),PROF=()=>PF()==="prof";
  if(t==="cal")return true;
  if(t==="crPs"||t==="crCron"||t==="crHist"||t==="crAno")return DIR()||PROF();
  if(t==="crCump"||t==="crDef")return DIR();
  if(/^s3/.test(t))return DIR()||(!pfX&&(()=>{try{return !!S3_OK}catch(e){return false}})());
  if(/^pw/.test(t))return DIR(); // Pass360 — só a Direção
  if(/^fo[A-Z]/.test(t))return DIR(); // Folder360 — só a Direção
  if(/^eco[A-Z]/.test(t))return DIR()||PF()==="econ"||(t==="ecoReq"&&PROF()); // Econo360 — Direção e Economato; os formadores só as suas requisições
  if(/^pap/.test(t))return DIR();
  if(t==="hsVer")return PF()!=="form"&&PF()!=="econ"; // 0.9.191: Horários (ver o horário de qualquer formador ou turma) — formadores e Direção
  if(t==="hsSem")return PF()!=="econ"; // Horários360 › Semana — toda a gente vê o horário publicado (menos o Economato)
  if(t==="hsFor")return PF()!=="form"&&PF()!=="econ"; // Por formadores — formadores e Direção
  if(t==="hsCom")return DIR(); // Comunicar — só a Direção
  if(t==="mof")return false;
  return null}
$("#mods").addEventListener("click",e=>{const b=e.target.closest("button[data-m]");if(b)mostrarModulo(b.dataset.m,true)});
mostrarModulo(curMod,false);

/* ---------- tabs ---------- */
let curTab="box";
$("#nav").addEventListener("click",e=>{const b=e.target.closest("button[data-t]");if(!b)return;show(b.dataset.t)});
function show(t){if(!podeVer(t)){const f=primeiroPermitido(modDeTab(t)||curMod);if(!f||f===t)return;t=f}
  curTab=t;document.body.classList.toggle("esch",t==="esch");document.body.classList.toggle("s360",/^s3/.test(t));document.body.classList.toggle("ecom",/^eco[A-Z]/.test(t));try{if(!(LOGOS.anos&&LOGOS.anos.__ok))lgMigrar();aplicarLogos()}catch(e){}{const m=modDeTab(t);if(m&&m!==curMod)mostrarModulo(m,false)}document.querySelectorAll("#nav button").forEach(b=>b.classList.toggle("on",b.dataset.t===t));
  document.querySelectorAll("main>section").forEach(s=>s.classList.toggle("on",s.id===(t==="hsVer"?"mh":t))); // 0.9.191: «Horários» usa o mesmo ecrã de «O meu horário», com a procura
  if(t==="hsVer"||t==="mh")try{renderMh()}catch(e){}
  if(t==="prof"&&typeof GRID_SUJO!=="undefined"&&GRID_SUJO.profs){GRID_SUJO.profs=0;try{renderProfs()}catch(e){}} if(t==="rel")renderReport(); if(t==="box")try{buUI();locUI()}catch(e){} if(t==="est")renderEst(); if(t==="pas")renderTree(); if(t==="alt"){renderAlt();if(SES&&lastListing&&!scanBusy&&Date.now()-(lastListing.t||0)>120000)altAtualizar(true)} if(t==="rel"||t==="alt")verificarFundo(); if(t==="env")renderSend(); if(t==="def")renderDef(); if(t==="cop")renderRP(); if(t==="pra")renderPrazos(); if(t==="mof"){verificarFundo()} if(t==="esc")renderEscPainel(); if(t==="anos")renderAnos(); if(t==="cur")renderCursos(); if(t==="tur")renderTurmas(); if(t==="for")renderFormandos(); if(t==="pc")renderPC(); if(t==="cal")renderCal(); if(t.startsWith("cr"))crRender(t); if(t.startsWith("pap"))papRender(t); if(/^pw/.test(t))pwRender(t); if(/^fo[A-Z]/.test(t))foRender(t);if(/^eco[A-Z]/.test(t))ecoRender(t); if(t==="dsd")renderDSD(); if(t!=="esch"&&H3_IMP){H3_IMP=false;const b=document.querySelector('#nav button[data-t="esch"]');if(b)b.hidden=!podeVer("esch")} if(t==="esch")esMostrar(); if(t==="hsSem")hsRender(); if(t==="hsCom")hsComRender(); if(t==="hsFor")hsForRender(); if(t==="meu")renderMeu(); if(t==="mh")renderMh(); if(t==="uti"||t==="per")renderUti(); if(t.startsWith("rc"))try{rcRender(t)}catch(e){console.warn(e)} if(/^s3/.test(t))s3Mostrar(t)}
function refreshAll(){renderAll();if(curTab&&curTab.startsWith("rc"))try{rcRender(curTab)}catch(_){}try{escRender();esRecarregar()}catch(_){}if(curTab==="pra")renderPrazos();if(curTab==="rel")renderReport();if(curTab==="est")renderEst();if(curTab==="env")renderSend();if(curTab==="pas")renderTree();if(curTab==="alt")renderAlt();if(curTab==="cop")renderRP()}
const debounce=(fn,ms)=>{let h;return()=>{clearTimeout(h);h=setTimeout(fn,ms)}};

// ===== src/js/box/atribuicoes.js =====
/* ---------- documentos exigidos ---------- */
function renderDocs(){
  $("#tbDocs").innerHTML=cfg.docTypes.map(d=>`<tr data-id="${d.id}">
   <td><input type="text" data-k="nome" value="${esc(d.nome)}"></td>
   <td><input type="text" data-k="subpasta" value="${esc(d.subpasta)}" placeholder="—"></td>
   <td><input type="text" data-k="palavras" value="${esc(d.palavras)}" placeholder="qualquer nome"></td>
   <td><input type="text" data-k="conteudo" value="${esc(d.conteudo||"")}" placeholder="não verificar"></td>
   <td class="hm"><input type="text" data-k="ext" value="${esc(d.ext)}" placeholder="qualquer" style="width:110px"></td>
   <td class="hm"><input type="number" min="1" data-k="min" value="${d.min||1}"></td>
   <td><button class="x" title="Remover" data-del>×</button></td></tr>`).join("");
}
$("#tbDocs").addEventListener("input",e=>{const tr=e.target.closest("tr");const d=cfg.docTypes.find(x=>x.id===tr.dataset.id);const k=e.target.dataset.k;d[k]=k==="min"?Math.max(1,parseInt(e.target.value)||1):e.target.value;save();if(k==="nome")renderMods()});
$("#tbDocs").addEventListener("click",e=>{if(!e.target.hasAttribute("data-del"))return;const id=e.target.closest("tr").dataset.id;cfg.docTypes=cfg.docTypes.filter(x=>x.id!==id);cfg.mods.forEach(m=>m.docs=m.docs.filter(x=>x!==id));save();renderAll()});
$("#addDoc").onclick=()=>{const d={id:uid(),nome:"Novo documento",subpasta:"",palavras:"",conteudo:"",ext:"",min:1};cfg.docTypes.push(d);cfg.mods.forEach(m=>m.docs.push(d.id));save();renderAll()};
$("#dtpPreset").onclick=()=>{ponto("Antes de aplicar o modelo DTP EPISJ");cfg.docTypes=dtpTypes();cfg.mods.forEach(m=>m.docs=cfg.docTypes.map(d=>d.id));save();renderAll();toast("Modelo DTP EPISJ aplicado (pode anular)")};

/* ---------- formadores ---------- */
// 0.9.131: email da escola por defeito — primeiro nome + último apelido, sem acentos (Joel Lima da Cunha → joel.cunha@episj.com)
const EMAIL_DOM="episj.com";
function emailAuto(nome){const w=String(nome||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z\s'-]/g," ").split(/\s+/).map(x=>x.replace(/['-]/g,"")).filter(x=>x&&!/^(da|de|do|das|dos|e|d)$/.test(x));
  if(!w.length)return "";return (w.length>1?w[0]+"."+w[w.length-1]:w[0])+"@"+EMAIL_DOM}
// só preenche quem não tem email — nunca muda um email escrito à mão
function emailsAuto(){let n=0;(cfg.profs||[]).forEach(p=>{if(!String(p.email||"").trim()){const e=emailAuto(p.nome);if(e){p.email=e;n++}}});return n}
function renderProfs(){if(!renderProfs.wa){renderProfs.wa=1;waPronto().then(()=>{if(curTab==="prof")renderProfs()})} // 0.9.170: telemóveis (peça H3)
  if(emailsAuto())save();
  const q=norm(($("#profFilter")||{}).value||"");
  const list=cfg.profs.filter(p=>!q||norm((p.cod||"")+" "+p.nome+" "+p.email).includes(q));
  const semMail=cfg.profs.filter(p=>!/\S+@\S+\.\S+/.test(p.email||"")).length;
  const cnt={};ativos().forEach(m=>{const p=profOf(m);if(p)cnt[p]=(cnt[p]||0)+1});
  const wEl=$("#profWarn");if(wEl)wEl.innerHTML=cfg.profs.length?(semMail?`<div class="msg bad">${semMail} formador(es) sem email válido — não vão receber mensagens.</div>`:`<div class="msg ok">${cfg.profs.length} formador(es), todos com email.</div>`):"";
  PROF_N=PROF_N||200;const resto=list.length-PROF_N; // 0.9.53: com 1000 formadores, 200 linhas de cada vez (eram 4000 caixas de texto a cada redesenho)
  $("#tbProfs").innerHTML=list.slice(0,PROF_N).map(p=>`<tr data-id="${p.id}">
   <td><input type="text" data-k="cod" value="${esc(p.cod||"")}"></td>
   <td><input type="text" data-k="nome" value="${esc(p.nome)}"></td>
   <td><input type="text" data-k="abrev" value="${esc(p.abrev||"")}" maxlength="8"></td>
   <td><input type="email" data-k="email" value="${esc(p.email)}"></td>
   <td><input type="date" data-k="nasc" value="${esc(p.nasc||"")}" title="Data de nascimento (só para o widget Aniversários do Dashboard; não é publicada)"></td>
   <td><input type="tel" data-wtel="${esc(p.id)}" value="${esc(waTelVer(H3&&H3.tel[p.id]))}" placeholder="9xx xxx xxx" inputmode="tel" title="Para o SMS e o WhatsApp (só a Direção; não é publicado)"></td>
   <td class="hm" style="color:var(--muted)">${cnt[p.id]||0}</td>
   <td><button class="x" title="Remover" data-del>×</button></td></tr>`).join("")+(resto>0?`<tr><td colspan="8" style="text-align:center"><button class="b s" type="button" data-profmais>Mostrar mais ${Math.min(resto,500)} (faltam ${resto}) — ou procure acima</button></td></tr>`:"")||`<tr><td colspan="8" class="hint">${cfg.profs.length?"Ninguém corresponde à procura.":"Ainda sem formadores — adicione no formulário acima ou cole uma lista abaixo."}</td></tr>`;
}
var PROF_N=200;
// 0.9.170: telemóvel do formador (o mesmo do Horários360 › Comunicar) — peça H3, só a Direção
$("#tbProfs").addEventListener("change",async e=>{const i=e.target.closest("[data-wtel]");if(!i)return;await waPronto();if(!waTelGravar("p",i.dataset.wtel,i.value)){toast("Número de telemóvel inválido");return}i.value=waTelVer(H3.tel[i.dataset.wtel])});
$("#tbProfs").addEventListener("input",e=>{if(!e.target.dataset.k)return;const tr=e.target.closest("tr");const p=cfg.profs.find(x=>x.id===tr.dataset.id);
  if(e.target.dataset.k==="nome"){const ant=emailAuto(p.nome);if(!String(p.email||"").trim()||p.email===ant){p.email=emailAuto(e.target.value);const ie=tr.querySelector('[data-k="email"]');if(ie)ie.value=p.email}}
  p[e.target.dataset.k]=e.target.value;save();if(e.target.dataset.k==="nome")nomesMudaram();try{esRecarregar()}catch(_){}});
const nomesMudaram=debounce(()=>{renderMods();renderGrid()},300);
$("#tbProfs").addEventListener("click",e=>{if(e.target.hasAttribute("data-profmais")){PROF_N+=500;renderProfs();return}if(!e.target.hasAttribute("data-del"))return;const id=e.target.closest("tr").dataset.id;
  cfg.profs=cfg.profs.filter(x=>x.id!==id);cfg.mods.forEach(m=>{if(m.profId===id)m.profId=""});for(const k in cfg.grid)if(cfg.grid[k]===id)delete cfg.grid[k];save();renderAll();toast("Formador removido (pode anular)")});
$("#profForm").addEventListener("input",()=>{$("#pFormMsg").innerHTML="";$("#pEmail").placeholder=emailAuto($("#pNome").value)||"nome.apelido@"+EMAIL_DOM});
$("#profForm").addEventListener("submit",e=>{e.preventDefault();
  const cod=$("#pCod").value.trim(),nome=$("#pNome").value.trim(),email=$("#pEmail").value.trim()||emailAuto(nome),abrev=$("#pAbrev").value.trim();
  const msg=(t,k)=>{$("#pFormMsg").innerHTML=`<div class="msg ${k}" style="margin:0 0 12px">${esc(t)}</div>`};
  if(!nome){msg("Indique o nome do formador.","bad");$("#pNome").focus();return}
  if(email&&!/^\S+@\S+\.\S+$/.test(email)){msg("O email não parece válido.","bad");$("#pEmail").focus();return}
  const dup=cfg.profs.find(p=>(cod&&norm(p.cod)===norm(cod))||(email&&norm(p.email)===norm(email)));
  if(dup){msg(`Já existe um formador com ${cod&&norm(dup.cod)===norm(cod)?"esse código":"esse email"}: ${dup.nome}.`,"bad");return}
  cfg.profs.push({id:uid(),cod,nome,email,abrev});cfg.profs.sort(cmpProf);save();renderAll();
  msg(`${nome} adicionado(a).`,"ok");$("#profForm").reset();$("#pCod").focus();});
{let h=null;$("#profFilter").addEventListener("input",()=>{PROF_N=200;clearTimeout(h);h=setTimeout(renderProfs,120)})}
$("#profImport").onclick=()=>{
  const lines=$("#profBulk").value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return;
  ponto("Antes de colar uma lista de formadores");
  let add=0,upd=0,bad=0;
  for(const l of lines){
    const em=(l.match(/[^\s;,<>"]+@[^\s;,<>"]+\.[^\s;,<>"]+/)||[])[0]||"";
    if(!em&&(/e-?mail|c[oó]digo/i.test(l)||/^(nome|name|professor(es)?|formador(es)?)$/i.test(l.trim())))continue; // linha de cabeçalho
    let parts=l.replace(em,"").replace(/[<>"]/g,"").split(/\t|;|,/).map(x=>x.trim()).filter(Boolean);
    let cod="";if(parts.length>=2&&/^[\w.\-\/]{1,12}$/.test(parts[0])&&/\d/.test(parts[0])){cod=parts.shift()}
    let nm=parts.join(" ").trim();
    if(!nm&&!em){bad++;continue}
    if(!nm)nm=em.split("@")[0];
    const ex=cfg.profs.find(p=>(cod&&p.cod&&norm(p.cod)===norm(cod))||(em&&norm(p.email)===norm(em))||norm(p.nome)===norm(nm));
    if(ex){if(em)ex.email=em;if(cod)ex.cod=cod;if(nm)ex.nome=ex.nome||nm;if(!ex.email)ex.email=emailAuto(ex.nome);upd++}else{cfg.profs.push({id:uid(),cod,nome:nm,email:em||emailAuto(nm)});add++}
  }
  cfg.profs.sort(cmpProf);
  save();renderAll();
  $("#profMsg").textContent=`${add} adicionado(s), ${upd} atualizado(s)${bad?`, ${bad} linha(s) ignorada(s)`:""}.`;
  if(add||upd)$("#profBulk").value="";
};

/* ===================== 0.9.48: listas preguiçosas (1000 formadores) =====================
   Os menus de formador/turma em tabelas grandes só têm a opção escolhida até se tocar neles; aí enchem-se de uma vez (lista em cache).
   Com 1000 formadores e 60 turmas, a página de Turmas passava de dezenas de milhares de opções para uma por linha. */
const LZ={first:[],cache:{}};
function lzLista(kind){const k=kind+":"+cfgRev+":"+(kind==="turma"||kind==="tcod"?(anoAtivo()||{}).id:"");const c=LZ.cache[kind];if(c&&c.k===k)return c.h;let h="";
  if(kind==="prof")h=cfg.profs.slice().sort(cmpProf).map(p=>`<option value="${p.id}">${esc(p.nome||"(sem nome)")}${p.cod?` (${esc(p.cod)})`:""}</option>`).join("");
  else if(kind==="tcod")h=[...new Set(turmasDoAno().map(t=>t.cod))].map(c=>`<option>${esc(c)}</option>`).join("");
  else if(kind==="turma"){const a=anoAtivo();h=escData().turmas.slice().sort((x,y)=>COLL_PTN.compare(String(x.cod),String(y.cod))).map(t=>`<option value="${t.id}">${esc(t.cod)}${turmaNoAno(t,a)?"":" (outro ano)"}</option>`).join("")}
  LZ.cache[kind]={k,h};return h}
function lzOpts(kind,sel,first){first=first??(kind==="turma"?`<option value="">— sem turma —</option>`:`<option value="">— escolher —</option>`);let i=LZ.first.indexOf(first);if(i<0){LZ.first.push(first);i=LZ.first.length-1}
  let lbl="";if(sel){if(kind==="prof"){const p=cfg.profs.find(x=>x.id===sel);lbl=p?(p.nome||"(sem nome)")+(p.cod?` (${p.cod})`:""):"(formador apagado)"}else{const t=escData().turmas.find(x=>x.id===sel);lbl=t?t.cod+(turmaNoAno(t,anoAtivo())?"":" (outro ano)"):"(turma apagada)"}}
  return first.replace("<option",`<option data-lzk="${kind}" data-lzf="${i}"`)+(sel?`<option value="${esc(sel)}" selected>${esc(lbl)}</option>`:"")}
function lzEncher(sel){if(!sel||sel.dataset.lzok)return;const o=sel.querySelector("option[data-lzk]");if(!o)return;sel.dataset.lzok=1;
  const v=sel.value,kind=o.dataset.lzk,f=LZ.first[+o.dataset.lzf]||"",lab=v?(sel.selectedOptions[0]||{}).textContent:"";sel.innerHTML=f+lzLista(kind);
  if(v&&![...sel.options].some(x=>x.value===v))sel.insertAdjacentHTML("beforeend",`<option value="${esc(v)}">${esc(lab||"(apagado)")}</option>`);sel.value=v}
["pointerdown","mousedown","touchstart","focusin","keydown"].forEach(ev=>document.addEventListener(ev,e=>{const t=e.target;if(t&&t.tagName==="SELECT"&&!t.dataset.lzok)lzEncher(t)},true));
function profOpts(sel,first){return (first??`<option value="">— escolher —</option>`)+cfg.profs.slice().sort(cmpProf).map(p=>`<option value="${p.id}" ${p.id===sel?"selected":""}>${esc(p.nome||"(sem nome)")}${p.cod?` (${esc(p.cod)})`:""}</option>`).join("")}

/* ---------- módulos do(s) ano(s) letivo(s) da análise carregada ---------- */
let _atv=null,_atvK="";
function ativos(){const k=filesRev+"|"+cfgRev;if(_atv&&_atvK===k)return _atv;
  const idx=getIdx();
  _atv=!idx.recs.length?cfg.mods:cfg.mods.filter(m=>m.ano?idx.anos.has(m.ano):(idx.anos.size===0||idx.pick(segs(m.pasta),"folders").length>0));
  _atvK=k;return _atv}
// módulos antigos (sem ano letivo): ficam associados ao ano da análise onde as suas pastas existem
function adotar(){const idx=getIdx();if(!idx.anos.size)return 0;let n=0;
  for(const m of cfg.mods){if(m.ano)continue;const ss=segs(m.pasta);if(!ss.length)continue;
    for(const [ano,dir] of idx.anos){if(idx.pick([norm(dir),...ss],"folders").length){m.ano=ano;m.anoDir=dir;m.pasta=dir+" / "+m.pasta;n++;break}}}
  if(n){cfgRev++;const s=JSON.stringify(cfg);lastJSON=s;try{localStorage.setItem(KEY,s)}catch(e){}}
  return n}
const anoRef=()=>[...getIdx().anos.keys()].sort().join(",");

/* ---------- grelha turma × disciplina ---------- */
function gridRows(){
  const map=new Map();
  for(const m of ativos()){const k=gridKey(m);let r=map.get(k);if(!r)map.set(k,r={k,turma:m.turma,disc:m.disc,ano:m.ano||"",ref:m,mods:[]});r.mods.push(m)}
  return [...map.values()].sort((a,b)=>a.ano.localeCompare(b.ano)||COLL_PTN.compare(a.turma,b.turma)||COLL_PTN.compare(a.disc,b.disc));
}
function gridRowHTML(r){let html="";
    const exc=r.mods.filter(isExc),g=gridGet(r.ref),gp=g?"":planoProf(r.ref);
    const ab=GOPEN.has(r.k);
    html+=`<div class="grow2${g||gp?"":" vazio"}${ab?" open":""}" data-g="${esc(r.k)}"${gp?` title="Formador tirado do Plano Curricular da turma — escolha outro para mudar"`:""}><span>${esc(r.disc||"(sem disciplina)")}</span><button class="n gopen" data-gopen title="Ver os módulos e atribuir cada um a um formador">${r.mods.length} ${r.mods.length===1?"módulo":"módulos"} <span class="car">▾</span></button>
      <select data-grid>${lzOpts("prof",g,gp?`<option value="">↳ do Plano Curricular: ${esc(profName(gp))}</option>`:`<option value="">— sem formador —</option>`)}</select>
      <span class="exc">${exc.length?`<a href="#" data-excf="${esc(r.turma+" "+discShort(r.disc))}">${exc.length} exceção${exc.length===1?"":"ões"}: ${esc([...new Set(exc.map(m=>profName(m.profId)))].join(", "))}</a>`:""}</span></div>`;
    if(ab)html+=`<div class="gsub">${r.mods.slice().sort((a,b)=>COLL_PTN.compare(String(a.cod),String(b.cod))).map(m=>`<div class="gsubr${isExc(m)?" exc":""}" data-mid="${m.id}"><span>${esc(modTitle(m))}</span>
      <select data-mprof>${lzOpts("prof",m.profId||"",`<option value="">↳ o da disciplina (${esc(profName(g||gp)||"sem formador")})</option>`)}</select></div>`).join("")}</div>`;
  return html}
function renderGrid(){
  const q=norm($("#gFilter").value),only=$("#gEmpty").checked,gp=$("#gProf"),pf=gp.value;
  gp.innerHTML=profOpts(pf,`<option value="">Todos os formadores</option>`);gp.value=cfg.profs.some(p=>p.id===pf)?pf:"";const pid=gp.value;
  const all=gridRows(),multi=new Set(all.map(r=>r.ano)).size>1;
  const rows=all.filter(r=>(!q||q.split(" ").every(w=>norm(r.turma+" "+r.disc+" "+r.ano+" "+profName(gridEf(r.ref))).includes(w)))&&(!only||!gridEf(r.ref))&&(!pid||gridEf(r.ref)===pid||r.mods.some(m=>profOf(m)===pid)));
  let html="",last=null;
  for(const r of rows){
    const tk=r.ano+"|"+r.turma;
    if(tk!==last){html+=`<div class="gturma">${esc(r.turma||"(sem turma)")}${multi&&r.ano?` <span class="tag" style="background:#eef1f5;color:#4a5260">${esc(r.ano)}</span>`:""}</div>`;last=tk}
    html+=gridRowHTML(r);
  }
  const sem=all.filter(r=>!gridEf(r.ref)).length,doPlano=all.filter(r=>!gridGet(r.ref)&&planoProf(r.ref)).length,outros=cfg.mods.length-ativos().length,anos=[...getIdx().anos.keys()].sort();
  $("#anoInfo").innerHTML=anos.length?`Ano letivo da análise carregada: <b>${esc(anos.join(", "))}</b>${outros?` · ${outros} módulo(s) de outros anos letivos estão guardados, mas não aparecem aqui nem no relatório`:""}`:(outros?`${outros} módulo(s) de outras análises não aparecem aqui`:"");
  $("#grid").innerHTML=(all.length?`<p class="hint" id="gridRes">${all.length} disciplinas em ${new Set(all.map(r=>r.ano+"|"+r.turma)).size} turmas · ${sem} sem formador${doPlano?` · ${doPlano} com o formador do Plano Curricular`:""}</p>`:"")+(html||`<p class="hint">${all.length?"Nada corresponde ao filtro.":"Ainda sem módulos nesta análise: carregue a listagem da Box e clique em “Detetar módulos e UFCD”."}</p>`);
}

/* 0.9.85: escolher o formador na grelha é imediato — troca-se só a linha; gravar, o resumo, os Módulos e os Formadores vêm a seguir, sem prender o menu */
function gridTrocarLinha(k){const el=[...document.querySelectorAll("#grid [data-g]")].find(x=>x.dataset.g===k);const r=gridRows().find(x=>x.k===k);if(!el||!r)return;
  const nx=el.nextElementSibling,sub=nx&&nx.classList.contains("gsub")?nx:null,foc=document.activeElement&&el.contains(document.activeElement)?"[data-grid]":null;
  const t=document.createElement("div");t.innerHTML=gridRowHTML(r);if(sub)sub.remove();el.replaceWith(...t.childNodes);
  if(foc){const n=[...document.querySelectorAll("#grid [data-g]")].find(x=>x.dataset.g===k);const sl=n&&n.querySelector(foc);if(sl)sl.focus({preventScroll:true})}}
let GRID_H=0,GRID_SUJO={mods:0,profs:0};addEventListener("pagehide",()=>{if(GRID_H){clearTimeout(GRID_H);GRID_H=0;try{save()}catch(e){}}});
function gridDepois(){clearTimeout(GRID_H);GRID_H=setTimeout(()=>{save();
  try{const all=gridRows(),sem=all.filter(r=>!gridEf(r.ref)).length,doPlano=all.filter(r=>!gridGet(r.ref)&&planoProf(r.ref)).length,el=$("#gridRes");
    if(el)el.textContent=`${all.length} disciplinas em ${new Set(all.map(r=>r.ano+"|"+r.turma)).size} turmas · ${sem} sem formador${doPlano?` · ${doPlano} com o formador do Plano Curricular`:""}`;
    if($("#gEmpty").checked||$("#gProf").value)renderGrid()}catch(e){}
  GRID_SUJO.mods=1;GRID_SUJO.profs=1;const idle=window.requestIdleCallback||(f=>setTimeout(f,200));
  idle(()=>{if(GRID_SUJO.mods){GRID_SUJO.mods=0;try{renderMods()}catch(e){}}if(GRID_SUJO.profs&&curTab==="prof"){GRID_SUJO.profs=0;try{renderProfs()}catch(e){}}})},250)}
$("#gFilter").addEventListener("input",debounce(()=>renderGrid(),140));$("#gEmpty").addEventListener("change",renderGrid);$("#gProf").addEventListener("change",renderGrid);
$("#grid").addEventListener("change",e=>{if(e.target.matches("[data-mprof]")){const m=cfg.mods.find(x=>x.id===e.target.closest("[data-mid]").dataset.mid);if(!m)return;
    m.profId=e.target.value===gridEf(m)?"":e.target.value;gridTrocarLinha(gridKey(m));gridDepois();toast(m.profId?"Módulo atribuído a "+profName(m.profId)+" (exceção)":"O módulo volta a seguir a disciplina");return}
  if(!e.target.matches("[data-grid]"))return;const k=e.target.closest("[data-g]").dataset.g,v=e.target.value;
  const row=gridRows().find(r=>r.k===k);if(!row)return;const leg=legKey(row.ref);
  if(v)cfg.grid[k]=v;else if(k!==leg&&cfg.grid[leg])cfg.grid[k]="";else delete cfg.grid[k];
  row.mods.forEach(m=>{if(m.profId===v)m.profId=""}); // deixa de ser exceção se coincidir
  gridTrocarLinha(k);gridDepois()});
$("#grid").addEventListener("click",e=>{const o=e.target.closest("[data-gopen]");if(o){const k=o.closest("[data-g]").dataset.g;GOPEN.has(k)?GOPEN.delete(k):GOPEN.add(k);renderGrid();return}
  const a=e.target.closest("[data-excf]");if(!a)return;e.preventDefault();$("#modFilter").value="!exc "+a.dataset.excf;renderMods();$("#tbMods").scrollIntoView({behavior:"smooth",block:"start"})});

/* ---------- lista de módulos (exceções) ---------- */
function modVisible(m){const q=norm($("#modFilter").value);if(!q)return true;
  let rest=q;const noProf=rest.includes("!prof"),exc=rest.includes("!exc");rest=rest.replace("!prof","").replace("!exc","").trim();
  if(noProf&&profOf(m))return false;if(exc&&!isExc(m))return false;
  const hay=norm([m.turma,m.disc,m.cod,desigOf(m),m.pasta,profName(profOf(m))].join(" "));
  return rest.split(" ").filter(Boolean).every(w=>hay.includes(w));}
function renderMods(){
  $("#bulkProf").innerHTML=profOpts("",`<option value="">— escolher —</option><option value="__grid">↩ segue a grelha (desfazer exceções)</option>`);
  const atv=ativos(),vis=atv.filter(modVisible);
  $("#detMsg").textContent=atv.length?`${atv.length} módulos · ${atv.filter(m=>!profOf(m)).length} sem formador · ${atv.filter(isExc).length} exceções`:"";
  MODS_N=MODS_N||100;EXC_ABRE=EXC_ABRE||new Set();$("#tbMods").innerHTML=vis.slice(0,MODS_N).map(m=>{const g=gridEf(m),exc=isExc(m),segue=!m.profId&&!EXC_ABRE.has(m.id);
    return `<div class="mcard${profOf(m)?"":" noprof"}${exc?" exc":""}" data-id="${m.id}">
   <label class="f-nome"><span>Módulo / UFCD${exc?` <span class="tag exc">exceção</span>`:""}</span><input type="text" data-k="cod" value="${esc(m.cod)}"></label>
   <label class="f-turma"><span>Turma · disciplina</span><input type="text" value="${esc(m.turma+" · "+m.disc)}" title="${esc(m.turma+" · "+m.disc)}" disabled></label>
   <div class="f-prof"><span>Formador</span><div class="profrow">${segue?`<label class="chip tog" title="Desligue para escolher outro formador só para este módulo (exceção)"><input type="checkbox" data-segue checked> Segue a grelha</label><select disabled title="Formador da grelha"><option>${g?esc(profName(g)):"sem formador"}</option></select>`:`<label class="chip tog" title="Ligue para o módulo voltar a seguir o formador da grelha${g?" ("+esc(profName(g))+")":""}"><input type="checkbox" data-segue> Segue a grelha</label><select data-k="profId">${lzOpts("prof",m.profId||"",`<option value="">— escolher —</option>`)}</select>`}</div></div>
   <button class="x f-del" title="Remover módulo" data-del>×</button>
   <label class="f-pasta"><span>Designação</span><input type="text" data-des value="${esc(desigOf(m))}" placeholder="ex.: Probabilidade"></label>
   <div class="f-docs"><span>Pastas: ${esc(m.pasta)}</span></div>
  </div>`}).join("")+(vis.length>MODS_N?`<div style="text-align:center;margin:8px 0"><span class="hint" style="margin:0 10px 0 0">A mostrar ${MODS_N} de ${vis.length} (use o filtro para encontrar um módulo).</span><button class="b s" type="button" data-modmais>Mostrar mais ${Math.min(100,vis.length-MODS_N)}</button></div>`:"")||`<p class="hint">${atv.length?"Nenhum módulo corresponde ao filtro.":"Ainda sem módulos nesta análise."}</p>`;
  const bm=$("#tbMods").querySelector("[data-modmais]");if(bm)bm.onclick=()=>{MODS_N+=100;renderMods()};
}
var EXC_ABRE=EXC_ABRE||new Set(); // 0.9.103: módulos com «Segue a grelha» desligado mas ainda sem formador escolhido
var MODS_N=100; // 0.9.86: 100 cartões de cada vez (eram 300 de uma vez, ~9000 elementos)
$("#modFilter").addEventListener("input",debounce(()=>{MODS_N=100;renderMods()},140));
$("#bulkAssign").onclick=()=>{const pid=$("#bulkProf").value;if(!pid){toast("Escolha um formador");return}
  const vis=ativos().filter(modVisible);if(!vis.length)return;
  ponto(`Antes de mudar o formador de ${vis.length} módulo(s)`);
  vis.forEach(m=>{m.profId=pid==="__grid"?"":(pid===gridEf(m)?"":pid)});save();renderAll();
  toast(pid==="__grid"?`${vis.length} módulo(s) voltaram a seguir a grelha`:`${vis.length} módulo(s) mudados`)};
const modId=m=>(m.ano||"")+"|"+norm(m.turma)+"|"+discCode(m.disc)+"|"+modKey(m.cod);
function detetar(){
  // só procura módulos nas secções usadas pelos documentos exigidos (ex.: 006, 007, 008, 012); ignora as pastas dos formandos
  const idx=getIdx();
  const secs=[]; // 0.9.97: procura em todas as secções (antes só nas dos «documentos exigidos»)
  const found=new Map();
  for(const rec of idx.recs){const comps=rec.r,nc=rec.n;
    if(secs.length&&!secs.some(s=>nc.some(c=>segMatch(c,s))))continue;
    if(nc.some(c=>/^0*3(\.\d+)*\s*-\s*formandos/.test(c)||c==="formandos"))continue; // 003 - Formandos (dados dos formandos); «008.1 - Formandos» tem os módulos
    for(let i=1;i<comps.length;i++){
      let disc=null,mod=null;
      if(isDisc(comps[i-1])){disc=comps[i-1];mod=comps[i]}else if(isModName(comps[i])&&!isDisc(comps[i])){disc=comps[i-1];mod=comps[i]}
      if(!mod)continue;
      const turma=comps.slice(0,i).find(isTurma);if(!turma)break; // 0.9.97: só dentro da pasta de uma turma
      const anoDir=comps.slice(0,i).find(c=>anoDe(c))||"";
      const key=anoDe(anoDir)+"|"+norm(turma)+"|"+discCode(disc)+"|"+modKey(mod);
      if(!found.has(key))found.set(key,{turma,disc,mod,anoDir});break;}}
  return found}
$("#detect").onclick=()=>{
  if(!files.length&&!folders.length){$("#detMsg").textContent="Carregue primeiro a listagem da Box em Análise.";return}
  adotar();
  const found=detetar(),have=new Set(cfg.mods.map(modId));
  const novos=[...found.entries()].filter(([k])=>!have.has(k)).map(([,v])=>v);
  if(novos.length)ponto(`Antes de detetar ${novos.length} módulo(s)`);
  for(const v of novos){const m={id:uid(),nome:"",turma:v.turma,disc:v.disc,cod:v.mod,ano:anoDe(v.anoDir),anoDir:v.anoDir,profId:"",docs:cfg.docTypes.map(d=>d.id)};m.pasta=pastaDe(m);cfg.mods.push(m)}
  const sk=m=>(m.ano||"")+"|"+m.turma+"|"+m.disc+"|"+m.cod;
  cfg.mods.sort((a,b)=>COLL_PTN.compare(sk(a),sk(b)));
  save();renderAll();toast(novos.length?`${novos.length} módulo(s)/UFCD novos detetados (pode anular)`:"Nenhum módulo novo encontrado");
  verificarFundo();
};
$("#tbMods").addEventListener("input",e=>{const tr=e.target.closest("[data-id]");if(!tr)return;const m=cfg.mods.find(x=>x.id===tr.dataset.id);
  if(e.target.dataset.doc){const id=e.target.dataset.doc;if(e.target.checked){if(!m.docs.includes(id))m.docs.push(id)}else m.docs=m.docs.filter(x=>x!==id);e.target.parentElement.classList.toggle("on",e.target.checked);save();return}
  if(e.target.hasAttribute("data-des")){const k=discCode(m.disc)+"|"+modKey(m.cod);if(e.target.value.trim())cfg.desig[k]=e.target.value.trim();else delete cfg.desig[k];save();return}
  const k=e.target.dataset.k;if(!k)return;
  if(k==="profId"){if(!e.target.value)return;m.profId=e.target.value===gridEf(m)?"":e.target.value;EXC_ABRE.delete(m.id);save();renderMods();renderGrid();renderProfs();
    toast(m.profId?"Módulo atribuído a "+profName(m.profId)+" (exceção)":"É o formador da grelha — o módulo volta a seguir a grelha");return}
  m[k]=e.target.value;if(k==="cod")m.pasta=pastaDe(m);save();});
// 0.9.103: interruptor «Segue a grelha» em cada módulo
$("#tbMods").addEventListener("change",e=>{if(!e.target.hasAttribute("data-segue"))return;const tr=e.target.closest("[data-id]");const m=tr&&cfg.mods.find(x=>x.id===tr.dataset.id);if(!m)return;
  if(e.target.checked){EXC_ABRE.delete(m.id);const tinha=!!m.profId;m.profId="";if(tinha){save();renderGrid();renderProfs()}renderMods();if(tinha)toast("O módulo volta a seguir a grelha");return}
  EXC_ABRE.add(m.id);renderMods();const s=$("#tbMods").querySelector(`[data-id="${m.id}"] select[data-k="profId"]`);if(s){s.focus();try{s.showPicker&&s.showPicker()}catch(_){}}});
$("#tbMods").addEventListener("click",e=>{if(!e.target.hasAttribute("data-del"))return;const id=e.target.closest("[data-id]").dataset.id;cfg.mods=cfg.mods.filter(x=>x.id!==id);save();renderAll();toast("Módulo removido (pode anular)")});
$("#addMod").onclick=()=>{const r=gridRows()[0],idx=getIdx(),a=[...idx.anos][0]||["",""];
  const m={id:uid(),nome:"",turma:r?r.turma:"Turma",disc:r?r.disc:"0000 - Disciplina",cod:"Novo módulo",ano:r?r.ano:a[0],anoDir:r?(r.ref.anoDir||""):a[1],profId:"",docs:cfg.docTypes.map(d=>d.id)};
  m.pasta=pastaDe(m);cfg.mods.unshift(m);save();$("#modFilter").value="";renderAll()};

/* ---------- Catálogo Nacional de Qualificações (catalogo.snq.gov.pt) — só leitura ---------- */
const SNQ="https://bocatalogo.snq.gov.pt/webapi/api",SNQ_REP="https://bocatalogo.snq.gov.pt/reports//TecnologicaHtml";
const cursoDe=t=>String(t||"").replace(/\(\s*\d{2,4}\s*[-\/]\s*\d{2,4}\s*\)/,"").trim().replace(/^[a-z]?\d{1,4}[a-z]?\s*[-–:]?\s+/i,"").trim();
const inicioDe=t=>{const m=String(t||"").match(/\(\s*(\d{2,4})\s*[-\/]/);if(!m)return null;let y=+m[1];return y<100?y+2000:y};
const semTecnico=n=>norm(n).replace(/^tecnico\/?a?\s*(especialista\s*)?(de|em|do|da)?\s*/,"").replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim();
let _snqIx=null,_snqRev=-1;
function snqDesig(m){if(_snqRev!==cfgRev||!_snqIx){_snqIx=new Map();_snqRev=cfgRev;
    for(const k in cfg.snq||{})for(const it of cfg.snq[k].itens||[])_snqIx.set(k+"|"+modKey(it.cod),it.nome)}
  return _snqIx.get(norm(m.turma)+"|"+modKey(m.cod))||""}
async function snqProcura(nome){const out=[],vistos=new Set();
  for(const ex of[false,true]){const r=await fetch(SNQ+"/qualificacoes/searchSite",{method:"POST",headers:{"Content-Type":"application/json"},
      body:JSON.stringify({currentPage:1,itemsPerPage:50,codigo:"",designacao:nome,areasFormacaoId:[],conselhosSetoriaisId:[],nivelQEQ:[],rvcc:false,adaptada:false,baseadoEmRA:false,regulamentada:false,outrosReferencias:false,excluida:ex,excluidasId:ex?1:0})});
    if(!r.ok)throw new Error("o catálogo respondeu "+r.status);const j=await r.json();
    for(const it of j.items||[])for(const d of it.details||[])if(!vistos.has(d.qualificacoesVersoesId)){vistos.add(d.qualificacoesVersoesId);out.push({cod:it.codigo,nivel:it.nivel,id:d.qualificacoesVersoesId,nome:d.designacao,conceito:d.conceito})}}
  return out}
function snqScore(curso,c){const a=semTecnico(curso),b=semTecnico(c.nome);if(a===b)return 100+(c.nivel==="4"?5:0);
  const A=new Set(a.split(" ").filter(w=>w.length>2)),B=new Set(b.split(" ").filter(w=>w.length>2));let k=0;for(const w of A)if(B.has(w))k++;
  return Math.round(k/Math.max(1,new Set([...A,...B]).size)*80)+(c.nivel==="4"?5:0)}
// componente tecnológica: UFCD/UC obrigatórias e opcionais (por bolsa) + horas de opcionais exigidas
const snqTxt=x=>String(x||"").replace(/\s+/g," ").trim();
async function snqTec(id,tipo){
  const t=await fetch(`${SNQ_REP}?preview=true&id=${id}&faq=false&tipo=${encodeURIComponent(tipo||"PP")}&tipoReport=FORMACAO`).then(r=>{if(!r.ok)throw new Error("referencial: "+r.status);return r.text()});
  const d=new DOMParser().parseFromString(t,"text/html"),out=[],vistos=new Set();let opc=false,bolsa="";
  for(const tb of d.querySelectorAll("table")){
    const hs=[...tb.querySelectorAll(":scope > thead th[colspan]")].map(x=>snqTxt(x.textContent)).filter(Boolean);
    if(hs.some(h=>/opcion/i.test(h)))opc=true;
    const b=hs.filter(h=>!/opcionais$|^forma[cç][aã]o tecnol/i.test(h));if(opc&&b.length)bolsa=b[b.length-1];
    for(const tr of tb.querySelectorAll(":scope > tbody > tr")){const c=[...tr.cells].map(x=>snqTxt(x.textContent));if(c.length<3)continue;
      if(!/^(UC\d{3,6}|\d{4,5})$/i.test(c[0])||vistos.has(c[0]))continue;vistos.add(c[0]);
      const it={cod:c[0].toUpperCase(),nome:c[2],h:/^\d+$/.test(c[3]||"")?+c[3]:null};if(opc){it.opc=true;if(bolsa&&!/^bolsa$/i.test(bolsa))it.bolsa=bolsa}out.push(it)}}
  const m=snqTxt(d.body&&d.body.textContent).match(/realizadas\s+(\d+)\s+horas\s+d[aeo]s?\s+(?:UFCD|UC)\s+opcionais/i);
  return{itens:out,opcH:m?+m[1]:null}}
async function snqReferencial(id,tipo){return(await snqTec(id,tipo)).itens}
// componentes sociocultural e científica (Cursos Profissionais), ou de base (Aprendizagem, EFA)
const SNQ_MOD={Profissional:"CP",Aprendizagem:"CA",EFA:"EFA"};
async function snqEscolar(id,mod){
  const t=await fetch(`https://bocatalogo.snq.gov.pt/reports//EscolarHtml?id=${id}&modalidade=${mod}&preview=true&diplomaId=3&dateVersionNivel2=null`).then(r=>{if(!r.ok)throw new Error("referencial escolar: "+r.status);return r.text()});
  const d=new DOMParser().parseFromString(t,"text/html"),comps=[];let C=null,G=null;
  for(const tr of d.querySelectorAll("tr")){if(tr.closest("table.footer"))continue;
    const sub=tr.querySelector("th.report-subtitle");
    if(sub){if(!C){C={nome:"Formação",grupos:[]};comps.push(C)}G={nome:snqTxt(sub.textContent),discs:[]};C.grupos.push(G);continue}
    const th=tr.querySelector("th[colspan]");
    if(th&&tr.parentElement&&tr.parentElement.tagName==="THEAD"){const n=snqTxt(th.textContent);if(n){C={nome:n,grupos:[]};comps.push(C);G=null}continue}
    if(tr.classList.contains("header")||!C)continue;
    const c=[...tr.cells].map(x=>snqTxt(x.textContent));if(c.length<3||!c[0]||/\s/.test(c[0])||!c[1]||/^c[oó]digo$/i.test(c[0]))continue;
    if(!G){G={nome:"",discs:[]};C.grupos.push(G)}
    G.discs.push({cod:c[0],nome:c[1],h:/^\d+$/.test(c[2])?+c[2]:null})}
  comps.forEach(c=>c.grupos=c.grupos.filter(g=>g.discs.length));
  const L=comps.filter(c=>c.grupos.length),k=n=>/sociocultural|de base/i.test(n)?0:/cient/i.test(n)?1:2;
  return L.sort((a,b)=>k(a.nome)-k(b.nome))}
// escolhe a versão do referencial em vigor no início da turma (setembro do ano inicial)
async function snqVersao(cands,ano){const lim=(ano||new Date().getFullYear())+"-09-01",vs=[];
  for(const c of cands){const d=await fetch(`${SNQ}/qualificacoes/qualificacoesVersoes/${c.id}/false`).then(r=>r.json());
    for(const v of d.versoes||[{qualificacoesVersoesId:c.id,dataInicio:d.dataInicio,tipoAlteracao:""}])if(v.tipoAlteracao!=="EXC")vs.push({id:v.qualificacoesVersoesId,data:String(v.dataInicio||"").slice(0,10),conceito:d.conceito||c.conceito,qual:c})}
  vs.sort((a,b)=>b.data.localeCompare(a.data));return vs.find(v=>v.data&&v.data<=lim)||vs[vs.length-1]||null}
async function snqTurma(turma,forcar){const k=norm(turma),curso=cursoDe(turma),ano=inicioDe(turma);
  let cands=await snqProcura(curso);
  if(!cands.length){const w=curso.split(/\s+/).filter(x=>x.length>2);if(w.length>1)cands=await snqProcura(w.slice(0,2).join(" "))}
  cands.forEach(c=>c.sc=snqScore(curso,c));cands.sort((a,b)=>b.sc-a.sc);
  let esc=forcar?cands.filter(c=>c.cod===forcar):[];
  if(!esc.length&&cands.length){const top=cands[0],nb=semTecnico(top.nome);esc=cands.filter(c=>semTecnico(c.nome)===nb&&c.nivel===top.nivel);if(!esc.length)esc=[top]}
  const r={curso,ano,cands:cands.slice(0,12).map(({cod,nivel,id,nome,conceito})=>({cod,nivel,id,nome,conceito})),t:Date.now(),forcar:forcar||""};
  if(esc.length){const v=await snqVersao(esc,ano);if(v){r.qual={cod:v.qual.cod,nome:v.qual.nome,nivel:v.qual.nivel,id:v.id,data:v.data,conceito:v.conceito};const T=await snqTec(v.id,v.conceito);r.itens=T.itens;r.opcH=T.opcH}}
  (cfg.snq=cfg.snq||{})[k]=r;return r}
function turmasSNQ(){return [...new Set(ativos().map(m=>m.turma).filter(isTurma))].sort((a,b)=>COLL_PTN.compare(a,b))}
function renderSNQ(){const el=$("#snqList");if(!el)return;const T=turmasSNQ();
  if(!T.length){el.innerHTML=`<p class="hint">Ainda não há turmas no formato <code>A01 - Nome do curso (25/28)</code> nesta análise.</p>`;return}
  // 0.9.86: "com pasta na Box" conta as pastas que existem mesmo na análise (e não só os módulos já detetados em Atribuições)
  const PT=new Map();for(const rec of getIdx().recs){const c=rec.n[rec.n.length-1];if(!isModLike(c))continue;const tu=rec.n.find(x=>isTurma(x));if(!tu)continue;const k=(turmaCod(tu)||tu).toLowerCase()+"|"+turmaAnos(tu);let S=PT.get(k);if(!S)PT.set(k,S=new Set());S.add(modKey(c))}
  el.innerHTML=T.map(t=>{const r=(cfg.snq||{})[norm(t)],mods=ativos().filter(m=>m.turma===t);
    if(!r)return `<div class="snq"><div class="snqh"><b>${esc(t)}</b><span class="hint" style="margin:0">ainda não cruzado</span></div></div>`;
    const tem=new Set(mods.map(m=>modKey(m.cod)));{const nt=norm(t),S=PT.get((turmaCod(nt)||nt).toLowerCase()+"|"+turmaAnos(nt));if(S)S.forEach(k=>tem.add(k))}const todos=r.itens||[],cu=cursoDaTurma(t),escO=cu&&Array.isArray(cu.opcEsc)&&cu.opcEsc.length?new Set(cu.opcEsc):null;
    // as opcionais só contam como em falta se a escola as escolheu (Escola › Cursos); sem escolha, contam só as que já têm pasta
    const it=todos.filter(i=>!i.opc||(escO?escO.has(i.cod):tem.has(modKey(i.cod)))),na=it.filter(i=>tem.has(modKey(i.cod))),sem=it.filter(i=>!tem.has(modKey(i.cod))),nOpc=todos.filter(i=>i.opc).length;
    const fora=mods.filter(m=>/^(uc)?\d{4,}$/.test(modKey(m.cod))&&!todos.some(i=>modKey(i.cod)===modKey(m.cod)));
    return `<div class="snq" data-snq="${esc(t)}"><div class="snqh"><b>${esc(t)}</b>
      ${r.qual?`<a href="https://catalogo.snq.gov.pt/qualificacoesDetalhe/${r.qual.id}" target="_blank" rel="noopener">${esc(r.qual.nome)}</a><span class="tag" style="background:#eef1f5;color:#4a5260">${esc(r.qual.cod)} · nível ${esc(r.qual.nivel||"?")} · ${r.qual.conceito==="RA"?"UC":"UFCD"} · referencial de ${esc(r.qual.data)}</span>`:`<span class="tag bad">não encontrado no catálogo</span>`}
      <span class="grow"></span>${r.cands&&r.cands.length>1?`<select data-snqpick><option value="">outra qualificação…</option>${r.cands.map(c=>`<option value="${esc(c.cod)}">${esc(c.nome)} (${esc(c.cod)}, nível ${esc(c.nivel)})</option>`).join("")}</select>`:""}</div>
      ${r.qual?`<p class="hint" style="margin:6px 0 0"><b>${it.length}</b> ${r.qual.conceito==="RA"?"UC":"UFCD"} no referencial · <b>${na.length}</b> com pasta na Box · <b>${sem.length}</b> sem pasta${fora.length?` · <b>${fora.length}</b> pasta(s) na Box fora do referencial`:""}${nOpc?` · ${escO?`opcionais escolhidas pela escola: <b>${escO.size}</b>`:`opcionais ainda por escolher em Escola › Cursos (${nOpc} na bolsa)`}`:""}</p>
      ${sem.length?`<details><summary class="hint" style="cursor:pointer;margin:4px 0 0">Ver as ${sem.length} sem pasta na Box</summary><div class="snqi">${sem.map(i=>`<span><b>${esc(i.cod)}</b> ${esc(i.nome)}${i.h?` · ${i.h} h`:""}${i.opc?` <span class="tag" style="background:#eef1f5;color:#4a5260">opcional</span>`:""}</span>`).join("")}</div></details>`:""}
      ${fora.length?`<details><summary class="hint" style="cursor:pointer;margin:4px 0 0">Ver as ${fora.length} fora do referencial</summary><div class="snqi">${fora.map(m=>`<span>${esc(discShort(m.disc))} · <b>${esc(codCurto(m.cod))}</b></span>`).join("")}</div></details>`:""}`:""}</div>`}).join("")}
async function cruzarSNQ(soTurma,forcar){const T=soTurma?[soTurma]:turmasSNQ();if(!T.length){renderSNQ();return}
  const b=$("#snqGo");b.disabled=true;let n=0,f=[];ponto("Antes de cruzar com o catálogo");
  for(const t of T){$("#snqMsg").textContent=`A consultar o catálogo: ${++n} de ${T.length} — ${t}…`;
    try{await snqTurma(t,soTurma?forcar:((cfg.snq||{})[norm(t)]||{}).forcar)}catch(e){f.push(t+": "+e.message)}}
  save();renderSNQ();renderAll();b.disabled=false;
  $("#snqMsg").textContent=f.length?`Concluído com ${f.length} erro(s): ${f.join(" · ")}`:`Concluído: ${T.length} turma(s). As designações das UFCD/UC passam a vir do catálogo (as que escreveu à mão têm prioridade).`}
$("#snqGo").onclick=()=>cruzarSNQ();
$("#snqList").addEventListener("change",e=>{if(!e.target.matches("[data-snqpick]")||!e.target.value)return;cruzarSNQ(e.target.closest("[data-snq]").dataset.snq,e.target.value)});

/* ---------- designações ---------- */
$("#desImport").onclick=()=>{
  const lines=$("#desBulk").value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!lines.length)return;
  ponto("Antes de guardar designações");let n=0,bad=0;
  for(const l of lines){const p=l.split(/\t|;/).map(x=>x.trim()).filter(Boolean);
    if(/designa/i.test(l)&&p.length<=3&&!/\d/.test(p[0]||""))continue;
    if(p.length>=3){cfg.desig[discCode(p[0])+"|"+modKey(p[1])]=p.slice(2).join(" ");n++}
    else if(p.length===2){cfg.desig["*|"+modKey(p[0])]=p[1];n++}else bad++}
  save();renderAll();$("#desMsg").textContent=`${n} designação(ões) guardada(s)${bad?`, ${bad} linha(s) ignorada(s)`:""}.`;if(n)$("#desBulk").value="";
};
function renderAll(){renderDocs();renderProfs();renderGrid();renderMods();renderSNQ();undoUI()}


/* ---------- CSV ---------- */
function parseCSV(text){
  text=text.replace(/^﻿/,"");
  const first=text.split(/\r?\n/)[0]||"";
  const cnt=ch=>first.split(ch).length-1;
  const sep=[["\t",cnt("\t")],[";",cnt(";")],[",",cnt(",")]].sort((a,b)=>b[1]-a[1])[0];
  const d=sep[1]>0?sep[0]:"\u0000";
  const rows=[];let row=[],f="",q=false;
  for(let i=0;i<text.length;i++){const c=text[i];
    if(q){if(c==='"'){if(text[i+1]==='"'){f+='"';i++}else q=false}else f+=c}
    else if(c==='"'&&f==="")q=true;
    else if(c===d){row.push(f);f=""}
    else if(c==="\n"||c==="\r"){if(c==="\r"&&text[i+1]==="\n")i++;row.push(f);f="";if(row.some(x=>x!==""))rows.push(row);row=[]}
    else f+=c;}
  row.push(f);if(row.some(x=>x!==""))rows.push(row);
  return rows;
}
function guess(head,pats){const h=head.map(norm);for(const p of pats){const i=h.findIndex(x=>x===p);if(i>=0)return i}for(const p of pats){const i=h.findIndex(x=>x.includes(p));if(i>=0)return i}return -1}
function ingest(text,source){
  const rows=parseCSV(text);if(!rows.length){boxMsg("O ficheiro está vazio.","bad");return}
  const looksHeader=rows[0].some(c=>/path|caminho|name|nome|file|ficheiro|item|pasta|folder/i.test(c))&&rows[0].every(c=>!/[\/\\]/.test(c));
  if(!looksHeader&&rows[0].length===1)ingestRows(["Caminho"],rows,source);
  else if(!looksHeader)ingestRows(rows[0].map((_,i)=>"Coluna "+(i+1)),rows,source);
  else ingestRows(rows[0],rows.slice(1),source);
}
function ingestRows(head,rows,source){
  rawHead=head;rawRows=rows;
  const iPath=guess(rawHead,["path","full path","caminho","item path","folder path","parent path","pasta","caminho completo","caminho"]);
  const iName=guess(rawHead,["item name","file name","name","nome","ficheiro","nome do ficheiro"]);
  const iDate=guess(rawHead,["modified_at","modified at","modified","content modified","data de modificacao","modificado","updated","created"]);
  const iType=guess(rawHead,["item type","type","tipo"]);
  const opt=(sel,none)=>(none?`<option value="-1">— nenhuma —</option>`:"")+rawHead.map((h,i)=>`<option value="${i}" ${i===sel?"selected":""}>${esc(h)}</option>`).join("");
  $("#colPath").innerHTML=opt(iPath>=0?iPath:0,false);
  $("#colName").innerHTML=opt(iName!==iPath?iName:-1,true);
  $("#colDate").innerHTML=opt(iDate,true);
  $("#colType").innerHTML=opt(iType,true);
  $("#colPick").style.display="block";
  applyCols();
  boxMsg(`Lido ${source}: ${rawRows.length} linhas. Confirme as colunas se necessário.`,"ok");
}
function applyCols(){
  const ip=+$("#colPath").value,inn=+$("#colName").value,id=+$("#colDate").value,it=+$("#colType").value;
  files=[];folders=[];
  const hx=k=>rawHead.findIndex(h=>norm(h)===k),iId=hx("id"),iSz=hx("size"),iSh=hx("sha1"),iCm=hx("cmod");
  for(const r of rawRows){
    let p=(r[ip]||"").replace(/\\/g,"/").trim(); const nm=inn>=0?(r[inn]||"").trim():"";
    if(!p&&!nm)continue;
    if(nm){const last=p.split("/").filter(Boolean).pop()||"";if(last!==nm)p=p.replace(/\/+$/,"")+"/"+nm}
    const segs=p.split("/").map(s=>s.trim()).filter(Boolean); if(!segs.length)continue;
    const name=segs[segs.length-1]; const rawDir=segs.slice(0,-1).join("/");
    const isFolder=it>=0?/folder|pasta/i.test(r[it]||""):!/\.[a-z0-9]{1,6}$/i.test(name);
    if(isFolder){folders.push(segs.join("/"));continue}
    files.push({path:segs.join("/"),rawDir,comps:segs.slice(0,-1).map(norm),name,nname:norm(name),date:id>=0?(r[id]||""):"",
      fid:iId>=0?String(r[iId]||""):"",size:iSz>=0&&r[iSz]!==""&&r[iSz]!=null?+r[iSz]:null,sha1:iSh>=0?String(r[iSh]||""):"",cmod:iCm>=0?String(r[iCm]||""):""});
  }
  lastListing=null;dadosMudaram();
}
// os ficheiros/pastas carregados mudaram: refaz o índice e atualiza o que está à vista
function dadosMudaram(){filesRev++;IDX=null;adotar();refreshAll();renderPreview()}
function renderPreview(){
  $("#previewCard").style.display=files.length?"block":"none";
  $("#previewInfo").textContent=`${files.length} ficheiro(s) prontos para comparação. Primeiros 15:`;
  $("#tbPrev").innerHTML=files.slice(0,15).map(f=>`<tr><td>${esc(f.path)}</td><td class="hm">${esc(f.date)}</td></tr>`).join("");
}
function boxMsg(t,k){$("#boxMsg").innerHTML=`<div class="msg ${k}">${esc(t)}</div>`}
$("#applyCols").onclick=()=>{applyCols();boxMsg(`${files.length} ficheiro(s) prontos. Veja o separador Relatório.`,"ok")};
$("#fileCsv").onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>ingest(r.result,`“${f.name}”`);r.readAsText(f)};
$("#parsePaste").onclick=()=>{const t=$("#csvPaste").value;if(t.trim())ingest(t,"o texto colado")};

/* ---------- matching ---------- */
// uma pasta "corresponde" se o nome for igual ou começar pelo texto indicado seguido de espaço, hífen, parêntese, ponto…
const segs=s=>String(s||"").split("/").map(norm).filter(Boolean);
// 0.9.94: um código numérico ("008", "012", "012.1.1") só corresponde ao mesmo código — "012" já não apanha "012.1.1 - Enunciados…"
// (antes a Orientação Educativa contava os enunciados); uma palavra também corresponde depois do código da pasta:
// "enunciados" = "012.1.1 - Enunciados de Avaliação", "planificacoes" = "006 - Planificações"
const SEG_COD=/^\d{2,4}(?:\.\d+)*$/,SEG_PRE=/^(\d{2,4}(?:\.\d+)*)(?:\s*[-–:.)]\s*|\s+)/;
const segIni=(c,s)=>c===s||(c.startsWith(s)&&/[\s\-(_.]/.test(c[s.length]));
function segMatch(c,s){if(c===s)return true;
  if(SEG_COD.test(s)){const m=c.match(SEG_PRE);return m?m[1]===s:false}
  if(segIni(c,s))return true;
  const m=c.match(SEG_PRE);return !!m&&segIni(c.slice(m[0].length),s)}
function allIn(comps,ss){return ss.every(s=>comps.some(c=>segMatch(c,s)))}
// 0.9.86: comparação tolerante, para não dizer que falta uma pasta que só mudou de nome ou de escrita:
// "Módulo 1" = "Módulo 01 - Nome", "UFCD 0349" = "UFCD 349 (Ambiente)", "1600 - Matemática" = "1600 - Matemática e Ciências",
// "A23 - Curso (23/26)" = "A23 - Outro nome do curso (2023-2026)", "DTP 2026.2027" = "2026-2027"
const isModLike=c=>isModName(c)||(/^\d{4,6}(?![\d])/.test(c)&&!isDisc(c));
const turmaCod=c=>(String(c).match(/^([a-z]{1,2}\d{1,3})(?![a-z0-9])/i)||[])[1];
const turmaAnos=c=>{const m=String(c).match(/\(\s*(\d{2,4})\s*[-\/.]\s*(\d{2,4})\s*\)/);return m?m[1].slice(-2)+"-"+m[2].slice(-2):""};
function flexEq(c,s){if(segMatch(c,s))return true;
  if(isModLike(s)&&isModLike(c))return modKey(s)===modKey(c);
  if(isDisc(s)&&isDisc(c))return discCode(s)===discCode(c);
  const a=anoDe(s);if(a)return a===anoDe(c);
  if(isTurma(s)&&isTurma(c)){const k=turmaCod(s);return !!k&&k.toLowerCase()===String(turmaCod(c)||"").toLowerCase()&&turmaAnos(s)===turmaAnos(c)}
  return false}
// ===== src/js/box/verificacoes.js =====
/* ---------- índice de pastas e ficheiros: o relatório deixa de percorrer tudo de cada vez ---------- */
function buildIndex(fs,fo){
  const comp=new Map(); // nome de pasta (normalizado) -> {raw, files:[], folders:[]}
  const ent=(c,raw)=>{let e=comp.get(c);if(!e){e={raw,files:[],folders:[]};comp.set(c,e)}return e};
  const nc=new Map(),nrm=s=>{let v=nc.get(s);if(v===undefined){v=norm(s);nc.set(s,v)}return v};
  const seen=new Set(),recs=[];
  const addDir=p=>{ // regista a pasta e as pastas acima dela
    if(!p||seen.has(p))return;const parts=p.split("/").map(x=>x.trim()).filter(Boolean);
    for(let i=parts.length;i>=1;i--){const q=parts.slice(0,i).join("/");if(seen.has(q))break;seen.add(q);
      const r=parts.slice(0,i),n=r.map(nrm),rec={r,n};recs.push(rec);
      for(let k=0;k<n.length;k++){if(n.indexOf(n[k])!==k)continue;ent(n[k],r[k]).folders.push(rec)}}
    seen.add(p)};
  for(const p of fo)addDir(p);
  for(const f of fs){addDir(f.rawDir);const c=f.comps;for(let k=0;k<c.length;k++){if(c.indexOf(c[k])!==k)continue;ent(c[k],c[k]).files.push(f)}}
  // um segmento escrito pelo utilizador ("008", "modulo a07") corresponde às pastas com esse nome ou que começam por ele
  const segCache=new Map();
  const matching=s=>{let r=segCache.get(s);if(!r){r=[];const e0=comp.get(s);if(e0)r.push(e0);
      for(const [c,e] of comp)if(c!==s&&segMatch(c,s))r.push(e);segCache.set(s,r)}return r};
  const pick=(ss,kind)=>{if(!ss.length)return[];let best=null,bn=Infinity;
    for(const s of ss){const m=matching(s);let n=0;for(const e of m)n+=e[kind].length;if(n<bn){bn=n;best=m}}
    if(!bn)return[];const key=kind==="files"?"comps":"n",out=[];
    if(best.length===1){for(const x of best[0][kind])if(allIn(x[key],ss))out.push(x)}
    else{const sn=new Set();for(const e of best)for(const x of e[kind]){if(sn.has(x))continue;sn.add(x);if(allIn(x[key],ss))out.push(x)}}
    return out};
  const realName=s=>{const m=matching(s);return m.length?m[0].raw:s};
  // anos letivos presentes na listagem (pastas com "2025.2026" no nome); fica a pasta com mais subpastas
  const anos=new Map(),cnt=new Map();
  for(const e of comp.values()){if(!e.folders.length)continue;const a=anoDe(e.raw);if(a&&(cnt.get(a)||0)<e.folders.length){anos.set(a,e.raw);cnt.set(a,e.folders.length)}}
  // 0.9.86: quando a pasta de um módulo não aparece pelo nome exato, procura-a pelo código (só nos casos em falta)
  let byMod=null;const flexC=new Map();
  const flex=ss=>{const key=ss.join("/");if(flexC.has(key))return flexC.get(key);let res=null;
    const last=ss[ss.length-1];
    if(last&&isModLike(last)){
      if(!byMod){byMod=new Map();for(const r of recs){const c=r.n[r.n.length-1];if(!isModLike(c))continue;const k=modKey(c);let a=byMod.get(k);if(!a)byMod.set(k,a=[]);a.push(r)}}
      const rest=ss.slice(0,-1),ok=(byMod.get(modKey(last))||[]).filter(r=>rest.every(s=>r.n.some(c=>flexEq(c,s))));
      if(ok.length){const r0=ok[0];res={ss:ss.map(s=>r0.n.find(c=>flexEq(c,s))||s),nome:r0.r[r0.r.length-1]}}}
    flexC.set(key,res);return res};
  const tem=s=>matching(s).some(e=>e.folders.length);
  return{comp,recs,pick,realName,anos,flex,tem,nFiles:fs.length};
}
function getIdx(){return IDX||(IDX=buildIndex(files,folders))}

/* ---------- verificações de qualidade: documentos vazios, falsos, trocados ou copiados ---------- */
let CT={};try{CT=JSON.parse(localStorage.getItem("boxcheck_texto")||"{}")}catch(e){} // contagens antigas (versões 0.2–0.9)
const QC=()=>cfg.qual||{};
const minPal=()=>Math.max(1,+QC().min||40);
const qOn=k=>k==="antigo"?QC()[k]===true:QC()[k]!==false; // tudo ligado por omissão, exceto a data de edição (dá muitos avisos em recursos reutilizados)
const palavras=sha1=>{const t=sha1&&TX.get(sha1);if(t)return t.w;const c=sha1&&CT[sha1];return c&&c.w!=null?c.w:null};
let TPL=lsJ("boxcheck_modelos",null)||{itens:[]}; // modelos oficiais da escola: {id, pasta, quando, itens:[{nome, sha1}]}
let REF=null;                                      // ano de referência (anterior): {rootId, pasta, shas: Map(sha1 -> caminho)}
async function carregarRef(){const id=QC().refRoot;REF=null;
  if(id){const j=await lerListagem(id);if(j){const shas=new Map();for(const x of j.itens)if(x.type!=="folder"&&x.sha1&&x.size!==0&&!shas.has(x.sha1))shas.set(x.sha1,x.path+"/"+x.name);REF={rootId:id,pasta:j.pasta,shas}}}
  refRev++}
const escRe=s=>s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
// como um módulo/UFCD costuma aparecer escrito no nome ou no texto de um documento
function modRegex(cod){
  const k=modKey(cod);let m;
  if((m=k.match(/^uc(\d+)$/)))return new RegExp("(?:^|[^a-z0-9])uc\\s*0*"+m[1]+"(?!\\d)");
  if(/^\d{4,}$/.test(k))return /^(19|20)\d\d$/.test(k)?new RegExp("ufcd\\s*(?:n\\.?\\s*[oº°]?\\.?\\s*)?0*"+k+"(?!\\d)"):new RegExp("(?:^|[^0-9])0*"+k+"(?!\\d)");
  if((m=k.match(/^([a-z]{0,2})0*(\d{1,3})$/))){
    const alt=["(?:modulos?|mod|ufcd|\\bm)\\.?\\s*(?:n\\.?\\s*[oº°]?\\.?\\s*)?"+m[1]+"\\s*0*"+m[2]+"(?!\\d)"];
    if(m[1]&&k.length>=3)alt.push("(?:^|[^a-z0-9])"+escRe(k)+"(?![a-z0-9])");
    return new RegExp(alt.join("|"))}
  return k.length>=4?new RegExp(escRe(k)):null;
}
let MENT=new Map(),MENTK=null;
function mencoes(f,t,dc,sibs){ // módulos da mesma disciplina referidos no nome ou no texto do ficheiro
  const key=f.sha1+"|"+f.nname+"|"+dc;let s=MENT.get(key);if(s)return s;
  s=new Set();const hay=f.nname+" \n "+t.n;
  for(const [mk,x] of sibs)if((x.re&&x.re.test(hay))||(x.des.length>=8&&hay.includes(x.des)))s.add(mk);
  MENT.set(key,s);return s}
function qualCtx(idx,slotOf,mods){
  const bySha=new Map(),lsh=new Map(),near=qOn("quase");
  const addL=(t,e)=>{for(const k of bandKeys(t)){let a=lsh.get(k);if(!a)lsh.set(k,a=[]);a.push(e)}};
  for(const [f,slot] of slotOf){
    if(f.sha1&&f.size!==0){let a=bySha.get(f.sha1);if(!a)bySha.set(f.sha1,a=[]);a.push({f,slot})}
    if(near){const t=f.sha1&&TX.get(f.sha1);if(t&&t.w>=60)addL(t,{f,slot,sha1:f.sha1,sg:slot.sg,sig:t.sig})}}
  const ref=REF&&!(lastListing&&lastListing.rootId===REF.rootId)?REF:null;
  if(near&&ref){const nome=ref.pasta.split("/").pop();for(const [sha,path] of ref.shas){const t=TX.get(sha);if(t&&t.w>=60)addL(t,{f:null,slot:null,sha1:sha,sg:"§ref",sig:t.sig,label:`“${nome}”: ${path.split("/").slice(-2).join("/")}`})}}
  const sib=new Map(); // disciplina -> Map(módulo -> {cod, re, des})
  for(const m of mods){const dc=discCode(m.disc),mk=modKey(m.cod);let s=sib.get(dc);if(!s)sib.set(dc,s=new Map());if(!s.has(mk))s.set(mk,{cod:m.cod,re:modRegex(m.cod),des:norm(desigOf(m))})}
  const tpls=[],tplSha=new Map();
  // 0.9.113: a comparação com os modelos oficiais foi retirada (tpls fica vazio)
  if(false)for(const i of TPL.itens||[]){tplSha.set(i.sha1,i.nome);const t=TX.get(i.sha1);if(t&&t.w>=30)tpls.push({nome:i.nome,t})}
  let inicio="";if(qOn("antigo")){inicio=QC().inicio||"";if(!/^\d{4}-\d\d-\d\d$/.test(inicio)){inicio="";if(idx.anos.size===1)inicio=[...idx.anos.keys()][0].slice(0,4)+"-07-01"}}
  return{bySha,lsh,sib,tpls,tplSha,ref,inicio};
}
// devolve null (nada a apontar), {lvl:"bad"} (não conta como entregue) ou {lvl:"warn"} (conta, mas fica "a confirmar")
// falsos positivos: o diretor confirma que um ficheiro assinalado é válido (fica ligado a esta versão do ficheiro)
const fpKey=f=>(f.fid||f.name)+"|"+(f.sha1||"");
function marcarFP(keys,on,txt){cfg.fp=cfg.fp||{};for(const k of keys){if(on)cfg.fp[k]={t:Date.now(),txt:txt||""};else delete cfg.fp[k]}save();renderAll();if(curTab==="rel")renderReport();if(curTab==="alt")renderAlt();
  toast(on?"Assinalado como falso positivo — passa a contar como entregue (pode anular)":"Anulado — o aviso volta a aparecer")}
function qualOf(f,slot,X){
  if(f.size===0)return{lvl:"bad",txt:"ficheiro vazio (0 bytes)"};
  if(f.sha1&&X.tplSha.has(f.sha1))return{lvl:"bad",txt:`é o modelo «${X.tplSha.get(f.sha1)}» por preencher (ficheiro igual ao modelo)`};
  const t0=f.sha1?TX.get(f.sha1):null,t=t0&&t0.w!=null?t0:null,w=t?t.w:palavras(f.sha1),W=[];
  if(w!=null&&w<minPal()){
    if((f.size||0)<150000)return{lvl:"bad",txt:`em branco ou quase vazio (${w} palavra${w===1?"":"s"})`};
    W.push("sem texto — pode ser um documento digitalizado")}
  if(t&&t.w>=minPal()){
    if(qOn("enchimento")){
      if(t.lorem)return{lvl:"bad",txt:"texto de enchimento (lorem ipsum)"};
      if(t.top>0.5&&t.w>=20)return{lvl:"bad",txt:"texto de enchimento (a mesma palavra repetida)"};
      if(t.rep||(t.u<0.12&&t.w>=80))W.push("texto muito repetitivo (enchimento?)")}
    if(X.tpls.length&&t.w>=30){let best=0,bt=null;for(const m of X.tpls){const s=simSig(t.sig,m.t.sig);if(s>best){best=s;bt=m}}
      if(bt&&best>=0.9&&t.w-bt.t.w<Math.max(20,bt.t.w*0.1))return{lvl:"bad",txt:`é o modelo «${bt.nome}» por preencher (${Math.round(best*100)}% igual ao modelo)`};
      if(bt&&best>=0.75)W.push(`${Math.round(best*100)}% igual ao modelo «${bt.nome}» — pouco preenchido?`)}
    if(slot){const hay=f.nname+" \n "+t.n;
      if(qOn("tipo")&&slot.T.cont.length&&!slot.T.cont.some(k=>hay.includes(k)))W.push(`o conteúdo não parece ser «${slot.T.d.nome}»`);
      if(qOn("modulo")){const dc=discCode(slot.m.disc),sibs=X.sib.get(dc);
        if(sibs&&sibs.size>1){const men=mencoes(f,t,dc,sibs);
          if(men.size&&!men.has(modKey(slot.m.cod)))W.push(`parece ser de outro módulo (${[...men].slice(0,2).map(k=>sibs.get(k).cod).join(", ")})`)}}}}
  if(slot&&f.sha1){
    if(qOn("dup")){const o=(X.bySha.get(f.sha1)||[]).find(x=>x.f!==f&&x.slot.sg!==slot.sg);
      if(o)W.push(`ficheiro igual ao de ${modLabel(o.slot.m)} › ${o.slot.T.d.nome}`)}
    if(qOn("quase")&&t&&t.w>=60){let best=0,bo=null;
      for(const k of bandKeys(t)){const arr=X.lsh.get(k);if(!arr)continue;
        for(let i=0,n=Math.min(arr.length,80);i<n;i++){const x=arr[i];if(x.f===f||x.sha1===f.sha1||x.sg===slot.sg)continue;const s=simSig(t.sig,x.sig);if(s>best){best=s;bo=x}}
        if(best>=0.97)break}
      if(bo&&best>=0.85)W.push(`texto ${Math.round(best*100)}% igual ao de ${bo.slot?`${modLabel(bo.slot.m)} › ${bo.slot.T.d.nome} (${bo.f.name})`:bo.label}`)}}
  if(f.sha1&&X.ref&&qOn("anterior")&&X.ref.shas.has(f.sha1))W.push(`mesmo ficheiro já entregue em “${X.ref.pasta.split("/").pop()}”`);
  if(X.inicio&&f.cmod&&f.cmod.slice(0,10)<X.inicio)W.push(`última edição em ${f.cmod.slice(5,7)}/${f.cmod.slice(0,4)}, antes do ano letivo`);
  return W.length?{lvl:"warn",txt:W.slice(0,3).join("; ")}:null;
}
// 0.9.94: caminho real de uma pasta, a partir da pasta da turma (ex.: «008 - Avaliação > 008.1 - Formandos > 012.1.1 - Enunciados de Avaliação > 1400 - TIC > Módulo 001»)
function locReal(r){r=(r||[]).filter(Boolean);let i=-1;for(let k=0;k<r.length;k++)if(isTurma(r[k]))i=k;return (i>=0?r.slice(i+1):r).join(" > ")}
function prefixoComum(L){if(!L.length)return[];let p=L[0].slice();for(const x of L){let k=0;while(k<p.length&&k<x.length&&p[k]===x[k])k++;p=p.slice(0,k)}return p}
// quantos ficheiros do módulo estão dentro desta pasta (prefere-se a pasta onde o formador já pôs documentos)
function locPeso(rec,fs){const pre=rec.r.join("/")+"/";let n=0;for(const f of fs||[])if((f.rawDir+"/").startsWith(pre))n++;return n}
/* 0.9.97: o Box360 deixa de adivinhar «documentos exigidos». Para cada módulo vê todas as pastas do módulo na Box
   (em todas as secções: 006, 007, 008 › 012.1.x, 012…) e aponta:
   · cada PASTA VAZIA (a de cima: se uma pasta está vazia, as de dentro também estão) — ex.: «012.1.3 - Pautas › 1400 - TIC ›
     Módulo 002», ou a pasta de um formando dentro de «Teste Prático»;
   · cada pasta que só tem ficheiros que NÃO CONTAM (vazios, modelos por preencher, em branco, iguais aos de outro módulo…),
     pela análise dos documentos (qualOf) — para apanhar documentos postos só para a pasta não ficar vazia.
   As pastas com ficheiros válidos contam como entregues. Os itens mantêm a forma antiga ({doc,key,ok,state,…}) para o
   relatório, os PDF, os envios, os prazos e as estatísticas continuarem a funcionar. doc = a secção (ex.: «012.1.3 - Pautas…»). */
var CNT=null,CNTK=-1; // ficheiros por pasta (com as subpastas) e ficheiros de cada pasta
function contagens(){if(CNT&&CNTK===filesRev)return CNT;const tot=new Map(),own=new Map();
  for(const f of files){const d=f.rawDir||"";let L=own.get(d);if(!L)own.set(d,L=[]);L.push(f);
    let q=d;while(q){tot.set(q,(tot.get(q)||0)+1);const i=q.lastIndexOf("/");q=i>0?q.slice(0,i):""}}
  CNT={tot,own};CNTK=filesRev;return CNT}
// secção da pasta: a pasta numerada mais funda do caminho a seguir à turma (ex.: «012.1.3 - Pautas de Avaliação», «007 - Recursos Didáticos»)
function secDe(r){let i=-1;for(let k=0;k<r.length;k++)if(isTurma(r[k]))i=k;const L=r.slice(i+1);let sec="";for(const c of L){if(isDisc(c))break;if(/^\d{2,3}(\.\d+)*\s*[-–]/.test(c))sec=c}return sec||L[0]||"(pasta)"}
function evalCore(idx,mods){
  const out=[];
  const ref=lastEnvio(),refSet=ref?new Set(Object.values(ref.miss).flat()):null;
  const C=contagens(),FP=cfg.fp||{};
  const raiz=lastListing&&lastListing.pasta?segs(lastListing.pasta):[];
  const relDe=p=>{const q=segs(p);let k=0;while(k<raiz.length&&k<q.length&&q[k]===raiz[k])k++;return k===raiz.length?q.slice(k):null};
  const EXR=Object.values(cfg.excluir||{}).map(x=>relDe(x.path)).filter(x=>x&&x.length),FAR=((lastListing&&lastListing.failed)||[]).map(relDe).filter(x=>x&&x.length);
  const cobre=(L,esp)=>L.find(r=>r.every(x=>esp.some(c=>flexEq(x,c))));
  // 1.ª passagem: pastas de cada módulo e os ficheiros de cada uma (para a análise dos documentos comparar entre módulos)
  const slotOf=new Map();
  for(const m of mods){
    let ms=segs(m.pasta),modFolders=idx.pick(ms,"folders"),flexNome="";
    if(!modFolders.length&&ms.length){const alt=idx.flex(ms);if(alt){ms=alt.ss;modFolders=idx.pick(ms,"folders");flexNome=alt.nome}}
    const sgm=discCode(m.disc)+"|"+modKey(m.cod)+"|",S=new Set(modFolders.map(r=>r.r.join("/"))),pastas=[];
    for(const rec of modFolders){const p=rec.r.join("/"),own=C.own.get(p)||[],tot=C.tot.get(p)||0,nome=rec.r[rec.r.length-1];
      const T={cont:[],d:{id:"sec:"+norm(secDe(rec.r)),nome:secDe(rec.r),min:1,subpasta:""}};
      if(own.length){const slot={m,T:{...T,d:{...T.d,nome:nome}},hits:own,sg:sgm+p};for(const f of own)if(!slotOf.has(f))slotOf.set(f,slot);pastas.push({rec,p,nome,T,own,slot})}
      else if(!tot){const par=rec.r.slice(0,-1).join("/");if(!S.has(par)||(C.tot.get(par)||0)>0)pastas.push({rec,p,nome,T,own:[],vazia:true})}}
    out.push({mod:m,pastas,modFolders,nFiles:modFolders.reduce((a,r)=>a+(C.own.get(r.r.join("/"))||[]).length,0),folder:ms.join(" / "),ms,flexNome});
  }
  const ck=cfgEvalKey();if(MENTK!==ck){MENT=new Map();MENTK=ck}
  const X=qualCtx(idx,slotOf,mods);
  // 2.ª passagem: estado de cada pasta
  for(const e of out){const m=e.mod,items=[];
    const relTurma=r=>{let i=-1;for(let k=0;k<r.length;k++)if(isTurma(r[k]))i=k;return r.slice(i+1).map(norm).join("/")};
    for(const x of e.pastas){const esp=x.rec.n;
      if(EXR.length&&cobre(EXR,esp))continue; // pasta excluída da análise
      const key=m.id+"|p:"+relTurma(x.rec.r),loc=locReal(x.rec.r.slice(0,-1));let state,reasons=[],q=[],pastaObs="";
      if(x.vazia){state="missing";pastaObs=FAR.length&&cobre(FAR,esp)?"a Box não deixou abrir esta pasta (sem acesso) — não foi possível confirmar":"pasta vazia"}
      else{q=x.own.map(f=>{const r=qualOf(f,x.slot,X);if(r&&FP[fpKey(f)])return{f,q:null,fp:r.txt};return{f,q:r}});
        const good=q.filter(y=>!y.q||y.q.lvl!=="bad"),clean=q.filter(y=>!y.q),moF=[],rz=L=>L.map(y=>`${y.f.name}: ${y.q.txt}`);
        // 0.9.104: um teste/exame/grelha que não segue o modelo oficial aparece mesmo que a pasta tenha outros ficheiros bons
        if(moF.length&&cfg.mo&&cfg.mo.falta===true){state="blank";reasons=rz(moF)}
        else if(moF.length&&cfg.mo&&cfg.mo.falta==="modelo"){state="modelo";reasons=rz(moF)} // 0.9.106: estado próprio «não segue o modelo oficial» (conta como entregue)
        else if(good.length){state=clean.length&&!moF.length?"ok":"warn";if(state==="warn")reasons=rz(clean.length?moF:good.filter(y=>y.q))}
        else{state="blank";reasons=rz(q.filter(y=>y.q))}}
      let fpi=null;const fpI=FP["i:"+key]; // 0.9.102: a Direção deu este item como entregue (falso positivo), mesmo sem ficheiros válidos
      if(fpI&&state!=="ok"){fpi={era:fpI.txt||pastaObs||reasons.join("; ")||ESTADO[state],t:fpI.t};state="ok";reasons=[];pastaObs="falso positivo — conta como entregue"}
      let seg="";
      if(ref){const was=refSet.has(key);
        if(state==="ok"||state==="warn"||state==="modelo"){if(was)seg="entregue desde o envio de "+dataPT(ref.t)}
        else seg=was?"pedido a "+dataPT(ref.t)+" — continua em falta":"novo (não constava do envio de "+dataPT(ref.t)+")"}
      items.push({doc:x.T.d,key,ok:state==="ok"||state==="warn"||state==="modelo",state,reasons,hits:x.own,q,loc,falta:x.nome,pastaObs,seg,since:!!(ref&&seg.startsWith("entregue desde")),fora:false,fpi})}
    if(!e.modFolders.length)items.push({doc:{id:"sec:modulo",nome:"Pasta do módulo",min:1,subpasta:""},key:m.id+"|p:",ok:false,state:"missing",reasons:[],hits:[],q:[],
      loc:[m.turma,m.disc].filter(Boolean).join(" > "),falta:m.cod,pastaObs:"não há nenhuma pasta deste módulo na análise",seg:"",since:false,fora:false});
    if(!e.modFolders.length&&FP["i:"+m.id+"|p:"]){const it=items[items.length-1],v=FP["i:"+m.id+"|p:"];Object.assign(it,{ok:true,state:"ok",fpi:{era:v.txt||it.pastaObs,t:v.t},pastaObs:"falso positivo — conta como entregue"})}
    // as faltas primeiro, pela ordem das pastas
    e.items=items.sort((a,b)=>(a.ok-b.ok)||COLL_PTN.compare(a.loc+" > "+a.falta,b.loc+" > "+b.falta));
    delete e.pastas;delete e.modFolders;delete e.ms}
  return out;
}
// o resultado fica guardado enquanto nada mudar (ficheiros, textos lidos, módulos, documentos exigidos, opções)
let EV=null,EVK=null,_ekRev=-1,_ek="",QF=null;
function cfgEvalKey(){if(_ekRev!==cfgRev){_ek=JSON.stringify([cfg.docTypes,cfg.mods,cfg.desig,cfg.qual,(cfg.envios||[]).map(v=>v.id),cfg.fp||{}]);_ekRev=cfgRev}return _ek}
function evaluate(){const idx=getIdx(),ck=cfgEvalKey(),k=filesRev+"|"+txRev+"|"+refRev+"|"+tplRev;
  if(EV&&EVK&&EVK.k===k&&EVK.ck===ck)return EV;
  EV=evalCore(idx,ativos());EVK={k,ck};QF=null;return EV}
// estado de cada ficheiro (para o painel Alterações): id do ficheiro -> {lvl, txt}
function qualFicheiros(){if(QF)return QF;const ev=evaluate();QF=new Map();for(const e of ev)for(const i of e.items)for(const x of i.q)if(x.f.fid)QF.set(x.f.fid,x.q||{lvl:"ok",txt:""});return QF}
function byTeacher(ev){
  const map=new Map();
  for(const e of ev){const k=profOf(e.mod)||"_";if(!map.has(k))map.set(k,[]);map.get(k).push(e)}
  const arr=[...map.entries()].map(([pid,list])=>{const p=cfg.profs.find(x=>x.id===pid)||{id:"_",nome:"(sem formador atribuído)",email:""};
    const tot=list.reduce((a,e)=>a+e.items.length,0),ok=list.reduce((a,e)=>a+e.items.filter(i=>i.ok).length,0);return {p,list,tot,ok,miss:tot-ok}});
  arr.sort((a,b)=>b.miss-a.miss||COLL_PT.compare(a.p.nome,b.p.nome));return arr;
}
const motivoBad=i=>{const x=(i.q||[]).find(x=>x.q&&x.q.lvl==="bad");return x?x.q.txt:"sem conteúdo válido"};
const obsOf=i=>[i.state==="blank"?"os ficheiros desta pasta não contam: "+i.reasons.join("; "):"",i.pastaObs,i.state==="warn"?"a confirmar: "+i.reasons.join("; "):"",i.state==="modelo"?"não segue o modelo oficial — "+i.reasons.join("; "):"",i.seg].filter(Boolean).join(" · ");
const ESTADO={ok:"Entregue",warn:"Entregue — a confirmar",modelo:"Entregue — não segue o modelo oficial",blank:"Entregue, mas não conta (vazio ou falso)",missing:"Em falta"};

/* linhas no formato do Excel da escola */
function rowsFor(t,onlyMissing){const r=[];
  for(const e of t.list)for(const i of e.items){if(onlyMissing&&i.ok)continue;
    r.push({turma:e.mod.turma,disc:e.mod.disc,mod:modTitle(e.mod),loc:i.loc,falta:i.falta,obs:obsOf(i),state:i.state,item:i,e})}
  return r;}

/* ---------- envios registados (acompanhamento) ---------- */
// último envio registado para o(s) ano(s) letivo(s) da análise carregada
function lastEnvio(){const a=anoRef();return (cfg.envios||[]).find(v=>!v.anoRef||!a||v.anoRef===a)||null}
function registarEnvio(label){
  const T=byTeacher(evaluate());const miss={};let n=0;
  for(const t of T){if(t.p.id==="_")continue;const k=[];for(const e of t.list)for(const i of e.items)if(!i.ok)k.push(i.key);if(k.length){miss[t.p.id]=k;n+=k.length}}
  ponto("Antes de registar o envio");
  cfg.envios=[{id:uid(),t:Date.now(),label:label||"Envio de emails",miss,n,ano:cfg.mail.ano,anoRef:anoRef(),prazo:cfg.mail.prazo},...(cfg.envios||[])].slice(0,30);
  save();renderEnvios();toast(`Envio registado: ${n} item(ns) em falta`);
  if(lastListing)criarBase(lastListing,"Envio registado").then(()=>{if(curTab==="alt")renderAlt()}); // nova contagem para o painel Alterações
}
function renderEnvios(){const el=$("#envios");if(!el)return;
  el.innerHTML=(cfg.envios||[]).map((v,i)=>`<div class="rp"><span class="d">${new Date(v.t).toLocaleString("pt-PT",{dateStyle:"short",timeStyle:"short"})}</span><span class="l">${esc(v.label)} · ${v.n} item(ns) em falta${v.prazo?` · prazo ${esc(v.prazo)}`:""}${v===lastEnvio()?` <span class="tag ok">referência atual</span>`:""}</span><button class="x" title="Apagar este registo" data-envdel="${i}">×</button></div>`).join("")||`<p class="hint">Ainda não registou nenhum envio.</p>`}
$("#envios").addEventListener("click",e=>{const b=e.target.closest("[data-envdel]");if(!b)return;cfg.envios.splice(+b.dataset.envdel,1);save();renderEnvios();toast("Registo apagado (pode anular)")});

// ===== src/js/box/relatorio.js =====
/* ---------- report ---------- */
{let h=null;["#fProf","#fShow","#fTxt","#chkFiles"].forEach(s=>$(s).addEventListener("input",()=>{REL_N=30;REL_L={};clearTimeout(h);h=setTimeout(renderReport,s==="#fTxt"?150:0)}))}
// 0.9.102: interruptor «Falso positivo em todas as linhas» (guardado neste navegador)
const fpTodos=()=>{const c=$("#chkFp");return!!(c&&c.checked)};
{const c=$("#chkFp");try{c.checked=localStorage.getItem("box_fp_todos")==="1"}catch(e){}
  c.addEventListener("change",()=>{try{localStorage.setItem("box_fp_todos",c.checked?"1":"0")}catch(e){};renderReport()})}
function fpBtns(i){const fl=(i.q||[]).filter(x=>x.q),mk=(i.q||[]).filter(x=>x.fp);let h="";
  if(i.fpi)h+=`<br><span class="hint" style="margin:0">Dado como entregue pela Direção (era: ${esc(i.fpi.era)})</span> <button class="b s fpb" data-on="0" data-k="${esc(JSON.stringify(["i:"+i.key]))}">Anular</button>`;
  else if(fpTodos()&&i.state!=="ok"&&!(fl.length&&(i.state==="warn"||i.state==="blank"||i.state==="modelo")))h+=`<br><button class="b s fpb" data-on="1" data-k="${esc(JSON.stringify(["i:"+i.key]))}" data-t="${esc(obsOf(i)||ESTADO[i.state])}">Falso positivo — conta como entregue</button>`;
  if(fl.length&&(i.state==="warn"||i.state==="blank"||i.state==="modelo"))h+=`<br><button class="b s fpb" data-on="1" data-k="${esc(JSON.stringify(fl.map(x=>fpKey(x.f))))}" data-t="${esc(fl.map(x=>x.f.name+": "+x.q.txt).join("; "))}">Falso positivo — conta como entregue</button>`;
  if(mk.length)h+=`<br><span class="hint" style="margin:0">Assinalado como falso positivo: ${esc(mk.map(x=>x.f.name+" ("+x.fp+")").join("; "))}</span> <button class="b s fpb" data-on="0" data-k="${esc(JSON.stringify(mk.map(x=>fpKey(x.f))))}">Anular</button>`;
  return h}
$("#report").addEventListener("click",e=>{const b=e.target.closest(".fpb");if(!b)return;marcarFP(JSON.parse(b.dataset.k),b.dataset.on==="1",b.dataset.t)});
function renderReport(){
  const ev=evaluate(),T=byTeacher(ev);
  const fp=$("#fProf").value;
  $("#fProf").innerHTML=`<option value="">Todos</option>`+T.map(t=>`<option value="${t.p.id}" ${t.p.id===fp?"selected":""}>${esc(t.p.nome)}</option>`).join("");
  const tot=T.reduce((a,t)=>a+t.tot,0),ok=T.reduce((a,t)=>a+t.ok,0),profsMiss=T.filter(t=>t.miss>0&&t.p.id!=="_").length;
  const all=ev.flatMap(e=>e.items);
  const nBlank=all.filter(i=>i.state==="blank").length,nWarn=all.filter(i=>i.state==="warn").length,nSince=all.filter(i=>i.since).length,nMod=all.filter(i=>i.state==="modelo").length;
  const ref=lastEnvio();
  const pct=tot?Math.round(ok/tot*100):0;
  $("#tiles").innerHTML=`
   <div class="tile"><div class="v">${pct}%</div><div class="l">documentação entregue</div></div>
   <div class="tile"><div class="v" style="color:var(--bad)">${tot-ok}</div><div class="l">itens em falta</div></div>
   <div class="tile"><div class="v">${profsMiss}</div><div class="l">formadores com falhas</div></div>
   ${ref?`<div class="tile"><div class="v" style="color:var(--ok)">${nSince}</div><div class="l">entregues desde o envio de ${dataPT(ref.t)}</div></div>`:""}
   ${nMod?`<div class="tile"><div class="v" style="color:var(--bad)">${nMod}</div><div class="l">não seguem o modelo oficial</div></div>`:""}
   <div class="tile"><div class="v" style="color:#b26a00">${nBlank+nWarn}</div><div class="l">em branco (${nBlank}) ou a confirmar (${nWarn})</div></div>`;countUp($("#tiles"));
  const w=[];
  if(!files.length)w.push(["info","Ainda não carregou a listagem da Box (em Análise). Sem ela, tudo aparece em falta."]);
  const atv=ativos(),noprof=atv.filter(m=>!profOf(m)).length;if(noprof)w.push(["warn",`${noprof} módulo(s) sem formador atribuído — veja a grelha em Atribuições.`]);
  const outros=cfg.mods.length-atv.length;if(outros&&files.length)w.push(["info",`${outros} módulo(s) de outros anos letivos não entram neste relatório (só contam os do ano da análise carregada).`]);
  const pend=porLer().length;if(pend)w.push(["info",`Falta ler o conteúdo de ${pend} documento(s)${bgOn?" — a leitura está a correr em segundo plano e o relatório atualiza-se sozinho":SES?" — clique em “Ler os documentos agora”":" — entre na Box para os ler"}. Até lá, esses documentos contam como entregues.`]);
  const nfp=Object.keys(cfg.fp||{}).length;if(nfp)w.push(["info",`${nfp} documento(s) ou linha(s) assinalados como falso positivo contam como entregues. Para anular, mostre “Tudo” e carregue em “Anular” na linha. Se o formador substituir o ficheiro, a verificação volta a ser feita.`]);
  $("#warns").innerHTML=w.map(([k,t])=>`<div class="msg ${k==="warn"?"bad":"info"}">${esc(t)}</div>`).join("");
  const mode=$("#fShow").value,q=norm($("#fTxt").value),sf=$("#chkFiles").checked;
  const show=i=>mode==="tudo"||(mode==="desde"?i.since:(!i.ok||(mode==="aviso"&&(i.state==="warn"||i.state==="modelo"))));
  REL_N=REL_N||30;REL_L=REL_L||{};let html="",nVis=0,nTot=0; // 0.9.50: com 1000 formadores, 30 de cada vez (eram 111 000 elementos e 2 s)
  for(const t of T){ if(fp&&t.p.id!==fp)continue;
    const rows=rowsFor(t,false).filter(r=>show(r.item)&&(!q||norm(r.turma+" "+r.disc+" "+r.mod+" "+r.loc).includes(q)));
    if(!rows.length)continue;nTot++;if(nVis>=REL_N)continue;nVis++;
    const lim=REL_L[t.p.id]||150,resto=rows.length-lim;if(resto>0)rows.length=lim; // e no máximo 150 linhas por formador de cada vez (o grupo "sem formador" pode ter milhares)
    const pc=t.tot?Math.round(t.ok/t.tot*100):100;
    html+=`<div class="prof"><div class="hd"><b>${esc(t.p.nome)}</b>${t.p.cod?`<span class="tag" style="background:#eef1f5;color:#4a5260">${esc(t.p.cod)}</span>`:""}<span class="hint" style="margin:0">${esc(t.p.email)}</span><span class="grow"></span>
      <div class="bar"><i style="width:${pc}%"></i></div><span>${t.ok}/${t.tot}</span>
      ${t.miss?`<span class="tag bad">${t.miss} em falta</span>`:`<span class="tag ok">completo</span>`}${t.miss&&t.p.id!=="_"?`<button class="b s pdfb" data-rpdf="${t.p.id}" title="Exportar em PDF o que este formador tem em falta">PDF</button>`:""}</div>
      <div style="padding:4px 12px 10px;overflow-x:auto"><table class="rtab rt"><thead><tr><th>Turma</th><th>Disciplina</th><th>Módulo/UFCD</th><th>Localização na Box</th><th>O que está em falta</th><th>Observações</th></tr></thead><tbody>
      ${rows.map(r=>`<tr class="s-${r.state}"><td>${esc(r.turma)}</td><td>${esc(r.disc)}</td><td>${esc(r.mod)}</td><td>${esc(r.loc)}</td><td class="f">${{ok:"✓",warn:ico("alert"),modelo:ico("alert"),blank:"✗",missing:"✗"}[r.state]} <span title="${esc(r.falta)}">${esc(faltaDesc(r))}</span></td><td class="o">${esc(r.obs||(r.state==="ok"?"entregue":""))}${sf&&r.item.hits.length?`<br><b>Ficheiros:</b> ${r.item.hits.map(h=>esc(h.name)).join(", ")}`:""}${fpBtns(r.item)}</td></tr>`).join("")}
      </tbody></table>${resto>0?`<div style="text-align:center;margin:8px 0 2px"><button class="b s" data-relmais="${esc(t.p.id)}" type="button">Mostrar mais ${Math.min(500,resto)} linhas (faltam ${resto})</button></div>`:""}</div></div>`;}
  if(nTot>nVis)html+=`<div style="text-align:center;margin:6px 0 18px"><button class="b s" id="relMais" type="button">Mostrar mais ${Math.min(30,nTot-nVis)} formadores (faltam ${nTot-nVis})</button></div>`;
  $("#report").innerHTML=html||`<div class="card"><p class="hint" style="margin:0">${ativos().length?"Nada a mostrar com estes filtros.":"Defina primeiro os módulos em Atribuições."}</p></div>`;
  const bm=$("#relMais");if(bm)bm.onclick=()=>{REL_N+=30;renderReport()};
  $("#report").querySelectorAll("[data-relmais]").forEach(b=>b.onclick=()=>{const k=b.dataset.relmais;REL_L[k]=(REL_L[k]||150)+500;renderReport()});
}
var REL_N=30,REL_L={};

/* ---------- opções das verificações ---------- */
function qualInit(){
  cfg.qual=cfg.qual||{min:40,dup:true};
  $("#qMin").value=cfg.qual.min||40;$("#qInicio").value=cfg.qual.inicio||"";
  document.querySelectorAll("#qChecks [data-q]").forEach(c=>{c.checked=qOn(c.dataset.q);c.parentElement.classList.toggle("on",c.checked)});
  const cur=lastListing&&lastListing.rootId,r=resumos();
  $("#qRef").innerHTML=`<option value="">— nenhum —</option>`+Object.keys(r).filter(id=>id!==cur).map(id=>`<option value="${esc(id)}" ${cfg.qual.refRoot===id?"selected":""}>${esc(r[id].pasta)} (analisada a ${esc(r[id].quando)})</option>`).join("");
  const idx=getIdx();$("#qInicio").placeholder=idx.anos.size===1?[...idx.anos.keys()][0].slice(0,4)+"-07-01":"AAAA-MM-DD";
}
