 const sb=document.createElement("div");sb.id="subbar";sb.innerHTML=`<span class="subusr" id="subUsr"></span><span class="sst" id="subSt"></span>`;const mn=document.querySelector("main");mn.insertBefore(sb,mn.firstChild);
