/* ---------- Por formadores (0.9.142): todos os formadores numa semana, lado a lado ----------
   0.9.158: tempos seguidos da mesma aula juntam-se num só bloco; por omissão só quem tem aulas na semana (botão «Todos»);
   linhas da mesma altura, dias em fundos alternados, hoje destacado e uma linha final com quantos formadores estão em aula em cada tempo. */
const H3F={q:"",todos:false};
async function hsForRender(){await null;try{await esdPronto}catch(e){}try{await h3Carregar()}catch(e){}
  const out=$("#hsForOut"),hero=$("#hsForHero");if(!out)return;const st=mhEstado(),a=anoAtivo(),hj=calHoje();
  if(!H3S.seg){let d=hj;const w=calD(d).getDay();if(w===6)d=calMais(d,2);else if(w===0)d=calMais(d,1);H3S.seg=h3Seg(d)}
  $("#hsForData").value=H3S.seg;
  if(!st){hero.innerHTML=`<div class="ay-hero"><div class="ay-top"><div><h1>Por formadores</h1><div class="sub">${esc(a.nome)}</div></div></div></div>`;out.innerHTML=`<div class="pp-vz">${ICO.cal}<p>${RO?"A Direção ainda não publicou o horário de "+esc(a.nome)+".":"Ainda não há horário para "+esc(a.nome)+"."}</p></div>`;return}
  const VL=cpVersoes(st).slice().sort((p,q)=>String(p.de||"").localeCompare(String(q.de||""))),D=st.days||["Seg","Ter","Qua","Qui","Sex"],P=st.periods||[],NP=P.length,NL=calNaoLetivos(a);
  const dias=D.map((d,i)=>{const dt=calMais(H3S.seg,i);let V=cpVersaoEm(VL,dt);if(!V&&VL.length===1)V=VL[0];return{i,nome:d,dt,V,nl:NL.get(dt),fora:(a.inicio&&dt<a.inicio)||(a.fim&&dt>a.fim)}});
  const em=String(EU&&EU.email||"").toLowerCase(),me=(cfg.profs||[]).find(p=>h3Email(p)===em),eu=t=>!!me&&(t.id===me.id||(ESD.mapaT||{})[t.id]===me.id);
  const cache=new Map();const cel=(t,d)=>{if(!d.V||d.nl||d.fora)return null;const k=t.id+"|"+(VL.indexOf(d.V));if(!cache.has(k))cache.set(k,h3Celulas(st,d.V,"t",t.id));return cache.get(k)};
  const q=norm(H3F.q||"");
  const TT=(st.teachers||[]).filter(t=>!q||norm((t.name||"")+" "+(t.short||"")).includes(q)).map(t=>{let n=0;for(const d of dias){const m=cel(t,d);if(m)for(let pi=0;pi<NP;pi++){const L=m.get(d.i+"|"+pi);if(L)n+=L.length}}return{t,n}})
    .sort((x,y)=>(eu(y.t)-eu(x.t))||cmpTch(x.t,y.t));
  const comAulas=TT.filter(x=>x.n>0),semAulas=TT.filter(x=>!x.n&&!eu(x.t));
  const mostra=H3F.todos||!comAulas.length?TT:TT.filter(x=>x.n>0||eu(x.t));
  const ocup=dias.map(()=>new Array(NP).fill(0));let tot=0;const fim=calMais(H3S.seg,D.length-1);
  let h=`<div class="tw hsfw"><table class="hsf"><thead><tr><th class="nm" rowspan="2">Formador</th>${dias.map((d,di)=>`<th colspan="${NP}" class="dsep${di%2?" alt":""}${d.dt===hj?" hj":""}${d.nl||d.fora?" nl":""}">${esc(d.nome)} <small>${esc(calDM(d.dt))}</small>${d.dt===hj?` <i class="hjt">hoje</i>`:""}${d.nl?`<em>${esc(d.nl.n)}</em>`:d.fora?`<em>fora do ano letivo</em>`:""}</th>`).join("")}<th rowspan="2" class="tt">Tempos</th></tr><tr>${dias.map((d,di)=>P.map((p,pi)=>`<th class="${pi===0?"dsep":""}${di%2?" alt":""}${d.dt===hj?" hj":""}" title="${esc((p.start||"")+(p.end?"–"+p.end:""))}">${esc(p.label||pi+1)}</th>`).join("")).join("")}</tr></thead><tbody>`;
  for(const {t,n} of mostra){let r=`<td class="nm"><a href="#" data-hsver="${esc(t.id)}" title="Ver a semana de ${esc(t.name||"")}">${esc(t.name||t.short||"—")}</a>${t.short&&t.short!==t.name?` <span class="sg">${esc(t.short)}</span>`:""}</td>`;
    dias.forEach((d,di)=>{const m=cel(t,d),base=(d.nl||d.fora?" nl":"")+(di%2?" alt":"")+(d.dt===hj?" hj":"");
      for(let pi=0;pi<NP;){const L=m&&m.get(d.i+"|"+pi),cl=(pi===0?"dsep":"")+base;
        if(!L){r+=`<td class="${cl}"></td>`;pi++;continue}
        const x=L[0],k=L.map(y=>[y.tu,y.disc,y.sala].join("|")).join("~");let len=1;
        while(pi+len<NP){const L2=m.get(d.i+"|"+(pi+len));if(!L2||L2.map(y=>[y.tu,y.disc,y.sala].join("|")).join("~")!==k)break;len++}
        for(let z=0;z<len;z++)ocup[di][pi+z]++;
        const cor=h3Cor(st,x,"t"),pa=P[pi]||{},pz=P[pi+len-1]||{},hr=(pa.start||"")+(pz.end?"–"+pz.end:"");
        const tit=[`${x.nome||x.disc}${x.tu?" · "+x.tu:""}${x.sala?" · "+x.sala:""}`].concat(L.slice(1).map(y=>[y.nome||y.disc,y.tu,y.sala].filter(Boolean).join(" · "))).join("\n")+`\n${len} tempo${len>1?"s":""}${hr?" · "+hr:""}`;
        r+=`<td class="${cl} on" colspan="${len}"><div class="hsb" style="--sc:${esc(cor)};background:${h3Tinta(cor,.16)};color:${h3Escuro(cor)}" title="${esc(tit)}"><b>${esc(x.tu||x.disc)}${L.length>1?` <i>+${L.length-1}</i>`:""}</b><span>${esc([x.tu?x.disc:"",x.sala].filter(Boolean).join(" · "))}${len>1?` · ${len} t`:""}</span></div></td>`;pi+=len}});
    tot+=n;h+=`<tr class="${eu(t)?"eu":""}${n?"":" vz"}">${r}<td class="tt">${n||`<span class="z">0</span>`}</td></tr>`}
  h+=`</tbody><tfoot><tr><td class="nm">Formadores em aula</td>${dias.map((d,di)=>ocup[di].map((v,pi)=>`<td class="${pi===0?"dsep":""}${di%2?" alt":""}${d.dt===hj?" hj":""}">${v||""}</td>`).join("")).join("")}<td class="tt">${tot}</td></tr></tfoot></table></div>`;
  hero.innerHTML=`<div class="ay-hero"><div class="ay-top"><div><h1>Por formadores</h1><div class="sub">Semana de ${esc(calDM(H3S.seg,{day:"numeric",month:"short"}))} a ${esc(calDM(fim,{day:"numeric",month:"short"}))}${H3S.seg===h3Seg(hj)?" · esta semana":""}${me?" · o seu horário aparece primeiro":""}</div></div><span class="grow"></span><div class="ay-pct"><b>${comAulas.length}</b>com aulas, de ${TT.length} formador${TT.length===1?"":"es"} · ${tot} tempo${tot===1?"":"s"}</div></div></div>`;
  const seg=comAulas.length&&semAulas.length?`<div class="hsfbar"><div class="frseg" role="group" aria-label="Formadores a mostrar"><button type="button" data-hsft="0" class="${H3F.todos?"":"on"}">Com aulas (${comAulas.length})</button><button type="button" data-hsft="1" class="${H3F.todos?"on":""}">Todos (${TT.length})</button></div>${H3F.todos?"":`<span class="hint" style="margin:0">${semAulas.length} sem aulas nesta semana: ${esc(semAulas.slice(0,6).map(x=>x.t.name||x.t.short).join(", "))}${semAulas.length>6?"…":""}</span>`}</div>`:"";
  out.innerHTML=TT.length?seg+h+`<p class="hint">Carregue no nome de um formador para ver a semana dele em pormenor. Passe o rato por cima de uma aula para ver a disciplina, a turma, a sala e as horas.</p>`:`<p class="hint">Nenhum formador com este nome.</p>`}
$("#hsForOut").addEventListener("click",e=>{const b=e.target.closest("[data-hsft]");if(!b)return;H3F.todos=b.dataset.hsft==="1";hsForRender()});
$("#hsForQ").oninput=debounce(()=>{H3F.q=$("#hsForQ").value;hsForRender()},200);
$("#hsForData").onchange=e=>{if(e.target.value){H3S.seg=h3Seg(e.target.value);hsForRender()}};
$("#hsForAnt").onclick=()=>{H3S.seg=calMais(H3S.seg||h3Seg(calHoje()),-7);hsForRender()};
$("#hsForSeg").onclick=()=>{H3S.seg=calMais(H3S.seg||h3Seg(calHoje()),7);hsForRender()};
$("#hsForHoje").onclick=()=>{H3S.seg="";hsForRender()};
$("#hsForOut").addEventListener("click",e=>{const l=e.target.closest("[data-hsver]");if(!l)return;e.preventDefault();H3S.tipo="t";H3S.quem=l.dataset.hsver;show("hsSem")});

/* ---------- Importar do Untis a partir da versão simples ----------
   Os PDF escolhem-se aqui e são entregues ao importador do editor (o mesmo da versão completa), onde se confirma a importação. */
// 0.9.148: também os ficheiros GPU do Untis (GPU001.TXT…GPU006.TXT) — o mesmo intercâmbio que o DBG pleon lê; vão para o importador GPU do editor (junta ao horário atual)
const h3EhGPU=f=>/(^|\/)GPU0*\d+\D*\.txt$/i.test(f.webkitRelativePath||f.name)||/^GPU0*\d+\.txt$/i.test(f.name);
function h3Importar(modo){const pasta=modo===true||modo==="pasta",gpu=modo==="gpu";
  const inp=document.createElement("input");inp.type="file";inp.multiple=true;if(pasta)inp.webkitdirectory=true;else inp.accept=gpu?".txt,.TXT,text/plain":".pdf,.zip,.txt,application/pdf,application/zip,text/plain";inp.style.display="none";document.body.append(inp);
  inp.onchange=async()=>{let fs=[...inp.files].filter(f=>!/(^|\/)(__MACOSX|\.)/.test(f.webkitRelativePath||f.name));inp.remove();if(!fs.length){if(pasta)toast("Pasta vazia.");return}
    // na pasta (ou numa escolha mista): se houver ficheiros GPU, entram esses (dados exatos do Untis); senão os PDF e .zip
    const G=fs.filter(h3EhGPU),PD=fs.filter(f=>/\.(pdf|zip)$/i.test(f.name));
    let tipo=gpu||G.length?"gpu":"pdf",L=tipo==="gpu"?(G.length?G:fs.filter(f=>/\.txt$/i.test(f.name))):PD;
    if(!L.length){toast(gpu?"Escolha os ficheiros GPU do Untis (GPU001.TXT e, se houver, GPU002…GPU006).":pasta?"Essa pasta não tem PDF nem ficheiros GPU do Untis.":"Escolha PDF, .zip ou ficheiros GPU do Untis.");return}
    if(tipo==="gpu"&&!L.some(f=>/GPU0*1\D*\.txt$/i.test(f.name))){toast("Falta o GPU001.TXT (horários) — é o ficheiro principal da exportação do Untis.");return}
    if(pasta||(G.length&&PD.length))toast(tipo==="gpu"?`A importar ${L.length} ficheiro${L.length===1?"":"s"} GPU do Untis${PD.length?" (os PDF ficam de fora: os GPU têm os dados exatos)":""}…`:`A importar ${L.length} PDF…`);
    H3_IMP=true;aplicarPerfil();show("esch");
    const fr=$("#esFr");let w=null;for(let i=0;i<100;i++){try{w=fr.contentWindow;if(w&&typeof w.updfEscolher==="function"&&fr.classList.contains("pronto"))break}catch(e){}w=null;await new Promise(r=>setTimeout(r,200))}
    if(!w){toast("O editor de horários não abriu — tente outra vez");return}
    const entregar=inpEl=>{const dt=new w.DataTransfer();L.forEach(f=>dt.items.add(f));inpEl.files=dt.files;inpEl.dispatchEvent(new w.Event("change",{bubbles:true}))};
    if(tipo==="gpu"){ // a página «Ficheiro» do editor tem o importador GPU (#im-dif): abre-a e entrega-lhe os ficheiros
      try{w.location.hash="ficheiro"}catch(e){}let el=null;for(let i=0;i<50&&!el;i++){await new Promise(r=>setTimeout(r,100));try{el=fr.contentDocument.getElementById("im-dif")}catch(e){}}
      if(!el){toast("Não encontrei o importador GPU do editor — abra Horários › Ficheiro › Importar ficheiros GPU");return}
      try{entregar(el)}catch(e){toast("Não foi possível entregar os ficheiros ao importador: "+e.message);return}}
    else{const Pr=w.HTMLInputElement.prototype,orig=Pr.click;
      Pr.click=function(){if(this.type==="file"){Pr.click=orig;try{entregar(this)}catch(e){toast("Não foi possível entregar os ficheiros ao importador: "+e.message)}return}return orig.call(this)};
      try{w.updfEscolher()}catch(e){Pr.click=orig;toast("Não foi possível importar: "+e.message);return}
      setTimeout(()=>{if(Pr.click!==orig)Pr.click=orig},4000)}
    $("#esMsg").innerHTML=`<div class="msg info h3volta"><span>Confirme a importação na janela do Horários360 (por omissão junta ao horário atual, sem apagar nada). Quando terminar, volte à vista simples — os formadores com o horário mudado aparecem em «Comunicar».</span><button class="b s" data-h3volta>Voltar à semana</button></div>`};
  inp.click()}
document.addEventListener("click",e=>{if(!e.target.closest("[data-h3volta]"))return;H3_IMP=false;$("#esMsg").innerHTML="";aplicarPerfil();show(h3Modo()==="completa"?"hsCom":"hsSem")});

/* ---------- Comunicar: o que mudou desde o último aviso ---------- */
// as aulas de um formador no horário em vigor e nos seguintes, em frases que se podem comparar e mostrar
const h3Frase=(pre,dia,p,pi,x)=>`${pre}${dia} ${p.start||p.label||pi+1}${p.end?"–"+p.end:""} · ${x.disc}${x.tu?" · "+x.tu:""}${x.sala?" · "+x.sala:""}`;
function h3Linhas(st,tid){const VL=cpVersoes(st),hj=calHoje(),D=st.days||["Seg","Ter","Qua","Qui","Sex"],P=st.periods||[],o=new Set();
  for(const V of VL){if(V.ate&&V.ate<hj)continue;const m=h3Celulas(st,V,"t",tid),pre=V.de&&V.de>hj?"A partir de "+calDM(V.de)+" · ":"";
    for(const [k,L] of m){const [di,pi]=k.split("|").map(Number),p=P[pi]||{};if(!D[di])continue;for(const x of L)o.add(h3Frase(pre,D[di],p,pi,x))}}
  const DS=["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"],ord=s=>{const m=/(Seg|Ter|Qua|Qui|Sex|Sáb|Dom)\S* (\d\d:\d\d)?/.exec(s);return (s.startsWith("A partir")?"1":"0")+(m?DS.indexOf(m[1].slice(0,3))+(m[2]||""):"")+s};
  return [...o].sort((a,b)=>ord(a).localeCompare(ord(b)))}
// 0.9.149: cada formador só sai da lista depois de avisado pelas duas vias — email e telemóvel (notificação ou SMS).
// H3.ult[tid] = {c: horário do último aviso completo (base das diferenças), em/emT: horário avisado por email, tl/tlT: por telemóvel}
function h3Pendentes(){const st=mhEstado();if(!st||!H3)return[];const r=[];
  for(const t of st.teachers||[]){const cur=h3Linhas(st,t.id),h=esHash(cur.join("\n")),ant=H3.ult[t.id],p=h3ProfDe(st,t.id);
    if(!ant&&!cur.length)continue;
    // 0.9.153: as linhas «?» (aulas por colocar, antes da 0.9.151) deixam de contar
    const base=ant&&ant.c&&ant.c.filter(l=>!/^\? /.test(l)),hb=ant&&ant.c?esHash(ant.c.join("\n")):"",A=new Set(base||[]),B=new Set(cur),mais=base?cur.filter(x=>!A.has(x)):cur,menos=base?base.filter(x=>!B.has(x)):[],igual=!!base&&!mais.length&&!menos.length;
    const antigo=!!ant&&ant.em===undefined&&ant.tl===undefined; // avisos de antes da 0.9.149: contam para as duas vias se nada mudou
    const emOk=!!ant&&(ant.em===h||(igual&&(antigo||ant.em===hb))),tlOk=!!ant&&(ant.tl===h||(igual&&(antigo||ant.tl===hb)));
    if(emOk&&tlOk)continue;
    r.push({t,p,cur,h,novo:!base,mais,menos,emOk,tlOk})}
  return r.sort((a,b)=>COLL_PT.compare(String(a.t.name),String(b.t.name)))}
/* ---------- 0.9.170: turmas (formandos) — avisos pelo WhatsApp ----------
   Como para os formadores: o horário de cada turma (em vigor e seguintes) em frases; H3.ultC[classId]={c,h,t} = o último
   horário avisado. Avisa-se pelo grupo de avisos da turma (texto pronto) ou os formandos um a um (wa.me, ver core/whatsapp.js). */
function h3TurmaDe(c){const E=escData();return E.turmas.find(t=>t.id===c.id)||E.turmas.find(t=>t.id===(ESD.mapaC||{})[c.id])||E.turmas.find(t=>norm(t.cod||"")===norm(c.name||""))||null}
function h3LinhasC(st,cid){const VL=cpVersoes(st),hj=calHoje(),D=st.days||["Seg","Ter","Qua","Qui","Sex"],P=st.periods||[],o=new Set();
  for(const V of VL){if(V.ate&&V.ate<hj)continue;const m=h3Celulas(st,V,"c",cid),pre=V.de&&V.de>hj?"A partir de "+calDM(V.de)+" · ":"";
    for(const [k,L] of m){const [di,pi]=k.split("|").map(Number),p=P[pi]||{};if(!D[di])continue;
      for(const x of L)o.add(`${pre}${D[di]} ${p.start||p.label||pi+1}${p.end?"–"+p.end:""} · ${x.disc}${x.form?" · "+x.form:""}${x.sala?" · "+x.sala:""}`)}}
  const DS=["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"],ord=s=>{const m=/(Seg|Ter|Qua|Qui|Sex|Sáb|Dom)\S* (\d\d:\d\d)?/.exec(s);return (s.startsWith("A partir")?"1":"0")+(m?DS.indexOf(m[1].slice(0,3))+(m[2]||""):"")+s};
  return [...o].sort((a,b)=>ord(a).localeCompare(ord(b)))}
function h3PendentesC(){const st=mhEstado();if(!st||!H3)return[];const r=[];
  for(const c of st.classes||[]){const cur=h3LinhasC(st,c.id),h=esHash(cur.join("\n")),ant=H3.ultC[c.id];if(!ant&&!cur.length)continue;if(ant&&ant.h===h)continue;
    const base=ant&&ant.c,A=new Set(base||[]),B=new Set(cur);r.push({c,t:h3TurmaDe(c),cur,h,novo:!base,mais:base?cur.filter(x=>!A.has(x)):cur,menos:base?base.filter(x=>!B.has(x)):[]})}
  return r.sort((a,b)=>COLL_PTN.compare(String((a.t&&a.t.cod)||a.c.name),String((b.t&&b.t.cod)||b.c.name)))}
function h3MarcarC(x){H3.ultC[x.c.id]={c:x.cur,h:x.h,t:Date.now()};H3.env.push({t:Date.now(),por:(EU&&EU.email)||"",quem:"Turma "+((x.t&&x.t.cod)||x.c.name||""),canais:["wa"],n:x.novo?-1:x.mais.length+x.menos.length});if(H3.env.length>200)H3.env=H3.env.slice(-200)}
function h3TxtC(x){if(x.novo)return x.cur.map(s=>"• "+s).join("\n");return (x.mais.length?"Aulas novas ou mudadas:\n"+x.mais.map(s=>"+ "+s).join("\n"):"")+(x.mais.length&&x.menos.length?"\n\n":"")+(x.menos.length?"Deixam de existir:\n"+x.menos.map(s=>"− "+s).join("\n"):"")}
function h3PreencherC(tpl,x,nome){const sem=calDM(h3Seg(calHoje()),{day:"numeric",month:"long"});
  return String(tpl||"").replace(/\{turma\}/g,(x.t&&x.t.cod)||x.c.name||"").replace(/\{alteracoes\}/g,h3TxtC(x)).replace(/\{ligacao\}/g,h3Lig()).replace(/\{semana\}/g,sem).replace(/\{primeiro_nome\}/g,waPrimeiro(nome)).replace(/\{nome\}/g,nome||"")}
function h3FormandosC(x){return x.t?escData().formandos.filter(f=>f.turmaId===x.t.id&&!f.estado):[]}
function h3Txt(x){if(x.novo)return "O seu horário:\n"+x.cur.map(s=>"  "+s).join("\n");
  return (x.mais.length?"Aulas novas ou mudadas:\n"+x.mais.map(s=>"  + "+s).join("\n"):"")+(x.mais.length&&x.menos.length?"\n\n":"")+(x.menos.length?"Deixam de existir:\n"+x.menos.map(s=>"  − "+s).join("\n"):"")}
/* 0.9.171: {nome} = só o primeiro nome do formador («Olá Joel,») */
function h3PNome(x){const n=String((x.p&&x.p.nome)||x.t.name||"").trim();return n.split(/\s+/)[0]||n}
function h3Preencher(tpl,x){const n=x.novo?"horário novo":(x.mais.length+x.menos.length)+" alteraç"+(x.mais.length+x.menos.length===1?"ão":"ões");
  const sem=calDM(h3Seg(calHoje()),{day:"numeric",month:"long"});
  return String(tpl||"").replace(/\{nome\}/g,h3PNome(x)).replace(/\{alteracoes\}/g,h3Txt(x)).replace(/\{ligacao\}/g,h3Lig()).replace(/\{semana\}/g,sem).replace(/\{n\}/g,n)}
function h3Marcar(x,canais){const u=Object.assign({},H3.ult[x.t.id]||{}),agora=Date.now(),todos=canais.includes("marca");
  if(todos||canais.includes("email")){u.em=x.h;u.emT=agora}
  if(todos||canais.includes("push")||canais.includes("sms")||canais.includes("wa")){u.tl=x.h;u.tlT=agora}
  if(u.em===x.h&&u.tl===x.h)u.c=x.cur;u.t=agora;H3.ult[x.t.id]=u;
  H3.env.push({t:agora,por:(EU&&EU.email)||"",quem:x.t.name||"",canais,n:x.novo?-1:x.mais.length+x.menos.length});if(H3.env.length>200)H3.env=H3.env.slice(-200)}
async function h3Push(x){const tp=h3Topico(h3Email(x.p));if(!tp)throw new Error("sem tópico");
  const r=await fetch("https://ntfy.sh/",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({topic:tp,title:"EPISJ 360 — Horário",message:h3Preencher(H3.msg.curta,x),click:h3Lig(),tags:["calendar"]})});
  if(!r.ok)throw new Error("ntfy "+r.status)}
async function h3Email1(x){const to=h3Email(x.p);if(!to)throw new Error("sem email");await msEnviar({to,subject:h3Preencher(H3.msg.assunto,x),body:h3Preencher(H3.msg.corpo,x),html:h3EmailHtml(x)})}
// 0.9.151: email em HTML com o horário desenhado (grelha dias × tempos, cores das disciplinas, aulas novas ou mudadas assinaladas).
// Estilos todos embutidos e tabelas simples, para o Outlook e o Gmail mostrarem igual; o texto simples continua como alternativa.
function h3EmailHtml(x){const st=mhEstado();if(!st)return "";const hj=calHoje(),D=st.days||["Seg","Ter","Qua","Qui","Sex"],P=st.periods||[],novo=new Set(x.novo?[]:x.mais),F="font-family:Segoe UI,Helvetica,Arial,sans-serif";
  const VL=cpVersoes(st).slice().sort((p,q)=>String(p.de||"").localeCompare(String(q.de||""))).filter(V=>!(V.ate&&V.ate<hj));
  const usadas=new Map();
  const grelha=V=>{const m=h3Celulas(st,V,"t",x.t.id),pre=V.de&&V.de>hj?"A partir de "+calDM(V.de)+" · ":"";let n=0;
    // tempos seguidos com a mesma aula juntam-se num só bloco (rowspan)
    const sig=(di,pi)=>{const L=m.get(di+"|"+pi);return L?L.map(c=>c.disc+"|"+c.tu+"|"+c.sala+"|"+(novo.has(h3Frase(pre,D[di],P[pi]||{},pi,c))?1:0)).join("¦"):""};
    const tapa=new Set(),span={};D.forEach((d,di)=>{for(let pi=0;pi<P.length;pi++){const g=sig(di,pi);if(!g)continue;let k=1;while(pi+k<P.length&&sig(di,pi+k)===g){tapa.add(di+"|"+(pi+k));k++}span[di+"|"+pi]=k;pi+=k-1}});
    let h=`<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="border-collapse:separate;border-spacing:4px;width:100%;max-width:760px;table-layout:fixed;${F};font-size:12px"><tr><td style="width:62px"></td>${D.map(d=>`<td style="width:${Math.floor(100/D.length)}%;padding:6px 4px 4px;text-align:center;font-weight:700;font-size:12.5px;color:#163269;border-bottom:2px solid #e3e7ee">${esc(d)}</td>`).join("")}</tr>`;
    P.forEach((p,pi)=>{h+=`<tr><td style="padding:6px 8px 4px 0;text-align:right;color:#8a92a3;white-space:nowrap;vertical-align:top;font-size:11px;line-height:1.35"><b style="color:#1b2333;font-size:12px">${esc(p.start||p.label||pi+1)}</b><br>${esc(p.end||"")}</td>`;
      D.forEach((d,di)=>{if(tapa.has(di+"|"+pi))return;const L=m.get(di+"|"+pi);if(!L){h+=`<td style="background:#f6f8fb;border-radius:8px;height:46px"></td>`;return}
        const k=span[di+"|"+pi]||1;
        h+=`<td rowspan="${k}" style="vertical-align:top;padding:0;height:${46*k}px">`+L.map(c=>{n+=k;const cor=h3Cor(st,c,"t"),nv=novo.has(h3Frase(pre,d,p,pi,c));usadas.set(c.tu||c.disc,cor);
          return `<div style="background:${h3Tinta(cor,.16)};border-left:4px solid ${esc(cor)};${nv?"outline:2px solid #1b2333;":""}border-radius:8px;padding:6px 8px;margin:0 0 3px;line-height:1.3;min-height:${46*k-14}px;color:#1b2333"><b style="font-size:13px;color:${h3Escuro(cor)}">${esc(c.tu||c.disc)}</b>${nv?` <span style="font-size:9.5px;font-weight:700;letter-spacing:.04em;background:#1b2333;color:#fff;border-radius:4px;padding:1px 5px;vertical-align:1px">NOVO</span>`:""}<br><span style="font-size:11px;color:#4a5262">${esc([c.tu?c.disc:"",c.sala].filter(Boolean).join(" · "))}</span>${k>1?`<br><span style="font-size:10.5px;color:#8a92a3">${k} tempos</span>`:""}</div>`}).join("")+`</td>`});h+=`</tr>`});
    return {h:h+`</table>`,n}};
  let quadro="";for(const V of VL){const g=grelha(V);if(!g.n&&VL.length>1)continue;
    quadro+=`<p style="${F};font-size:14px;font-weight:700;color:#163269;margin:18px 0 6px">${VL.length>1?(V.de&&V.de>hj?"A partir de "+esc(calDMA(V.de)):"Horário em vigor"+(V.de?" desde "+esc(calDMA(V.de)):"")):"O seu horário"} <span style="font-weight:400;color:#6b7385">· ${g.n} tempo${g.n===1?"":"s"} por semana</span></p>`+g.h}
  {const leg=[...usadas].sort((a,b)=>COLL_PTN.compare(a[0],b[0])).map(([t,c])=>`<span style="display:inline-block;margin:0 10px 4px 0;white-space:nowrap"><span style="display:inline-block;width:10px;height:10px;border-radius:3px;background:${esc(c)};vertical-align:-1px"></span>&nbsp;${esc(t)}</span>`).join("");
    quadro+=`<p style="${F};font-size:12px;color:#4a5262;margin:8px 0 0">${leg}${!x.novo&&x.mais.length?`<span style="display:inline-block;white-space:nowrap"><span style="font-size:9.5px;font-weight:700;background:#1b2333;color:#fff;border-radius:4px;padding:1px 5px">NOVO</span>&nbsp;aula nova ou mudada</span>`:""}</p>`}
  if(!x.novo&&x.menos.length)quadro+=`<p style="${F};font-size:13px;font-weight:700;color:#1b2333;margin:14px 0 4px">Deixam de existir</p><ul style="${F};font-size:12.5px;color:#6b7385;margin:0;padding-left:18px">${x.menos.map(l=>`<li style="text-decoration:line-through">${esc(l)}</li>`).join("")}</ul>`;
  /* 0.9.163: sem ligações no email — o filtro de correio do Office 365 retinha (sem avisar) os emails com ligações para o endereço da
     EPISJ 360, um domínio ainda recente; testado a 22/11/2026: o mesmo email sem ligações chega. O endereço fica escrito, em negrito. */
  const lig=h3Lig(),txt0=t=>esc(t).replace(/\n/g,"<br>").replace(/\{ligacao\}/g,`<b style="color:#163269">${esc(lig.replace(/^https?:\/\//,"").replace(/\/$/,""))}</b>`);
  /* 0.9.170: a despedida («Com os melhores cumprimentos, …» e a assinatura) fica alinhada à direita */
  const txt=t=>{const m=String(t).match(/(^|\n)[ \t]*((com os )?(melhores |cordiais )?cumprimentos|atenciosamente|saudações)/i);if(!m)return txt0(t);const k=m.index+m[1].length;
    return txt0(t.slice(0,k).replace(/\s+$/,""))+`<div style="text-align:right;margin-top:${k?14:0}px">${txt0(t.slice(k).replace(/^\s+/,""))}</div>`};
  const corpo=String(H3.msg.corpo||"").replace(/\{nome\}/g,h3PNome(x)).replace(/\{semana\}/g,calDM(h3Seg(hj),{day:"numeric",month:"long"})).replace(/\{n\}/g,x.novo?"horário novo":String(x.mais.length+x.menos.length));
  const partes=corpo.split("{alteracoes}").map((t,i,a)=>a.length>1?(i===0?t.replace(/\s+$/,""):i===a.length-1?t.replace(/^\s+/,""):t.trim()):t),meio=`</div>${quadro}<div style="${F};font-size:14px;color:#1b2333;line-height:1.55;margin-top:16px">`;
  const btn="";
  return `<!DOCTYPE html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"></head><body style="margin:0;padding:0;background:#ffffff">
<div style="max-width:780px;padding:8px 4px">
${h3EmailTopo(F)}
<div style="${F};font-size:14px;color:#1b2333;line-height:1.55">${partes.map(txt).join(meio)}</div>${partes.length<2?quadro:""}${btn}
${h3EmailFundos()}<p style="${F};font-size:11px;color:#9aa1ad;margin:10px 0 0">Escola Profissional da Ilha de São Jorge · mensagem enviada pela EPISJ 360</p></div></body></html>`}
/* 0.9.169: logótipos do ano letivo no email — em cima o logótipo principal (e o do canto direito, se houver), em baixo a barra de
   financiamento do ano (a mesma da barra de baixo da app). As imagens seguem como anexos embutidos (cid:, ver msEmbutir em o365.js). */
function h3LgImg(o,maxW,maxH,alt){if(!o||!o.src||!/^data:image\//.test(o.src))return "";const w0=+o.w||maxW,h0=+o.h||maxH,k=Math.min(1,maxW/w0,maxH/h0),w=Math.max(1,Math.round(w0*k)),h=Math.max(1,Math.round(h0*k));
  return `<img src="${esc(o.src)}" width="${w}" height="${h}" alt="${esc(alt)}" style="display:block;border:0;width:${w}px;height:${h}px;max-width:100%">`}
function h3EmailTopo(F){let m,r;try{m=lgGet("main");r=lgGet("right")}catch(e){}
  const a=h3LgImg(m,220,52,"Escola Profissional da Ilha de São Jorge"),b=h3LgImg(r,200,52,"");
  // 0.9.170: cabeçalho com o nome da escola, o ano letivo e a data do horário (última importação/publicação do ano)
  let ano="",dt="";try{const A=anoAtivo();if(A){ano=anoNomeChave(A.nome)||A.nome||"";const q=ESD.porAno&&ESD.porAno[A.id]&&ESD.porAno[A.id].quando;if(q)dt=new Date(q).toLocaleDateString("pt-PT",{day:"numeric",month:"long",year:"numeric"})}}catch(e){}
  const sub=[ano?"Ano letivo "+ano:"",dt?"Horário de "+dt:""].filter(Boolean).join(" · ");
  const tit=`<div style="${F};margin:0 0 18px;text-align:center"><div style="font-size:16px;font-weight:700;color:#163269;line-height:1.3">Escola Profissional da Ilha de São Jorge</div>${sub?`<div style="font-size:13px;color:#4a5262;margin-top:2px">${esc(sub)}</div>`:""}</div>`;
  if(!a&&!b)return tit;
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:760px;margin:0 0 14px;border-bottom:1px solid #e3e7ee"><tr><td style="padding:0 0 12px;vertical-align:middle">${a}</td><td style="padding:0 0 12px;vertical-align:middle" align="right">${b}</td></tr></table>`+tit}
function h3EmailFundos(){let f;try{f=lgFootBarra()}catch(e){try{f=lgGet("foot")}catch(x){}}const im=h3LgImg(f,560,64,"Logótipos de financiamento do ano letivo");
  return im?`<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:760px;margin:22px 0 0;border-top:1px solid #e3e7ee"><tr><td align="center" style="padding:14px 0 0">${im}</td></tr></table>`:""}
function h3SmsLink(L){L=L.filter(x=>!x.tlOk);const nums=L.map(x=>h3Tel(H3.tel[(x.p||{}).id])).filter(Boolean);if(!nums.length)return "";
  const body=encodeURIComponent(L.length===1?h3Preencher(H3.msg.curta,L[0]):"EPISJ 360: o seu horário mudou. Veja em "+h3Lig()),ios=/iPhone|iPad|Macintosh/.test(navigator.userAgent);
  return ios?`sms:/open?addresses=${nums.join(",")}&body=${body}`:`sms:${nums.join(",")}?body=${body}`}
async function h3Enviar(L,canais,msg,forcar){ // 0.9.164: forcar = envio pedido à mão (manda a todos os escolhidos, também a quem já tinha recebido por essa via)
if(H3_ENVIO||!L.length)return;H3_ENVIO=true;let ok=0,erros=[],nomes=[];
  // 0.9.155: a sessão do Office 365 é pedida logo no início (ainda no clique, para a janela da Microsoft não ser bloqueada);
  // se não houver sessão, diz uma vez porquê em vez de falhar formador a formador
  if(canais.includes("email")&&L.some(x=>forcar||!x.emOk)){try{await msToken()}catch(e){H3_ENVIO=false;const m=typeof msErro==="function"?msErro(e):(e.message||String(e));
    return{ok:0,erros:["Os emails não saíram: "+m+" Carregue em «Ligar a conta da Microsoft» (por cima dos botões) e depois envie outra vez."]}}}
  try{for(let i=0;i<L.length;i++){const x=L[i],feito=[];if(msg)msg(`A enviar ${i+1} de ${L.length}…`);
      const fazEm=canais.includes("email")&&(forcar||!x.emOk),fazTl=canais.includes("push")&&(forcar||!x.tlOk);
      if(fazEm)try{await h3Email1(x);feito.push("email")}catch(e){erros.push((x.t.name||"")+": email — "+(e.message||e))}
      if(fazTl)try{await h3Push(x);feito.push("push")}catch(e){erros.push((x.t.name||"")+": notificação — "+(e.message||e))}
      if(feito.length){h3Marcar(x,feito);ok++;nomes.push(((x.p&&x.p.nome)||x.t.name||"")+" ("+feito.map(c=>c==="email"?"email para "+h3Email(x.p):"notificação").join(" e ")+")")}
      if(fazEm&&i<L.length-1)await new Promise(r=>setTimeout(r,2100))}}
  finally{H3_ENVIO=false;h3Guardar()}
  return{ok,erros,nomes}}
// avisos automáticos: do navegador de quem é da Direção, alguns minutos depois de o horário mudar (um computador de cada vez)
async function h3AutoVer(){try{if(!H3||!H3.auto.on||RO||H3_ENVIO||!podePublicar())return;const a=anoAtivo(),x=ESD.porAno&&ESD.porAno[a.id];if(!x||!x.quando)return;
    if(Date.now()-x.quando<(+H3.auto.min||10)*60000||curTab==="esch")return;const L=h3Pendentes();if(!L.length)return;
    const can=[];if(H3.auto.email&&MSACC)can.push("email");if(H3.auto.push)can.push("push");if(!can.length)return;
    if(!(await trincoNuvem("h3-auto",300)))return;const r=await h3Enviar(L,can);if(r&&r.ok)toast(`Horários360: ${r.ok} formador${r.ok===1?"":"es"} avisado${r.ok===1?"":"s"} das alterações do horário`);if(curTab==="hsCom")hsComRender()}catch(e){console.warn("Horários360/avisos",e)}}
setInterval(h3AutoVer,60000);

async function hsComRender(){await null;try{await esdPronto}catch(e){}await h3Carregar();const el=$("#hsComOut");if(!el)return;
  if(!podePublicar()||RO){el.innerHTML=`<div class="msg info">Só a Direção comunica os horários.</div>`;return}
  if(!H3.sal){try{await h3TrazerNuvem()}catch(e){}if(!H3.sal){H3.sal=h3Sal();H3.salT=Date.now();h3Guardar()}}
  const st=mhEstado(),L=st?h3Pendentes():[],ms=!!MSACC;
  $("#hsComHero").innerHTML=`<div class="ay-hero"><div class="ay-top"><div><h1>Comunicar horários</h1><div class="sub">Avisa cada formador quando o horário vindo do Untis muda — só o que mudou para ele.</div></div><span class="grow"></span><div class="ay-pct"><b>${L.length}</b>formador${L.length===1?"":"es"} por avisar</div></div></div>`;
  if(!st){el.innerHTML=`<div class="pp-vz">${ICO.cal}<p>Ainda não há horário para ${esc(anoAtivo().nome)}. Importe os PDF do Untis em «Semana».</p></div>`;return}
  const sms=h3SmsLink(L),semEm=L.filter(x=>!h3Email(x.p)).length;
  let h=`<div class="card"><h3 style="margin:0 0 4px">Por avisar</h3>
    <p class="hint" style="margin:0 0 10px">${L.length?"Formadores com o horário diferente do último aviso. Cada um só sai da lista depois de avisado pelas duas vias: email e telemóvel (notificação, SMS ou WhatsApp). Quem já foi avisado por uma via só recebe a outra.":"Todos os formadores já foram avisados do horário atual, por email e por telemóvel."}</p>`;
  if(L.length){h+=`<div class="tw"><table class="rt"><thead><tr><th><input type="checkbox" id="h3All" checked aria-label="Todos"></th><th>Formador</th><th>Email</th><th>Telemóvel</th><th>Avisado por</th><th>O que mudou</th></tr></thead><tbody>`+
    L.map(x=>`<tr><td><input type="checkbox" data-h3sel="${esc(x.t.id)}" checked></td><td>${esc((x.p&&x.p.nome)||x.t.name)}</td><td>${esc(h3Email(x.p)||"—")}</td><td>${esc(h3Tel(H3.tel[(x.p||{}).id])||"—")}</td>
      <td><span class="h3via ${x.emOk?"ok":""}">${x.emOk?"✓ ":""}Email</span> <span class="h3via ${x.tlOk?"ok":""}">${x.tlOk?"✓ ":""}Telemóvel</span></td>
      <td><details><summary>${x.novo?"horário novo ("+x.cur.length+" tempo"+(x.cur.length===1?"":"s")+")":`${x.mais.length?"+"+x.mais.length:""}${x.mais.length&&x.menos.length?" / ":""}${x.menos.length?"−"+x.menos.length:""}`}</summary><pre class="h3dif">${esc(h3Txt(x))}</pre></details> <button class="b s" type="button" data-h3prev="${esc(x.t.id)}" title="Ver o email que este formador vai receber">Ver email</button></td></tr>`).join("")+`</tbody></table></div>
    <div class="h3ms">${ms?`Os emails saem de <b>${esc(MSACC.username||"")}</b>.`:`<span>Para enviar emails é preciso a sua conta da Microsoft neste navegador.</span><button class="b s" type="button" id="h3MsLig">Ligar a conta da Microsoft</button>`}</div>
    <div class="row" style="margin-top:10px;flex-wrap:wrap;gap:8px">
      <button class="b" id="h3Em">Enviar email</button>
      <button class="b" id="h3Pu">Enviar notificação ao telemóvel</button>
      <button class="b" id="h3EmPu">Email e notificação</button>
      ${sms?`<a class="b s" id="h3Sms" href="${esc(sms)}">SMS pelo telemóvel</a>`:""}
      <button class="b s" id="h3Wa" title="Abre o WhatsApp com a mensagem de cada formador já escrita (gratuito)">WhatsApp um a um</button>
      <span class="grow"></span><button class="b s" id="h3Marc" title="Dar como avisados sem enviar nada">Marcar como avisados</button></div>
    <p class="hint" id="h3Msg" style="margin:8px 0 0">${ms?"":"Para enviar emails, entre com o Office 365 da escola (como para os outros envios). "}${semEm?semEm+" sem email em Escola360 › Formadores. ":""}</p>`}
  h+=`</div>`;
  // 0.9.170: turmas (formandos) pelo WhatsApp
  const LC=h3PendentesC();
  h+=`<div class="card"><h3 style="margin:0 0 4px">Turmas — avisar os formandos pelo WhatsApp</h3>
    <p class="hint" style="margin:0 0 10px">${LC.length?"Turmas com o horário diferente do último aviso. Use o grupo de avisos da turma (texto pronto a copiar) ou envie aos formandos um a um. Os telemóveis dos formandos escrevem-se em Escola360 › Formandos (ficam só com a Direção). Gratuito: sai pelo WhatsApp de quem envia.":"Todas as turmas já foram avisadas do horário atual."}</p>`;
  if(LC.length){h+=`<div class="tw"><table class="rt"><thead><tr><th>Turma</th><th>Formandos com telemóvel</th><th>O que mudou</th><th></th></tr></thead><tbody>`+
    LC.slice(0,80).map(x=>{const F=h3FormandosC(x),ct=F.filter(f=>waTelFor(f)).length;return `<tr><td><b>${esc((x.t&&x.t.cod)||x.c.name)}</b>${x.t?"":` <small class="hint">(sem turma na Escola360)</small>`}</td><td>${ct} de ${F.length}</td>
      <td><details><summary>${x.novo?"horário ("+x.cur.length+" tempo"+(x.cur.length===1?"":"s")+")":`${x.mais.length?"+"+x.mais.length:""}${x.mais.length&&x.menos.length?" / ":""}${x.menos.length?"−"+x.menos.length:""}`}</summary><pre class="h3dif">${esc(h3TxtC(x))}</pre></details></td>
      <td style="white-space:nowrap"><button class="b s" type="button" data-h3wag="${esc(x.c.id)}">Grupo da turma</button> <button class="b s" type="button" data-h3waf="${esc(x.c.id)}"${ct?"":" disabled title=\"Nenhum formando desta turma tem telemóvel\""}>Formandos um a um</button> <button class="b s" type="button" data-h3wam="${esc(x.c.id)}" title="Dar a turma como avisada sem enviar nada">Marcar</button></td></tr>`}).join("")+`</tbody></table></div>
    ${LC.length>80?`<p class="hint">E mais ${LC.length-80} turmas.</p>`:""}<div class="row" style="margin-top:8px"><span class="grow"></span><button class="b s" type="button" id="h3WaMT">Marcar todas as turmas como avisadas</button></div>`}
  h+=`</div>`;
  // avisos automáticos
  h+=`<div class="card"><h3 style="margin:0 0 4px">Avisos automáticos</h3>
    <label class="chk"><input type="checkbox" data-h3a="on"${H3.auto.on?" checked":""}> Avisar sozinho os formadores ${esc(String(H3.auto.min))} minutos depois de o horário mudar (por exemplo, depois de importar os PDF do Untis)</label>
    <div class="row" style="gap:16px;margin-top:6px"><label class="chk"><input type="checkbox" data-h3a="email"${H3.auto.email?" checked":""}> por email</label><label class="chk"><input type="checkbox" data-h3a="push"${H3.auto.push?" checked":""}> por notificação no telemóvel</label></div>
    <p class="hint" style="margin:6px 0 0">Os avisos saem do navegador de quem é da Direção e tem a EPISJ 360 aberta (um computador de cada vez). O SMS pelo telemóvel é sempre à mão.</p></div>`;
  // mensagem
  h+=`<div class="card"><h3 style="margin:0 0 4px">Mensagem</h3><p class="hint" style="margin:0 0 8px">Pode usar {nome}, {alteracoes}, {ligacao}, {semana} e, na mensagem curta, {n}.</p>
    <label class="h3lb">Assunto do email<input type="text" data-h3m2="assunto" value="${esc(H3.msg.assunto)}"></label>
    <label class="h3lb">Email<textarea data-h3m2="corpo" rows="9">${esc(H3.msg.corpo)}</textarea></label>
    <label class="h3lb">Mensagem curta (notificação e SMS)<input type="text" data-h3m2="curta" value="${esc(H3.msg.curta)}"></label>
    <label class="h3lb">WhatsApp aos formadores <small class="hint">— também {primeiro_nome}</small><textarea data-h3m2="wa" rows="6">${esc(H3.msg.wa)}</textarea></label>
    <label class="h3lb">WhatsApp às turmas <small class="hint">— {turma}, {alteracoes}, {semana}, {ligacao}; um a um também {primeiro_nome}</small><textarea data-h3m2="waT" rows="6">${esc(H3.msg.waT)}</textarea></label>
    <div class="row" style="margin-top:6px"><button class="b s" id="h3MsgRep">Repor as mensagens originais</button></div></div>`;
  // contactos
  const F=(st.teachers||[]).map(t=>({t,p:h3ProfDe(st,t.id)})).filter(x=>x.p).sort((a,b)=>COLL_PT.compare(a.p.nome,b.p.nome));
  h+=`<div class="card"><h3 style="margin:0 0 4px">Contactos dos formadores</h3>
    <p class="hint" style="margin:0 0 8px">O email vem de Escola360 › Formadores. Os telemóveis servem para o SMS e o WhatsApp e ficam só com a Direção (não são publicados). O tópico é o que cada formador escreve na app ntfy para receber as notificações — também o vê em Horários360 › Semana.</p>
    <div class="tw"><table class="rt"><thead><tr><th>Formador</th><th>Email</th><th>Telemóvel</th><th>Tópico das notificações</th></tr></thead><tbody>`+
    F.map(({p})=>{const tp=h3Topico(h3Email(p));return `<tr><td>${esc(p.nome)}</td><td>${esc(h3Email(p)||"—")}</td><td><input type="text" data-h3tel="${esc(p.id)}" value="${esc(H3.tel[p.id]||"")}" placeholder="9xx xxx xxx" inputmode="tel" style="width:140px"></td><td>${tp?`<code class="h3top">${esc(tp)}</code> <button class="b s" data-h3cp="${esc(tp)}" title="Copiar">Copiar</button>`:"—"}</td></tr>`}).join("")+`</tbody></table></div></div>`;
  // como funciona
  h+=`<div class="card"><h3 style="margin:0 0 4px">Como chegam os avisos (tudo gratuito)</h3><ul class="hint" style="margin:0;padding-left:18px">
    <li><b>Email</b> — pela conta do Office 365 da escola de quem envia, como os outros envios da EPISJ 360.</li>
    <li><b>Notificação no telemóvel</b> — pelo <b>ntfy</b> (serviço gratuito e de código aberto, sem conta): o formador instala a app ntfy e subscreve o seu tópico. Chega como uma mensagem, mas não gasta SMS. A mensagem só diz que o horário mudou e onde o ver.</li>
    <li><b>WhatsApp</b> — gratuito: a app abre o WhatsApp de quem envia (no computador ou no telemóvel) com o número e a mensagem já escritos, e basta carregar em Enviar; passa-se de pessoa em pessoa. Para as turmas há também o texto pronto para o grupo de avisos da turma.</li>
    <li><b>SMS</b> — não há serviço de SMS gratuito em Portugal para muitos envios (os gratuitos dão 1 SMS por dia ou só créditos de teste). Por isso o botão abre a app Mensagens do telemóvel (ou do Mac) com os números e o texto já preenchidos: sai pelo tarifário do telemóvel da escola.</li></ul></div>`;
  // histórico
  const E=H3.env.slice(-30).reverse();
  if(E.length)h+=`<div class="card"><h3 style="margin:0 0 6px">Últimos avisos</h3><div class="tw"><table class="rt"><thead><tr><th>Quando</th><th>Formador</th><th>Por</th><th>Enviado por</th></tr></thead><tbody>`+
    E.map(e=>`<tr><td>${esc(new Date(e.t).toLocaleString("pt-PT",{dateStyle:"short",timeStyle:"short"}))}</td><td>${esc(e.quem)}</td><td>${esc((e.canais||[]).map(c=>({email:"email",push:"notificação",sms:"SMS",wa:"WhatsApp",marca:"marcado à mão"})[c]||c).join(", "))}</td><td>${esc(e.por)}</td></tr>`).join("")+`</tbody></table></div></div>`;
  el.innerHTML=h;
  const sel=()=>{const ids=new Set([...el.querySelectorAll("[data-h3sel]:checked")].map(i=>i.dataset.h3sel));return L.filter(x=>ids.has(x.t.id))};
  const m=t=>{const e=$("#h3Msg");if(e)e.textContent=t};
  const go=async can=>{const S=sel();if(!S.length){toast("Escolha pelo menos um formador");return}
    if(!confirm(`Enviar ${can.map(c=>c==="email"?"email":"notificação").join(" e ")} a ${S.length} formador${S.length===1?"":"es"}?`))return;
    const r=await h3Enviar(S,can,m,true);if(!r)return;toast(`${r.ok} formador${r.ok===1?"":"es"} avisado${r.ok===1?"":"s"}`);hsComRender().then(()=>{const e=$("#h3Msg");if(!e)return;e.innerHTML=(r.nomes&&r.nomes.length?`<span style="color:var(--ok,#1a7f45)">Enviado: ${r.nomes.slice(0,10).map(esc).join("; ")}${r.nomes.length>10?" e mais "+(r.nomes.length-10):""}.</span>`:"")+(r.erros.length?`${r.nomes&&r.nomes.length?"<br>":""}<span style="color:var(--bad)">${r.erros.slice(0,8).map(esc).join("<br>")}</span>`:"")})};
  // 0.9.156: o botão liga a conta da Microsoft logo no clique (a janela não é bloqueada); sem conta carregada, tenta recuperá-la da sessão do navegador
  const bl=$("#h3MsLig");if(bl)bl.onclick=async()=>{try{await msLoginPopup();toast("Conta da Microsoft ligada");hsComRender()}catch(e){m(typeof msErro==="function"?msErro(e):String(e.message||e))}};
  if(!ms&&!window.__h3MsTent){window.__h3MsTent=1;msInit().then(()=>{if(MSACC)hsComRender()}).catch(()=>{})}
  const b1=$("#h3Em"),b2=$("#h3Pu"),b3=$("#h3EmPu"),b4=$("#h3Marc"),b5=$("#h3Sms"),all=$("#h3All");
  if(b1)b1.onclick=()=>go(["email"]);if(b2)b2.onclick=()=>go(["push"]);if(b3)b3.onclick=()=>go(["email","push"]);
  if(all)all.onchange=()=>{el.querySelectorAll("[data-h3sel]").forEach(i=>i.checked=all.checked);h3SmsAtual()};
  el.querySelectorAll("[data-h3sel]").forEach(i=>i.onchange=h3SmsAtual);
  function h3SmsAtual(){if(b5){const s=h3SmsLink(sel());if(s)b5.href=s;b5.hidden=!s}}
  if(b5)b5.onclick=()=>{setTimeout(()=>{const S=sel().filter(x=>!x.tlOk&&h3Tel(H3.tel[(x.p||{}).id]));if(S.length&&confirm("A mensagem foi enviada pelo telemóvel? Os "+S.length+" formadores com telemóvel ficam como avisados por telemóvel."))
    {S.forEach(x=>h3Marcar(x,["sms"]));h3Guardar();hsComRender()}},1500)};
  if(b4)b4.onclick=()=>{const S=sel();if(!S.length)return;if(!confirm(`Dar ${S.length} formador${S.length===1?"":"es"} como avisado${S.length===1?"":"s"} pelas duas vias sem enviar nada?`))return;S.forEach(x=>h3Marcar(x,["marca"]));h3Guardar();hsComRender()};
  // 0.9.170: WhatsApp
  const bw=$("#h3Wa");if(bw)bw.onclick=()=>{const S=sel();if(!S.length){toast("Escolha pelo menos um formador");return}
    waFila(S.map(x=>({id:x.t.id,x,nome:(x.p&&x.p.nome)||x.t.name||"",tel:h3Tel(H3.tel[(x.p||{}).id]),txt:waPreencher(h3Preencher(H3.msg.wa,x),(x.p&&x.p.nome)||x.t.name||"")})),{titulo:"Horário por WhatsApp — formadores",
      onFeito:y=>{h3Marcar(y.x,["wa"]);waRegistar("h3",y.id,y.nome)},fim:n=>{if(n)hsComRender()}})};
  const xC=id=>LC.find(y=>y.c.id===id);
  el.querySelectorAll("[data-h3wag]").forEach(b=>b.onclick=()=>{const x=xC(b.dataset.h3wag);if(!x)return;
    waGrupo("Grupo da turma "+((x.t&&x.t.cod)||x.c.name),h3PreencherC(H3.msg.waT,x,"").replace(/Olá ,/g,"Olá a todos,"),{sub:"Copie e cole no grupo de avisos da turma, ou abra o WhatsApp e escolha o grupo. A turma fica como avisada.",onFeito:()=>{h3MarcarC(x);waRegistar("h3t",x.c.id,"grupo");setTimeout(hsComRender,400)}})});
  el.querySelectorAll("[data-h3waf]").forEach(b=>b.onclick=()=>{const x=xC(b.dataset.h3waf);if(!x)return;const F=h3FormandosC(x),com=F.filter(f=>waTelFor(f)).length;
    waFila(F.map(f=>({id:f.id,nome:f.nome,tel:waTelFor(f),txt:h3PreencherC(H3.msg.waT,x,f.nome)})),{titulo:"Horário da turma "+((x.t&&x.t.cod)||x.c.name)+" — formandos",
      sub:"Depois de enviar a todos, a turma fica como avisada.",onFeito:f=>waRegistar("h3t",x.c.id,f.nome),fim:n=>{if(n&&n>=com){h3MarcarC(x);h3Guardar()}if(n)hsComRender()}})});
  el.querySelectorAll("[data-h3wam]").forEach(b=>b.onclick=()=>{const x=xC(b.dataset.h3wam);if(!x)return;h3MarcarC(x);h3Guardar();hsComRender()});
  const bmt=$("#h3WaMT");if(bmt)bmt.onclick=()=>{if(!confirm(`Dar as ${LC.length} turmas como avisadas sem enviar nada?`))return;LC.forEach(h3MarcarC);h3Guardar();hsComRender()};
  el.querySelectorAll("[data-h3prev]").forEach(b=>b.onclick=()=>{const x=L.find(y=>y.t.id===b.dataset.h3prev);if(!x)return;const w=window.open("","_blank");if(!w){toast("O navegador bloqueou a janela — permita janelas deste site");return}
    w.document.open();w.document.write(h3EmailHtml(x).replace("<body",`<body`).replace('<div style="max-width:780px;padding:8px 4px">',`<div style="max-width:780px;padding:8px 4px"><p style="font-family:Segoe UI,Arial,sans-serif;font-size:12px;color:#6b7385;margin:0 0 14px">Pré-visualização · Para: ${esc(h3Email(x.p))} · Assunto: ${esc(h3Preencher(H3.msg.assunto,x))}</p>`));w.document.close()});
  el.querySelectorAll("[data-h3a]").forEach(i=>i.onchange=()=>{H3.auto[i.dataset.h3a]=i.checked;h3Guardar()});
  el.querySelectorAll("[data-h3m2]").forEach(i=>i.onchange=()=>{H3.msg[i.dataset.h3m2]=i.value;h3Guardar()});
  $("#h3MsgRep").onclick=()=>{if(!confirm("Repor as mensagens originais?"))return;H3.msg=Object.assign({},H3_MSG0);h3Guardar();hsComRender()};
  el.querySelectorAll("[data-h3tel]").forEach(i=>i.onchange=()=>{const v=i.value.trim();if(v&&!h3Tel(v)){toast("Número de telemóvel inválido");return}H3.tel[i.dataset.h3tel]=v?h3Tel(v):"";h3Guardar()})}
h3Carregar();
// ===== src/js/core/whatsapp.js =====
/* ===================== WhatsApp (0.9.170) — avisos gratuitos, um clique de cada vez =====================
   A app escreve cada mensagem e abre o WhatsApp (ligação wa.me) com o número e o texto já preenchidos: quem está na escola
   só carrega em «Enviar». Não há custos nem contas na Meta; é só num sentido (escola → formadores / formandos).
   · Fila «um a um» (waFila): passa de pessoa em pessoa; cada «Abrir no WhatsApp» conta como enviado.
   · Texto para um grupo (waGrupo): copiar ou abrir o WhatsApp para escolher o grupo (ex.: grupo de avisos da turma).
   · Aviso livre (waCompor): formadores e/ou formandos de turmas escolhidas.
   Telemóveis: formadores em H3.tel[profId] (já existia, Horários360) e formandos em H3.telF[formandoId] — peça H3 da
   g360_estado, que só a Direção lê. NUNCA pôr o telemóvel em escola.formandos: a escola publicada leva a lista de
   formandos para os formadores. Registo dos envios em H3.wa (os últimos 300). */
function waNum(tel){const t=h3Tel(tel);return t?t.replace(/^\+/,""):""}
function waLink(tel,txt){return "https://wa.me/"+waNum(tel)+"?text="+encodeURIComponent(String(txt||""))}
function waTelVer(tel){const t=h3Tel(tel);if(!t)return "";const m=/^\+351(\d{3})(\d{3})(\d{3})$/.exec(t);return m?`${m[1]} ${m[2]} ${m[3]}`:t}
function waTelProf(p){return (H3&&p&&h3Tel(H3.tel[p.id]))||""}
function waTelFor(f){return (H3&&f&&h3Tel((H3.telF||{})[f.id]))||""}
function waPrimeiro(n){return String(n||"").trim().split(/\s+/)[0]||""}
function waPreencher(tpl,nome){return String(tpl||"").replace(/\{primeiro_nome\}/g,waPrimeiro(nome)).replace(/\{nome\}/g,String(nome||""))}
// grava um telemóvel (formador: "p", formando: "f"); devolve false se o número não for válido. Vazio apaga só esse número.
function waTelGravar(tipo,id,v){if(!H3||!id)return false;v=String(v||"").trim();const n=v?h3Tel(v):"";if(v&&!n)return false;
  if(tipo==="f"){H3.telF=H3.telF||{};H3.telF[id]=n}else H3.tel[id]=n;h3Guardar();return true}
function waRegistar(o,id,quem){if(!H3)return;H3.wa=H3.wa||[];H3.wa.push({t:Date.now(),por:(EU&&EU.email)||"",o,id:id||"",q:quem||""});if(H3.wa.length>300)H3.wa=H3.wa.slice(-300);h3Guardar()}
function waUltimo(o,id){if(!H3||!H3.wa)return 0;let t=0;for(const x of H3.wa)if(x.o===o&&x.id===id&&x.t>t)t=x.t;return t}
// os telemóveis vivem na peça H3: antes de os usar fora do Horários360, carregar e juntar com a nuvem
async function waPronto(){try{await h3Carregar();if(!H3_SINC)await h3TrazerNuvem()}catch(e){}return !!H3}

/* ---------- janela ---------- */
function waJanela(html){waFechar();const bg=document.createElement("div");bg.className="wa-bg";bg.id="waBg";bg.innerHTML=`<div class="wa-box" role="dialog" aria-modal="true">${html}</div>`;
  document.body.appendChild(bg);bg.addEventListener("click",e=>{if(e.target===bg||e.target.closest("[data-wafecha]"))waFechar()});
  document.addEventListener("keydown",waEsc);return bg}
function waEsc(e){if(e.key==="Escape")waFechar()}
function waFechar(){const b=$("#waBg");if(b){b.remove();if(typeof b._fim==="function")try{b._fim()}catch(e){}}document.removeEventListener("keydown",waEsc)}
const WA_ICO=`<svg viewBox="0 0 24 24" width="16" height="16" aria-hidden="true" style="fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;vertical-align:-3px"><path d="M3.5 20.5l1.3-4A8.5 8.5 0 1 1 8 19.6z"/><path d="M9 9.5c.3 2 2.2 4.2 5 5l1-1.2 1.8.8-.3 1.4c-3.6.4-7.6-3.3-7.8-7l1.4-.4.9 1.7z"/></svg>`;

/* ---------- um a um ----------
   itens: [{id, nome, tel, txt}]; quem não tem telemóvel fica de fora (contado). opt: {titulo, sub, onFeito(item), fim()} */
function waFila(itens,opt){opt=opt||{};const L=(itens||[]).filter(x=>waNum(x.tel)),sem=(itens||[]).filter(x=>!waNum(x.tel));
  if(!L.length){toast(sem.length?`Ninguém com telemóvel (${sem.length} sem número) — escreva os telemóveis primeiro`:"Ninguém para avisar");return}
  let i=0;const feito=new Set();
  const bg=waJanela(`<div class="wa-h"><div><b>${esc(opt.titulo||"Enviar por WhatsApp")}</b><small id="waCnt"></small></div><button class="x" type="button" data-wafecha title="Fechar">×</button></div>
    ${opt.sub?`<p class="hint" style="margin:0 0 10px">${esc(opt.sub)}</p>`:""}
    <div class="wa-quem" id="waQuem"></div>
    <textarea id="waTxt" rows="8" spellcheck="true"></textarea>
    <div class="row wa-bt"><a class="b" id="waAbrir" target="_blank" rel="noopener">${WA_ICO} Abrir no WhatsApp</a><button class="b s" type="button" id="waSeg">Seguinte</button><button class="b s" type="button" id="waAnt">Anterior</button><span class="grow"></span><button class="b s" type="button" data-wafecha>Terminar</button></div>
    <p class="hint" style="margin:8px 0 0">No WhatsApp carregue em <b>Enviar</b>, volte a esta janela e passe ao seguinte. Pode mudar o texto antes de abrir.${sem.length?` <b>${sem.length}</b> sem telemóvel ficaram de fora: ${esc(sem.slice(0,6).map(x=>x.nome).join(", "))}${sem.length>6?"…":""}.`:""}</p>
    <ol class="wa-lista" id="waLista"></ol>`);
  bg._fim=()=>{if(typeof opt.fim==="function")opt.fim(feito.size)};
  const txt=$("#waTxt"),ab=$("#waAbrir");
  const desenha=()=>{const x=L[i];$("#waCnt").textContent=` · ${i+1} de ${L.length} · ${feito.size} enviado${feito.size===1?"":"s"}`;
    $("#waQuem").innerHTML=`<b>${esc(x.nome)}</b><span>${esc(waTelVer(x.tel))}</span>${feito.has(i)?`<span class="tag ok">aberto no WhatsApp</span>`:""}`;
    txt.value=x.txt;ab.href=waLink(x.tel,x.txt);$("#waAnt").disabled=i===0;$("#waSeg").textContent=i===L.length-1?"Terminar":"Seguinte";
    $("#waLista").innerHTML=L.map((y,k)=>`<li class="${k===i?"cur":""}${feito.has(k)?" ok":""}"><button type="button" data-wak="${k}">${esc(y.nome)}</button>${feito.has(k)?" ✓":""}</li>`).join("")};
  txt.oninput=()=>{L[i].txt=txt.value;ab.href=waLink(L[i].tel,txt.value)};
  ab.onclick=()=>{if(!feito.has(i)){feito.add(i);try{if(opt.onFeito)opt.onFeito(L[i])}catch(e){console.warn("WhatsApp",e)}}setTimeout(desenha,50);$("#waSeg").focus()};
  $("#waSeg").onclick=()=>{if(i>=L.length-1){waFechar();return}i++;desenha()};
  $("#waAnt").onclick=()=>{if(i>0){i--;desenha()}};
  $("#waLista").onclick=e=>{const b=e.target.closest("[data-wak]");if(b){i=+b.dataset.wak;desenha()}};
  desenha()}

/* ---------- texto para um grupo ---------- */
function waGrupo(titulo,txt,opt){opt=opt||{};
  waJanela(`<div class="wa-h"><div><b>${esc(titulo||"Texto para o grupo")}</b></div><button class="x" type="button" data-wafecha title="Fechar">×</button></div>
    <p class="hint" style="margin:0 0 10px">${esc(opt.sub||"Copie e cole no grupo do WhatsApp, ou abra o WhatsApp e escolha o grupo.")}</p>
    <textarea id="waTxt" rows="10"></textarea>
    <div class="row wa-bt"><button class="b" type="button" id="waCp">Copiar o texto</button><a class="b s" id="waAbrir" target="_blank" rel="noopener">${WA_ICO} Abrir no WhatsApp e escolher o grupo</a><span class="grow"></span><button class="b s" type="button" data-wafecha>Fechar</button></div>`);
  const t=$("#waTxt"),ab=$("#waAbrir");t.value=txt||"";ab.href=waLink("",t.value);t.oninput=()=>{ab.href=waLink("",t.value)};
  let feito=false;const marca=()=>{if(!feito){feito=true;try{if(opt.onFeito)opt.onFeito()}catch(e){}}};
  $("#waCp").onclick=()=>{copy(t.value);marca()};ab.onclick=marca}

/* ---------- aviso livre (formadores e/ou turmas) ---------- */
async function waCompor(pre){pre=pre||{};if(!podePublicar()||RO){toast("Só a Direção envia avisos");return}await waPronto();
  const E=escData(),a=anoAtivo(),viva=t=>{try{return forTurmaViva(t)}catch(e){return true}};
  const T=E.turmas.filter(viva).map(t=>({t,fs:E.formandos.filter(f=>f.turmaId===t.id&&!f.estado)})).filter(x=>x.fs.length).sort((x,y)=>COLL_PTN.compare(x.t.cod||"",y.t.cod||""));
  const nP=cfg.profs.filter(p=>waTelProf(p)).length;
  waJanela(`<div class="wa-h"><div><b>Aviso por WhatsApp</b><small> · gratuito, um clique por pessoa</small></div><button class="x" type="button" data-wafecha title="Fechar">×</button></div>
    <div class="wa-dest"><label class="chk"><input type="checkbox" id="waCP"${pre.formadores?" checked":""}> Formadores <small>(${nP} de ${cfg.profs.length} com telemóvel)</small></label>
    <div class="wa-tur">${T.map(({t,fs})=>`<label class="chk"><input type="checkbox" data-watur="${esc(t.id)}"${(pre.turmas||[]).includes(t.id)?" checked":""}> ${esc(t.cod||turmaNome(t))} <small>(${fs.filter(f=>waTelFor(f)).length}/${fs.length})</small></label>`).join("")||`<span class="hint">Sem turmas com formandos em ${esc(a.nome)}.</span>`}</div></div>
    <label class="h3lb" style="margin-top:8px">Mensagem <small class="hint">— pode usar {primeiro_nome} e {nome}</small><textarea id="waMsg" rows="7">${esc(pre.txt||"Olá {primeiro_nome},\n\n\n\nCom os melhores cumprimentos,\nDireção Pedagógica — EPISJ")}</textarea></label>
    <div class="row wa-bt"><button class="b" type="button" id="waUm">${WA_ICO} Um a um no WhatsApp</button><button class="b s" type="button" id="waGr">Texto para o grupo</button><span class="grow"></span><span class="hint" id="waN" style="margin:0"></span></div>`);
  const dest=()=>{const out=[];if($("#waCP").checked)cfg.profs.forEach(p=>out.push({id:"p:"+p.id,nome:p.nome,tel:waTelProf(p),tipo:"p"}));
    document.querySelectorAll("[data-watur]:checked").forEach(c=>{const x=T.find(y=>y.t.id===c.dataset.watur);if(x)x.fs.forEach(f=>out.push({id:"f:"+f.id,nome:f.nome,tel:waTelFor(f),tipo:"f",tur:x.t.cod}))});return out};
  const conta=()=>{const D=dest(),c=D.filter(x=>waNum(x.tel)).length;$("#waN").textContent=D.length?`${c} de ${D.length} com telemóvel`:"Escolha os destinatários"};
  document.querySelectorAll("#waCP,[data-watur]").forEach(i=>i.onchange=conta);conta();
  $("#waUm").onclick=()=>{const D=dest(),m=$("#waMsg").value;if(!D.length){toast("Escolha os destinatários");return}
    waFila(D.map(x=>Object.assign({},x,{txt:waPreencher(m,x.nome)})),{titulo:"Aviso por WhatsApp",onFeito:x=>waRegistar("aviso",x.id,x.nome)})};
  $("#waGr").onclick=()=>{const m=$("#waMsg").value.replace(/Olá \{primeiro_nome\},?/,"Olá a todos,").replace(/\{primeiro_nome\}|\{nome\}/g,"");waGrupo("Texto para o grupo",m,{onFeito:()=>waRegistar("grupo","","aviso")})}}

$("#forWa").onclick=()=>{const t=$("#forTurmaF").value;waCompor({turmas:t?[t]:[]})};
$("#profWa").onclick=()=>waCompor({formadores:true});
// ===== src/js/sala/sala.js =====
/* ---------- módulo RoomCheck: reservas do Auditório e dos Laboratórios de Informática 1 e 2 ----------
   Guardado neste navegador ("roomcheck") e na nuvem da EPISJ 360 (nome "rc"), junto por reserva: em cada uma vence a alteração mais recente
   (as canceladas ficam marcadas x:1 durante 90 dias para não voltarem de outro computador). Nada vai para a Box. */
const RC_VER="1.3";
document.querySelectorAll("[data-rcver]").forEach(el=>el.textContent="v"+RC_VER);
const RC_ESP0=[{id:"auditorio",n:"Auditório",sg:"Aud.",c:"#7c3aed",on:1},{id:"lab1",n:"Laboratório de Informática 1",sg:"LI1",c:"#0e7490",on:1},{id:"lab2",n:"Laboratório de Informática 2",sg:"LI2",c:"#c2410c",on:1}];
let RC=(()=>{let o=null;try{o=JSON.parse(localStorage.getItem("roomcheck")||"null")}catch(e){}
  if(!o||typeof o!=="object")o={};if(!Array.isArray(o.esp)||!o.esp.length)o.esp=RC_ESP0.map(x=>({...x}));
  o.cfg=Object.assign({abre:480,fecha:1140,sab:false},o.cfg||{});{const g=+(localStorage.getItem("episj_ger")||0);if(g&&!o.ger)o.ger=g}o.res=o.res&&typeof o.res==="object"?o.res:{};o.et=o.et||0;return o})();
const RCV={sem:"",esp:"",ed:null,vista:(()=>{try{return localStorage.getItem("rc_vista")||"sem"}catch(e){return"sem"}})(),ref:""};
// 0.9.14: tempos letivos (início e fim em minutos) — os do horário da escola; podem mudar-se em RoomCheck › Espaços
const RC_TEMPOS0=[[510,560],[570,620],[640,690],[700,750],[810,860],[870,920],[940,990]];
function rcTempos(){const T=(Array.isArray(RC.cfg.tempos)?RC.cfg.tempos:RC_TEMPOS0).filter(t=>Array.isArray(t)&&Number.isFinite(t[0])&&Number.isFinite(t[1])&&t[1]>t[0]).slice().sort((a,b)=>a[0]-b[0]);return T.length?T:RC_TEMPOS0}
const rcPad=n=>String(n).padStart(2,"0");
const rcIso=d=>d.getFullYear()+"-"+rcPad(d.getMonth()+1)+"-"+rcPad(d.getDate());
const rcData=s=>{const p=String(s||"").split("-");return new Date(+p[0],(+p[1]||1)-1,+p[2]||1)};
const rcMais=(s,n)=>{const d=rcData(s);d.setDate(d.getDate()+n);return rcIso(d)};
const rcSeg=s=>{const d=rcData(s);d.setDate(d.getDate()-(d.getDay()+6)%7);return rcIso(d)};
const rcHoje=()=>rcIso(new Date());
const rcHm=m=>rcPad(Math.floor(m/60))+":"+rcPad(m%60);
const rcHc=m=>Math.floor(m/60)+":"+rcPad(m%60);
const rcMin=t=>{const p=String(t||"").split(":");return p.length<2||p[0]===""?NaN:(+p[0])*60+(+p[1])};
const rcE=id=>RC.esp.find(e=>e.id===id)||{id,n:id,sg:id,c:"#64748b",on:0};
const rcDia=(s,o)=>rcData(s).toLocaleDateString("pt-PT",o||{weekday:"long",day:"numeric",month:"long"});
const rcAtivas=()=>Object.values(RC.res).filter(r=>r&&!r.x);
const rcChoque=(e,d,h0,h1,ignorar)=>rcAtivas().concat(rcAulas(d)).find(r=>r.e===e&&r.d===d&&r.h0<h1&&r.h1>h0&&r.id!==ignorar);
function rcGravar(nuvem){
  const lim=Date.now()-90*864e5;for(const k in RC.res){const r=RC.res[k];if(r&&r.x&&(r.u||0)<lim)delete RC.res[k]}
  if(LIMPAR)return;try{localStorage.setItem("roomcheck",JSON.stringify(RC))}catch(e){toast("Não foi possível guardar neste navegador")}
  if(nuvem!==false)rcNuvemAgendar()}
/* nuvem da EPISJ 360 */
let rcNuvH=null,rcNuvOk=0,rcNuvErr="";
function rcJuntar(a,b){if((a.ger||0)!==(b.ger||0))return (a.ger||0)>(b.ger||0)?a:b;const o={ger:a.ger||0,esp:a.esp,cfg:a.cfg,et:a.et||0,res:{...(a.res||{})}};
  if((b.et||0)>(o.et||0)){o.esp=b.esp;o.cfg=Object.assign({abre:480,fecha:1140,sab:false},b.cfg||{});o.et=b.et}
  for(const k in (b.res||{})){const r=b.res[k];if(!r)continue;const l=o.res[k];if(!l||(r.u||0)>(l.u||0))o.res[k]=r}return o}
function rcNuvemAgendar(){clearTimeout(rcNuvH);nuvFila("rcNuvH",()=>rcTrazer(true),1500)}
async function rcTrazer(enviar){try{if(!NUVOK()||nuvDesl()){rcNuvUI();return}
    let rem=null;const idx=(await (await nuvem("GET","")).json()).itens||{};if(idx.rc)rem=await nuvemGet("rc");
    const antes=JSON.stringify(RC);if(rem)RC=rcJuntar(RC,rem);
    const mudouAqui=JSON.stringify(RC)!==antes;if(mudouAqui)rcGravar(false);
    if(enviar||!rem||JSON.stringify(rcJuntar(rem,RC))!==JSON.stringify(rem))await nuvem("PUT","rc",await gz(RC),Date.now());
    rcNuvOk=Date.now();rcNuvErr="";if(mudouAqui&&curTab.startsWith("rc"))rcRender(curTab)}
  catch(e){if(e.kind!=="nokv")rcNuvErr=e.message||String(e)}rcNuvUI()}
function rcNuvUI(){const el=$("#rcNuv");if(!el)return;
  el.innerHTML=!NUVOK()?"":nuvDesl()?`<div class="msg info">Sem armazenamento na nuvem: as reservas ficam só neste navegador.</div>`:rcNuvErr?`<div class="msg bad">Não foi possível guardar na nuvem (${esc(rcNuvErr)}). Volta a tentar sozinho.</div>`:rcNuvOk?`<div class="msg ok">${ico("cloud")} Reservas guardadas na nuvem às ${new Date(rcNuvOk).toLocaleTimeString("pt-PT",{hour:"2-digit",minute:"2-digit"})}.</div>`:""}
/* atualiza com a vista aberta e à vista (para ver as reservas feitas noutro computador) */
setInterval(()=>{if(curTab&&curTab.startsWith("rc")&&document.visibilityState==="visible"&&$("#rcDw").hidden)rcTrazer(false)},60000);

function rcRender(t){t=t||curTab;if(!RCV.sem)RCV.sem=rcSeg(rcHoje());
  if(t==="rcMapa")rcMapa();if(t==="rcLista")rcLista();if(t==="rcEsp")rcEspacos();rcNuvUI()}

/* ---------- mapa da semana ---------- */
function rcMapa(){const hoje=rcHoje(),E=RC.esp.filter(e=>e.on);if(RCV.esp&&!E.some(e=>e.id===RCV.esp))RCV.esp="";
  const nada=!RCV.esp,esps=nada?E.slice(0,1).map(e=>({...e,id:"\u0000",c:"#9aa3b2"})):E.filter(e=>e.id===RCV.esp); // 0.9.22: sem sala escolhida não há vista "Todos" — o calendário fica a cinzento e vazio
  rcSemSala(nada);
  document.querySelectorAll("[data-rcvis]").forEach(b=>{b.classList.toggle("on",b.dataset.rcvis===RCV.vista);b.setAttribute("aria-selected",b.dataset.rcvis===RCV.vista)});
  if(RCV.vista==="mes"||RCV.vista==="ano")return rcMesAno(E,esps);
  const n=RC.cfg.sab?6:5,dias=[...Array(n)].map((_,i)=>rcMais(RCV.sem,i));const A=rcAtivas();
  if(!RC.cfg.sab&&A.some(r=>r.d===rcMais(RCV.sem,5)))dias.push(rcMais(RCV.sem,5));
  const AM=A.concat(dias.flatMap(d=>rcAulas(d))); // 0.9.47: com as aulas do Horários360
  const T=rcTempos();let H0=T[0][0],H1=T[T.length-1][1];AM.forEach(r=>{if(dias.includes(r.d)&&esps.some(e=>e.id===r.e)){H0=Math.min(H0,Math.floor(r.h0/30)*30);H1=Math.max(H1,Math.ceil(r.h1/30)*30)}});
  const PX=rcPx(H1-H0,46),alt=(H1-H0)*PX,estreito=esps.length>1,fim=rcMais(RCV.sem,dias.length-1);
  $("#rcEsps").innerHTML=E.map(e=>`<button class="rc-chip${RCV.esp===e.id?" on":""}" data-rcesp="${esc(e.id)}" style="--c:${esc(e.c)}"><i></i>${esc(e.n)}</button>`).join("");
  $("#rcSem").textContent=rcData(RCV.sem).toLocaleDateString("pt-PT",{day:"numeric",month:"short"})+" – "+rcData(fim).toLocaleDateString("pt-PT",{day:"numeric",month:"short",year:"numeric"});
  const horas=[];for(let m=Math.ceil(H0/60)*60;m<=H1;m+=60)if(m<T[0][0]-15||m>T[T.length-1][1]+15)horas.push(m); // horas só fora dos tempos letivos
  const gaps=T.slice(1).map((t,i)=>[T[i][1],t[0]]).filter(g=>g[1]>g[0]);
  const bloco=(r,e)=>{const top=(r.h0-H0)*PX,h=Math.max(18,(r.h1-r.h0)*PX-2),curto=h<40,medio=h<62;
    const hh=estreito?`<b>${rcHc(r.h0)}</b>${medio?"":`<b>–${rcHc(r.h1)}</b>`}`:`<b>${rcHm(r.h0)}–${rcHm(r.h1)}</b>`;
    if(r.aula)return `<div class="rc-bl rc-aula${curto?" curto":""}" data-rcaula="${esc(r.id)}" style="--c:${esc(e.c)};top:${top}px;height:${h}px" title="${esc(e.n+" · "+rcHm(r.h0)+"–"+rcHm(r.h1)+" · "+r.p+(r.t?" · "+r.t:"")+(r.m?" · "+r.m:"")+" (Horários360)")}"><span class="rc-hh">${hh}</span><span>${esc(r.p)}</span>${curto?"":r.t?`<span class="rc-mut">${esc(r.t)}</span>`:""}</div>`;
    return `<button class="rc-bl${curto?" curto":""}" data-rcr="${esc(r.id)}" style="--c:${esc(e.c)};top:${top}px;height:${h}px" title="${esc(e.n+" · "+rcHm(r.h0)+"–"+rcHm(r.h1)+" · "+r.p+(r.t?" · "+r.t:"")+(r.m?" · "+r.m:""))}"><span class="rc-hh">${hh}</span><span>${esc(r.p)}</span>${curto?"":r.t?`<span class="rc-mut">${esc(r.t)}</span>`:""}</button>`};
  const linhas=horas.map(m=>`<i style="top:${(m-H0)*PX}px"></i>`).join("")+T.map(t=>`<i class="t" style="top:${(t[0]-H0)*PX}px"></i><i class="t" style="top:${(t[1]-H0)*PX}px"></i>`).join("")
    +gaps.map(g=>`<b class="rc-int${g[1]-g[0]>=45?" alm":""}" style="top:${(g[0]-H0)*PX}px;height:${(g[1]-g[0])*PX}px"></b>`).join("");
  $("#rcGrid").innerHTML=`<div class="rc-grid${estreito?" rc-3":""}" style="--nd:${dias.length}"><div class="rc-cab"></div>
    ${dias.map(d=>`<div class="rc-cab${d===hoje?" hoje":""}"><b>${esc(rcData(d).toLocaleDateString("pt-PT",{weekday:"short"}).replace(".",""))}</b> <span>${rcData(d).getDate()}</span>${estreito?`<div class="rc-sub" style="grid-template-columns:repeat(${esps.length},1fr)">${esps.map(e=>`<span style="--c:${esc(e.c)}" title="${esc(e.n)}">${esc(e.sg)}</span>`).join("")}</div>`:""}</div>`).join("")}
    <div class="rc-horas" style="height:${alt}px">${horas.map(m=>`<span style="top:${(m-H0)*PX}px">${rcHm(m)}</span>`).join("")}${T.map(t=>`<div class="rc-tp" style="top:${(t[0]-H0)*PX}px;height:${(t[1]-t[0])*PX}px"><b>${rcHm(t[0])}</b><em>${rcHm(t[1])}</em></div>`).join("")}${gaps.filter(g=>g[1]-g[0]>=45).map(g=>`<div class="rc-alm" style="top:${(g[0]-H0)*PX}px;height:${(g[1]-g[0])*PX}px">Almoço</div>`).join("")}</div>
    ${dias.map(d=>`<div class="rc-dia${d===hoje?" hoje":""}${d<hoje?" pas":""}"><div class="rc-lanes" style="height:${alt}px">${linhas}${esps.map(e=>`<div class="rc-lane" data-rcd="${d}" data-rce="${esc(e.id)}" style="--c:${esc(e.c)}">${AM.filter(r=>r.d===d&&r.e===e.id).map(r=>bloco(r,e)).join("")}</div>`).join("")}</div></div>`).join("")}</div>`;
  const prox=A.filter(r=>r.d>=hoje).sort((a,b)=>a.d.localeCompare(b.d)||a.h0-b.h0).slice(0,10);
  $("#rcProx").innerHTML=prox.length?`<div class="rc-lista">${prox.map(r=>{const e=rcE(r.e);return `<div class="rc-it" style="--c:${esc(e.c)}"><i></i><div><b>${esc(e.n)}</b> · ${esc(rcDia(r.d))} · ${rcHm(r.h0)}–${rcHm(r.h1)}<br><span class="rc-mut">${esc(r.p)}${r.t?" · "+esc(r.t):""}${r.m?" · "+esc(r.m):""}${r.s?" · todas as semanas":""}</span></div><button class="b s" data-rcv="${esc(r.id)}">Ver</button></div>`}).join("")}</div>`:`<p class="hint" style="margin:0">Ainda não há reservas marcadas.</p>`;
  document.querySelectorAll("[data-rcesp]").forEach(b=>b.onclick=()=>{RCV.esp=b.dataset.rcesp;rcMapa()});
  document.querySelectorAll("#rcGrid .rc-lane").forEach(l=>l.onclick=ev=>{if(!RCV.esp||ev.target.closest(".rc-bl"))return;const d=l.dataset.rcd;if(d<hoje){toast("Não dá para reservar em dias que já passaram");return}
    const m=H0+(ev.clientY-l.getBoundingClientRect().top)/PX,tp=T.find(t=>m>=t[0]&&m<t[1]),ag=(()=>{const n=new Date();return n.getHours()*60+n.getMinutes()})();
    if(tp){if(d===hoje&&tp[1]<=ag){toast("Esse tempo já passou");return}rcNova({e:l.dataset.rce,d,h0:tp[0],h1:tp[1]});return} // clique num tempo: reserva esse tempo
    let h0=H0+Math.floor((m-H0)/30)*30;if(d===hoje&&h0+30<=ag)h0=Math.ceil(ag/15)*15;
    rcNova({e:l.dataset.rce,d,h0,h1:Math.min(1439,h0+90)})});
  document.querySelectorAll("#rcMapa [data-rcr],#rcMapa [data-rcv]").forEach(b=>b.onclick=()=>{if(rcArrastou){rcArrastou=false;return}rcVer(RC.res[b.dataset.rcr||b.dataset.rcv])});
  document.querySelectorAll("#rcGrid .rc-bl[data-rcr]").forEach(b=>b.addEventListener("pointerdown",ev=>rcArrastar(ev,b,{H0,PX,T,hoje})));
  document.querySelectorAll("#rcGrid [data-rcaula]").forEach(b=>b.onclick=ev=>{ev.stopPropagation();toast(b.title)});
  const sc=$("#rcGrid").closest(".rc-scroll"),dh=$("#rcGrid .rc-dia.hoje");if(sc&&dh&&sc.scrollWidth>sc.clientWidth+4&&sc.dataset.sem!==RCV.sem){sc.dataset.sem=RCV.sem;sc.scrollLeft=Math.max(0,dh.offsetLeft-(window.innerWidth<700?40:52))}}
/* RoomCheck 1.2: arrastar uma reserva para outra hora, dia ou espaço; nas que se repetem, pergunta se é só este dia ou todas */
let rcArrastou=false;
/* RoomCheck 1.3: o mapa ocupa a altura que o ecrã tem livre (e volta a desenhar-se quando a janela muda de tamanho) */
function rcLivre(cab){const g=$("#rcGrid");if(!g||!g.offsetParent)return 0;const top=g.getBoundingClientRect().top+window.scrollY;
  const f=$("#fundos"),fh=f&&!f.hidden&&getComputedStyle(f).display!=="none"&&getComputedStyle(f).position==="fixed"?f.getBoundingClientRect().height:0; // 0.9.20: a barra dos logótipos fixa em baixo tapa o fim do mapa
  return Math.max(0,window.innerHeight-top-cab-28-fh)} // 28 = margem do cartão por baixo
function rcPx(min,cab){const h=rcLivre(cab),pq=window.innerWidth<700;if(!h)return 1.15;return Math.max(pq?.85:.9,Math.min(2.6,h/min))}
let rcRsz=0,rcLarg=window.innerWidth;
{const fb=$("#fundos");if(fb&&window.MutationObserver)new MutationObserver(()=>{if(curTab==="rcMapa"){clearTimeout(rcRsz);rcRsz=setTimeout(rcMapa,60)}}).observe(fb,{attributes:true,attributeFilter:["hidden"]})}
window.addEventListener("resize",()=>{clearTimeout(rcRsz);rcRsz=setTimeout(()=>{if(curTab==="rcMapa"&&!document.querySelector(".rc-bl.arr")){rcMapa()}rcLarg=window.innerWidth},150)});
function rcArrastar(ev,el,o){if(ev.button!==0)return;const r=RC.res[el.dataset.rcr];if(!r||r.d<o.hoje)return;
  const dur=r.h1-r.h0,y0=ev.clientY,x0=ev.clientX,lane0=el.parentNode,top0=parseFloat(el.style.top),dy=y0-el.getBoundingClientRect().top;
  let ativo=false,alvo=null,dica=null;
  const calc=(cx,cy)=>{el.style.pointerEvents="none";const ln=document.elementFromPoint(cx,cy)?.closest?.(".rc-lane");el.style.pointerEvents="";if(!ln)return null;
    let h0=o.H0+(cy-dy-ln.getBoundingClientRect().top)/o.PX;const tp=o.T.find(t=>h0+10>=t[0]&&h0+10<t[1]); // perto do início de um tempo: encaixa nele
    h0=tp&&Math.abs(h0-tp[0])<=20?tp[0]:Math.round(h0/5)*5;h0=Math.max(0,Math.min(1440-dur,h0));
    const d=ln.dataset.rcd,e=ln.dataset.rce;return{ln,d,e,h0,h1:h0+dur,mau:d<o.hoje?"dia que já passou":(rcChoque(e,d,h0,h0+dur,r.id)?"ocupado":"")}};
  const mover=m=>{if(!ativo){if(Math.hypot(m.clientX-x0,m.clientY-y0)<5)return;ativo=true;el.classList.add("arr");el.setPointerCapture(ev.pointerId);dica=document.createElement("div");dica.className="rc-arrh";document.body.appendChild(dica)}
    m.preventDefault();const a=calc(m.clientX,m.clientY);if(!a)return;alvo=a;if(a.ln!==el.parentNode)a.ln.appendChild(el);
    el.style.top=(a.h0-o.H0)*o.PX+"px";el.classList.toggle("mau",!!a.mau);
    dica.textContent=`${rcE(a.e).sg} · ${rcData(a.d).toLocaleDateString("pt-PT",{weekday:"short",day:"numeric"})} · ${rcHm(a.h0)}–${rcHm(a.h1)}${a.mau?" — "+a.mau:""}`;dica.style.left=m.clientX+14+"px";dica.style.top=m.clientY+14+"px"};
  const largar=()=>{el.removeEventListener("pointermove",mover);el.removeEventListener("pointerup",largar);el.removeEventListener("pointercancel",largar);if(dica)dica.remove();
    if(!ativo)return;rcArrastou=true;setTimeout(()=>rcArrastou=false,50);
    const voltar=()=>{lane0.appendChild(el);el.style.top=top0+"px";el.classList.remove("arr","mau")};
    if(!alvo||(alvo.d===r.d&&alvo.e===r.e&&alvo.h0===r.h0)){voltar();return}
    if(alvo.mau){voltar();toast(alvo.mau==="ocupado"?"Esse espaço está ocupado nesse horário":"Não dá para mudar para um dia que já passou");return}
    rcMover(r,alvo,voltar)};
  el.addEventListener("pointermove",mover);el.addEventListener("pointerup",largar);el.addEventListener("pointercancel",largar)}
function rcMover(r,a,voltar){const hoje=rcHoje(),serie=r.s?rcAtivas().filter(x=>x.s===r.s&&x.d>=r.d&&x.d>=hoje).sort((x,y)=>x.d.localeCompare(y.d)):[];
  const desc=`${rcE(a.e).n} · ${rcDia(a.d)} · ${rcHm(a.h0)}–${rcHm(a.h1)}`;
  const aplicar=todas=>{const dd=Math.round((rcData(a.d)-rcData(r.d))/864e5),u=Date.now(),L=todas?serie:[r],ok=[],oc=[];
    for(const x of L){const d=rcMais(x.d,dd),c=rcChoque(a.e,d,a.h0,a.h1,x.id);if(c||d<hoje){oc.push({d,c});continue}
      RC.res[x.id]={...x,e:a.e,d,h0:a.h0,h1:a.h1,s:todas?x.s:"",u};ok.push(d)} // só este dia: sai da série
    rcGravar();rcFechar();rcRender(curTab);
    if(!oc.length)toast(ok.length>1?ok.length+" reservas mudadas":"Reserva mudada · "+desc);
    else toast(`${ok.length} mudada(s); ficaram como estavam ${oc.length} (ocupado: ${oc.map(o=>rcDia(o.d,{day:"numeric",month:"short"})).join(", ")})`)};
  if(serie.length<2){aplicar(false);return}
  rcAbrir("Mudar reserva",`<div class="rc-ver" style="--c:${esc(rcE(a.e).c)}"><b>${esc(r.p)}</b><span>${esc(desc)}</span></div>
    <p class="hint">Esta reserva repete-se todas as semanas (${serie.length} de hoje em diante). O que quer mudar?</p>
    <div class="rc-mv"><button class="b" id="rcMv1">Só este dia<small>${esc(rcDia(r.d,{weekday:"long",day:"numeric",month:"long"}))} — as outras semanas ficam como estão</small></button>
    <button class="b s" id="rcMvT">Todas as semanas, deste dia em diante<small>${serie.length} reservas passam para ${esc(rcData(a.d).toLocaleDateString("pt-PT",{weekday:"long"}))}, ${rcHm(a.h0)}–${rcHm(a.h1)}${a.e!==r.e?", "+esc(rcE(a.e).n):""}</small></button>
    <button class="b s" id="rcMvX">Cancelar</button></div>`);
  voltar(); // até escolher, a reserva fica onde estava (fechar o painel de qualquer forma é cancelar)
  $("#rcMv1").onclick=()=>aplicar(false);$("#rcMvT").onclick=()=>aplicar(true);$("#rcMvX").onclick=rcFechar}
document.querySelectorAll("[data-rcnav]").forEach(b=>b.onclick=()=>{const n=+b.dataset.rcnav,v=RCV.vista;
  if(!n){RCV.sem=rcSeg(rcHoje());RCV.ref=rcHoje()}
  else if(v==="sem")RCV.sem=rcMais(RCV.sem||rcSeg(rcHoje()),7*n);
  else{const r=rcData(RCV.ref||rcHoje());RCV.ref=rcIso(v==="mes"?new Date(r.getFullYear(),r.getMonth()+n,1):new Date(r.getFullYear()+n,0,1))}
  rcMapa()});
document.querySelectorAll("[data-rcvis]").forEach(b=>b.onclick=()=>{const v=b.dataset.rcvis;if(v===RCV.vista)return;
  if(v!=="sem")RCV.ref=RCV.vista==="sem"?rcMais(RCV.sem||rcSeg(rcHoje()),3):(RCV.ref||rcHoje()); // mês/ano: o da semana que se estava a ver
  else{const r=RCV.ref||rcHoje(),h=rcHoje();RCV.sem=rcSeg(r.slice(0,7)===h.slice(0,7)||(RCV.vista==="ano"&&r.slice(0,4)===h.slice(0,4))?h:r)}
  RCV.vista=v;try{localStorage.setItem("rc_vista",v)}catch(e){}rcMapa()});
const rcIrSemana=d=>{RCV.sem=rcSeg(d);RCV.vista="sem";try{localStorage.setItem("rc_vista","sem")}catch(e){}rcMapa()};
function rcSemSala(nada){const sc=$("#rcGrid")&&$("#rcGrid").closest(".rc-scroll");if(!sc)return;sc.classList.toggle("rc-off",nada);
  let av=sc.querySelector(".rc-aviso");if(nada&&!av){av=document.createElement("div");av.className="rc-aviso";av.innerHTML=`<div><b>Por favor, selecione uma sala</b><span>Escolha acima o Auditório ou um dos Laboratórios para ver o calendário e reservar.</span></div>`;sc.appendChild(av)}
  if(av){av.hidden=!nada; // 0.9.86: no telemóvel a grelha desliza para o lado — o aviso acompanha a parte à vista
    const pos=()=>{av.style.left=sc.scrollLeft+"px";av.style.width=sc.clientWidth+"px";av.style.right="auto"};pos();if(!sc.dataset.avs){sc.dataset.avs=1;sc.addEventListener("scroll",()=>{const a=sc.querySelector(".rc-aviso");if(a&&!a.hidden){a.style.left=sc.scrollLeft+"px"}},{passive:true})}}}
/* ---------- RoomCheck 1.1: mapa do mês e do ano ---------- */
function rcMesAno(E,esps){const hoje=rcHoje(),A=rcAtivas(),ids=new Set(esps.map(e=>e.id)),R=A.filter(r=>ids.has(r.e)),ref=rcData(RCV.ref||(RCV.ref=rcHoje())),y=ref.getFullYear(),T=rcTempos();
  const porDia=new Map();R.forEach(r=>(porDia.get(r.d)||porDia.set(r.d,[]).get(r.d)).push(r));porDia.forEach(L=>L.sort((a,b)=>a.h0-b.h0||String(a.e).localeCompare(String(b.e))));
  $("#rcEsps").innerHTML=E.map(e=>`<button class="rc-chip${RCV.esp===e.id?" on":""}" data-rcesp="${esc(e.id)}" style="--c:${esc(e.c)}"><i></i>${esc(e.n)}</button>`).join("");
  const comSab=d0=>RC.cfg.sab||R.some(r=>r.d.slice(0,d0.length)===d0&&rcData(r.d).getDay()===6),nomeDia=["Seg","Ter","Qua","Qui","Sex","Sáb"];
  const um=esps.length===1,cor=um?esps[0].c:"var(--brand)";
  if(RCV.vista==="mes"){const m=ref.getMonth(),pre=rcIso(new Date(y,m,1)).slice(0,7),nd=comSab(pre)?6:5,ini=rcSeg(rcIso(new Date(y,m,1))),fimM=rcIso(new Date(y,m+1,0));
    $("#rcSem").textContent=new Date(y,m,1).toLocaleDateString("pt-PT",{month:"long",year:"numeric"});
    let h=`<div class="rc-mes" style="--nd:${nd}">${nomeDia.slice(0,nd).map(n=>`<div class="rc-cab"><b>${n}</b></div>`).join("")}`;
    for(let w=ini;w<=fimM;w=rcMais(w,7))for(let i=0;i<nd;i++){const d=rcMais(w,i),L=porDia.get(d)||[],max=L.length>4?3:4;
      h+=`<div class="rc-md${d.slice(0,7)!==pre?" fora":""}${d===hoje?" hoje":""}${d<hoje?" pas":""}" data-rcmd="${d}"><button class="rc-mdn" data-rcir="${d}" title="Ver a semana">${rcData(d).getDate()}</button>
        ${L.slice(0,max).map(r=>{const e=rcE(r.e);return `<button class="rc-mc" data-rcr="${esc(r.id)}" style="--c:${esc(e.c)}" title="${esc(e.n+" · "+rcHm(r.h0)+"–"+rcHm(r.h1)+" · "+r.p+(r.t?" · "+r.t:""))}"><b>${rcHm(r.h0)}</b><span>${um?"":esc(e.sg)+" · "}${esc(r.p)}</span></button>`}).join("")}
        ${L.length>max?`<button class="rc-mais" data-rcir="${d}">+${L.length-max} mais</button>`:""}</div>`}
    $("#rcGrid").innerHTML=h+`</div>`;
    const sem=Math.round((rcData(fimM)-rcData(ini))/864e5/7)+1,lv=rcLivre(30),mn=window.innerWidth<700?64:104;
    const rh=Math.floor((lv-30-sem*6)/sem);if(rh>mn){const g=$("#rcGrid .rc-mes");g.classList.add("fit");g.style.gridTemplateRows=`auto repeat(${sem},${rh}px)`}}
  else{const a0=ref.getMonth()>=8?y:y-1;$("#rcSem").textContent="Ano letivo "+a0+"/"+(a0+1);const tot=T.reduce((s,t)=>s+t[1]-t[0],0)*esps.length||1;
    let h=`<div class="rc-ano" style="--c:${esc(cor)}">`;
    for(let k=0;k<12;k++){const ym=new Date(a0,8+k,1),yy=ym.getFullYear(),m=ym.getMonth(),pre=rcIso(ym).slice(0,7),nd=comSab(pre)?6:5,ini=rcSeg(pre+"-01"),fimM=rcIso(new Date(yy,m+1,0));
      const nRes=R.filter(r=>r.d.slice(0,7)===pre).length;
      h+=`<div class="rc-am"><h4><button data-rcmes="${pre}-01">${ym.toLocaleDateString("pt-PT",{month:"long"})}${m===0?" "+yy:""}</button><span>${nRes?nRes+(nRes>1?" reservas":" reserva"):""}</span></h4><div class="rc-amg" style="--nd:${nd}">${nomeDia.slice(0,nd).map(n=>`<i>${n[0]}</i>`).join("")}`;
      for(let w=ini;w<=fimM;w=rcMais(w,7))for(let i=0;i<nd;i++){const d=rcMais(w,i);if(d.slice(0,7)!==pre){h+=`<span></span>`;continue}
        const L=porDia.get(d)||[];let oc=0;L.forEach(r=>T.forEach(t=>{oc+=Math.max(0,Math.min(r.h1,t[1])-Math.max(r.h0,t[0]))}));
        const f=oc/tot,lv=!L.length?0:f<.15?1:f<.4?2:f<.7?3:4;
        h+=`<button class="${lv?"l"+lv:""}${d<hoje?" pas":""}${d===hoje?" hoje":""}" data-rcir="${d}" title="${esc(rcDia(d,{weekday:"long",day:"numeric",month:"long"}))}${L.length?" · "+L.length+(L.length>1?" reservas":" reserva")+" · "+Math.round(f*100)+"% dos tempos ocupados":" · livre"}">${rcData(d).getDate()}</button>`}
      h+=`</div></div>`}
    $("#rcGrid").innerHTML=h+`</div><div class="rc-leg" style="--c:${esc(cor)}">Ocupação dos tempos letivos${um?"":" (todos os espaços)"}: <b></b> livre <b style="background:color-mix(in srgb,var(--c) 22%,#fff)"></b><b style="background:color-mix(in srgb,var(--c) 42%,#fff)"></b><b style="background:color-mix(in srgb,var(--c) 66%,#fff)"></b><b style="background:var(--c)"></b> cheio · clique num dia para ver a semana</div>`}
  const prox=A.filter(r=>r.d>=hoje).sort((a,b)=>a.d.localeCompare(b.d)||a.h0-b.h0).slice(0,10);
  $("#rcProx").innerHTML=prox.length?`<div class="rc-lista">${prox.map(r=>{const e=rcE(r.e);return `<div class="rc-it" style="--c:${esc(e.c)}"><i></i><div><b>${esc(e.n)}</b> · ${esc(rcDia(r.d))} · ${rcHm(r.h0)}–${rcHm(r.h1)}<br><span class="rc-mut">${esc(r.p)}${r.t?" · "+esc(r.t):""}${r.m?" · "+esc(r.m):""}${r.s?" · todas as semanas":""}</span></div><button class="b s" data-rcv="${esc(r.id)}">Ver</button></div>`}).join("")}</div>`:`<p class="hint" style="margin:0">Ainda não há reservas marcadas.</p>`;
  document.querySelectorAll("[data-rcesp]").forEach(b=>b.onclick=()=>{RCV.esp=b.dataset.rcesp;rcMapa()});
  document.querySelectorAll("#rcGrid [data-rcir]").forEach(b=>b.onclick=ev=>{ev.stopPropagation();rcIrSemana(b.dataset.rcir)});
  document.querySelectorAll("#rcGrid [data-rcmes]").forEach(b=>b.onclick=()=>{RCV.ref=b.dataset.rcmes;RCV.vista="mes";try{localStorage.setItem("rc_vista","mes")}catch(e){}rcMapa()});
  document.querySelectorAll("#rcGrid [data-rcmd]").forEach(c=>c.onclick=ev=>{if(ev.target.closest("button"))return;const d=c.dataset.rcmd;if(d<hoje){toast("Não dá para reservar em dias que já passaram");return}rcNova({e:RCV.esp!=="todos"?RCV.esp:undefined,d,h0:T[0][0],h1:T[0][1]})});
  document.querySelectorAll("#rcMapa [data-rcr],#rcMapa [data-rcv]").forEach(b=>b.onclick=ev=>{ev.stopPropagation();rcVer(RC.res[b.dataset.rcr||b.dataset.rcv])})}
$("#rcNova").onclick=()=>rcNova({});

/* ---------- painel lateral ---------- */
function rcAbrir(t,html){$("#rcDwT").textContent=t;$("#rcDwC").innerHTML=html;$("#rcDw").hidden=false;setTimeout(()=>{const f=$("#rcDwC input,#rcDwC button");if(f)f.focus()},30)}
function rcFechar(){$("#rcDw").hidden=true}
$("#rcDwX").onclick=rcFechar;$("#rcDw").addEventListener("mousedown",e=>{if(e.target.id==="rcDw")rcFechar()});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!$("#rcDw").hidden)rcFechar()});

/* 0.9.33: na reserva, "Reservado por" e "Turma" vêm dos dados da escola (formadores e turmas do ano letivo ativo);
   se o formador escolhido dá Tecnologias da Informação e Comunicação, o motivo fica "Tecnologias de Informação e Comunicação" */
const RC_TIC="Tecnologias de Informação e Comunicação";
function rcProfPorNome(n){n=String(n||"").trim().toLowerCase();return n?(cfg.profs||[]).find(p=>String(p.nome||"").trim().toLowerCase()===n)||null:null}
function rcEhTIC(prof){if(!prof)return false;const re=/tecnologias\s+d[ae]\s+informa|(^|\D)1400(\D|$)|\bTIC\b/i;
  try{const a=anoAtivo().id;if(pcPlanos().some(p=>p.anoId===a&&(p.linhas||[]).some(l=>l.f===prof.id&&re.test(l.disc||""))))return true}catch(e){}
  return re.test([prof.grupo,prof.area,prof.disc,prof.disciplina].filter(Boolean).join(" "))}
function rcTurmaTxt(t){try{return dsdTurmaTxt(t)}catch(e){return t.cod+(t.nome?" — "+t.nome:"")}}
function rcCamposHTML(sf,v){v=v||{};const P=(cfg.profs||[]).filter(p=>p.nome).slice().sort(cmpProf);
  let T=[];try{T=turmasDoAno().map(rcTurmaTxt)}catch(e){}
  const pIn=!v.p||P.some(p=>p.nome===v.p),tIn=!v.t||T.includes(v.t);
  return `<label>Reservado por<select id="rcPs${sf}"><option value="">— escolha o formador —</option>${P.map(p=>`<option value="${esc(p.nome)}"${p.nome===v.p?" selected":""}>${esc(p.cod?p.cod+" - "+p.nome:p.nome)}</option>`).join("")}<option value="__o"${pIn?"":" selected"}>Outro (serviço ou pessoa de fora)…</option></select></label>
    <input type="text" id="rcP${sf}" value="${esc(v.p||"")}" maxlength="80" placeholder="Nome do serviço ou da pessoa" ${pIn?"hidden":""}>
    <label><span>Turma <span class="rc-mut">(opcional)</span></span><select id="rcTs${sf}"><option value="">— sem turma —</option>${T.map(t=>`<option value="${esc(t)}"${t===v.t?" selected":""}>${esc(t)}</option>`).join("")}${tIn?"":`<option value="${esc(v.t)}" selected>${esc(v.t)}</option>`}</select></label>
    <input type="hidden" id="rcT${sf}" value="${esc(v.t||"")}">
    <label><span>Motivo <span class="rc-mut">(opcional)</span></span><input type="text" id="rcM${sf}" value="${esc(v.m||"")}" maxlength="200" placeholder="Ex.: aula prática, teste, reunião"></label>`}
function rcCamposLigar(sf){const ps=$("#rcPs"+sf),pi=$("#rcP"+sf),ts=$("#rcTs"+sf),ti=$("#rcT"+sf),mi=$("#rcM"+sf);let auto=mi.value===RC_TIC?RC_TIC:"";
  const motivo=()=>{const tic=rcEhTIC(rcProfPorNome(pi.value));if(tic&&(!mi.value.trim()||mi.value===auto)){mi.value=RC_TIC;auto=RC_TIC}else if(!tic&&auto&&mi.value===auto){mi.value="";auto=""}};
  ps.onchange=()=>{if(ps.value==="__o"){pi.hidden=false;if(rcProfPorNome(pi.value))pi.value="";pi.focus()}else{pi.hidden=true;pi.value=ps.value}motivo()};
  pi.oninput=motivo;ts.onchange=()=>{ti.value=ts.value};motivo()}
/* ---------- nova reserva ---------- */
function rcNova(o){const hoje=rcHoje(),E=RC.esp.filter(e=>e.on);const e=(o.e&&o.e!=="\u0000"?o.e:"")||RCV.esp||(E[0]||{}).id;
  const d=o.d&&o.d>=hoje?o.d:((RCV.sem||hoje)>hoje?RCV.sem:hoje);const h0=Number.isFinite(o.h0)?o.h0:600,h1=Number.isFinite(o.h1)?o.h1:Math.min(1439,h0+90);
  const profs=(cfg.profs||[]).map(p=>p.nome).filter(Boolean),turmas=(()=>{let L=[];try{L=turmasDoAno().map(t=>t.cod+(t.nome?" — "+t.nome:""))}catch(_){}if(!L.length)L=[...new Set((cfg.mods||[]).map(m=>m.turma).filter(Boolean))].sort((a,b)=>COLL_PT.compare(a,b));return L})();
  const temMail=!!(msCfg()&&msCfg().clientId);
  rcAbrir("Nova reserva",`<div class="rc-f">
    <span class="rc-l">Espaço</span><div class="rc-ops">${E.map(x=>`<label class="rc-op" style="--c:${esc(x.c)}"><input type="radio" name="rcE" value="${esc(x.id)}" ${x.id===e?"checked":""}><i></i>${esc(x.n)}</label>`).join("")}</div>
    <div class="rc-3c"><label>Dia<input type="date" id="rcD" value="${d}" min="${hoje}"></label><label>Das<input type="time" id="rcH0" value="${rcHm(h0)}" step="300"></label><label>Às<input type="time" id="rcH1" value="${rcHm(h1)}" step="300"></label></div>
    <div class="rc-tps"><span class="rc-mut">Tempos:</span>${rcTempos().map((t,i)=>`<button class="b s" data-rctp="${i}" title="${rcHm(t[0])}–${rcHm(t[1])}">${rcHm(t[0])}</button>`).join("")}</div>
    <div class="rc-dur"><span class="rc-mut">Duração:</span>${[45,50,90,100,180].map(m=>`<button class="b s" data-rcdur="${m}">${Math.floor(m/60)}h${rcPad(m%60)}</button>`).join("")}</div>
    <div id="rcLivre" class="rc-livre" aria-live="polite"></div>
    ${rcCamposHTML("",{p:(()=>{try{const me=dsdEu();return me?me.nome:""}catch(e){return""}})()})}
    <label class="rc-chk"><input type="checkbox" id="rcRep"> Repetir todas as semanas, no mesmo dia e hora</label>
    <div id="rcRepW" hidden><label>Até<input type="date" id="rcAte" min="${rcMais(d,7)}" value="${rcMais(d,56)}"></label><p class="hint" style="margin:4px 0 0">No máximo 60 semanas. Os dias já ocupados ficam de fora e a EPISJ 360 diz quais.</p></div>
    ${temMail?`<label class="rc-chk"><input type="checkbox" id="rcMail"> Enviar confirmação por email ao formador (Office 365)</label>`:""}
    <div class="row" style="margin-top:6px"><button class="b" id="rcOk">Reservar</button><button class="b s" id="rcX">Cancelar</button></div>
    <div id="rcRes"></div></div>`);
  const val=()=>({e:(document.querySelector('input[name="rcE"]:checked')||{}).value,d:$("#rcD").value,h0:rcMin($("#rcH0").value),h1:rcMin($("#rcH1").value)});
  const livre=()=>{const x=val(),el=$("#rcLivre");if(!x.d||!Number.isFinite(x.h0)||!Number.isFinite(x.h1)){el.className="rc-livre";el.textContent="";return}
    if(x.h1<=x.h0){el.className="rc-livre mau";el.textContent="A hora de fim tem de ser depois da hora de início.";return}
    const c=rcChoque(x.e,x.d,x.h0,x.h1);el.className="rc-livre "+(c?"mau":"bom");el.textContent=c?`Ocupado: ${c.p} das ${rcHm(c.h0)} às ${rcHm(c.h1)}.`:`✓ ${rcE(x.e).n} livre nesse horário.`};
  const TT=rcTempos(),tpUI=()=>{const a=rcMin($("#rcH0").value),b=rcMin($("#rcH1").value);document.querySelectorAll("[data-rctp]").forEach(x=>{const t=TT[+x.dataset.rctp];x.classList.toggle("on",t[0]>=a&&t[1]<=b)})};
  document.querySelectorAll("[data-rctp]").forEach(x=>x.onclick=()=>{const i=+x.dataset.rctp,j=TT.findIndex(t=>t[0]===rcMin($("#rcH0").value));
    if(j>=0&&i>j&&TT[i][1]>rcMin($("#rcH1").value))$("#rcH1").value=rcHm(TT[i][1]); // outro tempo a seguir: junta até lá
    else{$("#rcH0").value=rcHm(TT[i][0]);$("#rcH1").value=rcHm(TT[i][1])}livre();tpUI()});
  document.querySelectorAll("#rcDwC input").forEach(i=>i.addEventListener("input",()=>{livre();tpUI()}));document.querySelectorAll('#rcDwC input[type=radio]').forEach(i=>i.addEventListener("change",livre));livre();tpUI();
  document.querySelectorAll("[data-rcdur]").forEach(b=>b.onclick=()=>{const h=rcMin($("#rcH0").value);if(Number.isFinite(h)){$("#rcH1").value=rcHm(Math.min(1439,h+ +b.dataset.rcdur));livre();tpUI()}});
  $("#rcRep").onchange=ev=>{$("#rcRepW").hidden=!ev.target.checked};
  $("#rcD").addEventListener("change",()=>{const v=$("#rcD").value;if(v){$("#rcAte").min=rcMais(v,7);if($("#rcAte").value<=v)$("#rcAte").value=rcMais(v,56)}});
  $("#rcX").onclick=rcFechar;rcCamposLigar("");
  $("#rcOk").onclick=async()=>{const x=val(),p=$("#rcP").value.trim();
    if(!x.e)return toast("Escolha o espaço");if(!x.d||x.d<hoje)return toast("Escolha um dia a partir de hoje");
    if(!Number.isFinite(x.h0)||!Number.isFinite(x.h1)||x.h1<=x.h0)return toast("Verifique as horas");if(!p)return toast("Indique quem reserva");
    const dias=[x.d];if($("#rcRep").checked){const ate=$("#rcAte").value;if(!ate||ate<=x.d)return toast("Escolha até quando se repete");let k=rcMais(x.d,7);while(k<=ate&&dias.length<60){dias.push(k);k=rcMais(k,7)}}
    const b=$("#rcOk");b.disabled=true;await rcTrazer(false); /* traz primeiro o que foi reservado noutros computadores */
    const s=dias.length>1?uid()+uid():"",ok=[],oc=[],u=Date.now(),pf=(cfg.profs||[]).find(q=>q.nome===p);
    for(const d of dias){const c=rcChoque(x.e,d,x.h0,x.h1);if(c){oc.push({d,c});continue}
      const id=uid()+uid();RC.res[id]={id,e:x.e,d,h0:x.h0,h1:x.h1,p,pid:pf?pf.id:"",t:$("#rcT").value.trim(),m:$("#rcM").value.trim(),s,u,c:u};ok.push(d)}
    if(ok.length){rcGravar();RCV.sem=rcSeg(x.d);rcRender(curTab)}
    const mail=$("#rcMail")&&$("#rcMail").checked;
    if(ok.length&&mail){if(!pf||!pf.email)toast("Sem email deste formador em Formadores — confirmação não enviada");
      else try{const e=rcE(x.e);await msEnviar({to:pf.email,cc:msCfg().cc||"",subject:`Reserva confirmada: ${e.n} — ${rcDia(ok[0],{day:"numeric",month:"long"})}${ok.length>1?" (e mais "+(ok.length-1)+")":""}`,
        body:`Olá,\n\nFicou reservado o ${e.n}, das ${rcHm(x.h0)} às ${rcHm(x.h1)}:\n\n${ok.map(d=>"• "+rcDia(d)).join("\n")}\n${$("#rcT").value.trim()?"\nTurma: "+$("#rcT").value.trim():""}${$("#rcM").value.trim()?"\nMotivo: "+$("#rcM").value.trim():""}\n\nEscola Profissional da Ilha de São Jorge`});toast("Confirmação enviada para "+pf.email)}
      catch(er){toast("Reserva feita, mas o email não saiu: "+(er.message||er))}}
    if(ok.length&&!oc.length){rcFechar();if(!mail)toast(ok.length>1?ok.length+" reservas feitas":"Reserva feita · "+rcE(x.e).n+" · "+rcHm(x.h0)+"–"+rcHm(x.h1));return}
    b.disabled=!!ok.length;if(ok.length)b.textContent="Feito";
    $("#rcRes").innerHTML=`<div class="rc-livre ${ok.length?"":"mau"}">${ok.length?`✓ ${ok.length} ${ok.length>1?"reservas feitas":"reserva feita"}. `:""}<b>${oc.length>1?"Estes dias ficaram de fora":"Este dia ficou de fora"}:</b><ul>${oc.map(o=>`<li>${esc(rcDia(o.d,{weekday:"short",day:"numeric",month:"short"}))} — ocupado por ${esc(o.c.p)} (${rcHm(o.c.h0)}–${rcHm(o.c.h1)})</li>`).join("")}</ul></div>`}}

/* ---------- ver / alterar / cancelar ---------- */
function rcVer(r){if(!r)return;const e=rcE(r.e),hoje=rcHoje(),serie=r.s?rcAtivas().filter(x=>x.s===r.s&&x.d>=hoje).length:0;
  rcAbrir(e.n,`<div class="rc-f"><div class="rc-ver" style="--c:${esc(e.c)}"><b>${esc(rcDia(r.d))}</b><span>${rcHm(r.h0)}–${rcHm(r.h1)}</span></div>
    <dl class="rc-dl"><dt>Reservado por</dt><dd>${esc(r.p)}</dd>${r.t?`<dt>Turma</dt><dd>${esc(r.t)}</dd>`:""}${r.m?`<dt>Motivo</dt><dd>${esc(r.m)}</dd>`:""}${r.s?`<dt>Repetição</dt><dd>Todas as semanas (${serie} por vir)</dd>`:""}<dt>Marcada em</dt><dd>${esc(new Date(r.c||r.u).toLocaleString("pt-PT",{dateStyle:"short",timeStyle:"short"}))}</dd></dl>
    <div class="row" style="margin-top:8px"><button class="b s" id="rcMud">Mudar hora ou espaço</button><button class="b rc-del" id="rcC1">Cancelar esta reserva</button>${serie>1?`<button class="b s" id="rcCs">Cancelar toda a série</button>`:""}</div></div>`);
  const canc=serie=>{if(!confirm(serie?"Cancelar todas as reservas desta série, de hoje em diante?":"Cancelar esta reserva?"))return;const u=Date.now();let n=0;
    rcAtivas().forEach(x=>{if(serie?(x.s===r.s&&x.d>=hoje):x.id===r.id){RC.res[x.id]={...x,x:1,u};n++}});rcGravar();rcFechar();rcRender(curTab);toast(n>1?n+" reservas canceladas":"Reserva cancelada")};
  $("#rcC1").onclick=()=>canc(false);if($("#rcCs"))$("#rcCs").onclick=()=>canc(true);
  $("#rcMud").onclick=()=>{const E=RC.esp.filter(x=>x.on||x.id===r.e);
    rcAbrir("Mudar reserva",`<div class="rc-f"><span class="rc-l">Espaço</span><div class="rc-ops">${E.map(x=>`<label class="rc-op" style="--c:${esc(x.c)}"><input type="radio" name="rcE2" value="${esc(x.id)}" ${x.id===r.e?"checked":""}><i></i>${esc(x.n)}</label>`).join("")}</div>
      <div class="rc-3c"><label>Dia<input type="date" id="rcD2" value="${r.d}"></label><label>Das<input type="time" id="rcA2" value="${rcHm(r.h0)}" step="300"></label><label>Às<input type="time" id="rcB2" value="${rcHm(r.h1)}" step="300"></label></div>
      ${rcCamposHTML("2",{p:r.p,t:r.t,m:r.m})}
      <div class="row"><button class="b" id="rcG2">Guardar</button><button class="b s" id="rcX2">Voltar</button></div></div>`);
    $("#rcX2").onclick=()=>rcVer(RC.res[r.id]);rcCamposLigar("2");
    $("#rcG2").onclick=async()=>{const e2=(document.querySelector('input[name="rcE2"]:checked')||{}).value,d=$("#rcD2").value,h0=rcMin($("#rcA2").value),h1=rcMin($("#rcB2").value),p=$("#rcP2").value.trim();
      if(!d||!Number.isFinite(h0)||!Number.isFinite(h1)||h1<=h0)return toast("Verifique o dia e as horas");if(!p)return toast("Indique quem reserva");
      await rcTrazer(false);const c=rcChoque(e2,d,h0,h1,r.id);if(c)return toast(`Ocupado: ${c.p} das ${rcHm(c.h0)} às ${rcHm(c.h1)}`);
      RC.res[r.id]={...RC.res[r.id],e:e2,d,h0,h1,p,t:$("#rcT2").value.trim(),m:$("#rcM2").value.trim(),u:Date.now()};rcGravar();rcFechar();rcRender(curTab);toast("Reserva alterada")}}}

/* ---------- lista, PDF e CSV ---------- */
function rcFiltradas(){const e=$("#rcFE").value,de=$("#rcFDe").value,ate=$("#rcFAte").value,q=$("#rcFQ").value.trim().toLowerCase();
  return rcAtivas().filter(r=>(!e||r.e===e)&&(!de||r.d>=de)&&(!ate||r.d<=ate)&&(!q||[r.p,r.t,r.m].join(" ").toLowerCase().includes(q))).sort((a,b)=>a.d.localeCompare(b.d)||a.h0-b.h0||a.e.localeCompare(b.e))}
function rcLista(){const s=$("#rcFE"),v=s.value;s.innerHTML=`<option value="">Todos</option>`+RC.esp.map(e=>`<option value="${esc(e.id)}">${esc(e.n)}</option>`).join("");s.value=v;
  if(!$("#rcFDe").dataset.ini){$("#rcFDe").value=rcHoje();$("#rcFDe").dataset.ini=1}
  const L=rcFiltradas(),N=window.__rclN||200; // 0.9.48: com muitas reservas, mostra 200 de cada vez
  $("#rcTab").innerHTML=L.length?`<table class="rc-t"><thead><tr><th>Dia</th><th>Horas</th><th>Espaço</th><th>Reservado por</th><th>Turma</th><th>Motivo</th><th></th></tr></thead><tbody>${L.slice(0,N).map(r=>{const e=rcE(r.e);return `<tr><td>${esc(rcDia(r.d,{weekday:"short",day:"2-digit",month:"2-digit",year:"numeric"}))}</td><td>${rcHm(r.h0)}–${rcHm(r.h1)}</td><td><span class="rc-pt" style="--c:${esc(e.c)}"></span>${esc(e.n)}</td><td>${esc(r.p)}</td><td>${esc(r.t||"")}</td><td>${esc(r.m||"")}</td><td><button class="b s" data-rcv="${esc(r.id)}">Ver</button></td></tr>`}).join("")}</tbody></table><p class="hint">${L.length} reserva(s)${L.length>N?` — a mostrar ${N}. <button class="b s" id="rcMais">Mostrar mais ${Math.min(300,L.length-N)}</button>`:"."}</p>`
    :`<p class="hint">Nenhuma reserva com estes filtros.</p>`;
  document.querySelectorAll("#rcTab [data-rcv]").forEach(b=>b.onclick=()=>rcVer(RC.res[b.dataset.rcv]));
  const mm=$("#rcMais");if(mm)mm.onclick=()=>{window.__rclN=N+300;rcLista()}}
["#rcFE","#rcFDe","#rcFAte"].forEach(s=>$(s).addEventListener("change",()=>{window.__rclN=200;rcLista()}));$("#rcFQ").addEventListener("input",debounce(()=>{window.__rclN=200;rcLista()},200));
$("#rcCsv").onclick=()=>{const L=rcFiltradas(),q=v=>'"'+String(v??"").replace(/"/g,'""')+'"';
  download("reservas-"+rcHoje()+".csv","﻿"+[["Dia","Início","Fim","Espaço","Reservado por","Turma","Motivo"].map(q).join(";")].concat(L.map(r=>[r.d,rcHm(r.h0),rcHm(r.h1),rcE(r.e).n,r.p,r.t,r.m].map(q).join(";"))).join("\r\n"),"text/csv;charset=utf-8")};
$("#rcPdf").onclick=async()=>{try{const J=await loadPDF(),doc=new J({orientation:"landscape"}),L=rcFiltradas();
    doc.setFontSize(15);doc.text("Reservas de espaços — Escola Profissional da Ilha de São Jorge",14,16);doc.setFontSize(10);
    doc.text(`EPISJ 360 · Sala360 · ${$("#rcFE").value?rcE($("#rcFE").value).n:"todos os espaços"}${$("#rcFDe").value?" · de "+dataPT($("#rcFDe").value):""}${$("#rcFAte").value?" até "+dataPT($("#rcFAte").value):""} · emitido em ${new Date().toLocaleString("pt-PT",{dateStyle:"short",timeStyle:"short"})}`,14,23);
    doc.autoTable({startY:28,head:[["Dia","Horas","Espaço","Reservado por","Turma","Motivo"]],body:L.map(r=>[rcDia(r.d,{weekday:"short",day:"2-digit",month:"2-digit",year:"numeric"}),rcHm(r.h0)+"–"+rcHm(r.h1),rcE(r.e).n,r.p,r.t||"",r.m||""]),theme:"grid",styles:{fontSize:9},headStyles:{fillColor:[22,50,105]}});
    doc.save("reservas-"+rcHoje()+".pdf")}catch(e){toast("Não foi possível criar o PDF: "+(e.message||e))}};

/* ---------- espaços ---------- */
function rcEspMudou(){RC.et=Date.now();rcGravar();rcEspacos()}
function rcEspacos(){$("#rcEspTab").innerHTML=`<table class="rc-t"><thead><tr><th>Cor</th><th>Nome</th><th>Sigla</th><th>Reservável</th><th></th></tr></thead><tbody>${RC.esp.map((e,i)=>`<tr data-i="${i}"><td><input type="color" data-k="c" value="${esc(e.c)}"></td><td><input type="text" data-k="n" value="${esc(e.n)}" maxlength="60"></td><td style="width:110px"><input type="text" data-k="sg" value="${esc(e.sg)}" maxlength="5"></td><td style="width:100px"><input type="checkbox" data-k="on" ${e.on?"checked":""}></td><td style="width:60px">${rcAtivas().some(r=>r.e===e.id)?"":`<button class="b s" data-rcdel="${i}" title="Apagar">✕</button>`}</td></tr>`).join("")}</tbody></table>`;
  $("#rcAbre").value=rcHm(RC.cfg.abre);$("#rcFecha").value=rcHm(RC.cfg.fecha);$("#rcSab").checked=!!RC.cfg.sab;
  if(document.activeElement!==$("#rcTempos"))$("#rcTempos").value=rcTempos().map(t=>rcHm(t[0])+"-"+rcHm(t[1])).join("\n")}
$("#rcEspTab").addEventListener("change",ev=>{const i=ev.target.closest("tr")?.dataset.i,k=ev.target.dataset.k;if(i==null||!k)return;const e=RC.esp[+i];
  if(k==="on")e.on=ev.target.checked?1:0;else{const v=ev.target.value.trim();if(!v&&k!=="c"){rcEspacos();return}e[k]=v}rcEspMudou()});
$("#rcEspTab").addEventListener("click",ev=>{const b=ev.target.closest("[data-rcdel]");if(!b)return;const e=RC.esp[+b.dataset.rcdel];if(confirm(`Apagar o espaço “${e.n}”?`)){RC.esp.splice(+b.dataset.rcdel,1);rcEspMudou()}});
$("#rcEspAdd").onclick=()=>{RC.esp.push({id:"e"+uid(),n:"Novo espaço",sg:"NE",c:"#2f9e57",on:1});rcEspMudou()};
[["#rcAbre","abre"],["#rcFecha","fecha"]].forEach(([s,k])=>$(s).addEventListener("change",ev=>{const m=rcMin(ev.target.value);if(Number.isFinite(m)){RC.cfg[k]=m;if(RC.cfg.fecha<=RC.cfg.abre+60)RC.cfg.fecha=Math.min(1440,RC.cfg.abre+60);rcEspMudou()}}));
$("#rcSab").addEventListener("change",ev=>{RC.cfg.sab=ev.target.checked;rcEspMudou()});
$("#rcTempos").addEventListener("change",ev=>{const T=[],mal=[];ev.target.value.split(/\n/).map(l=>l.trim()).filter(Boolean).forEach(l=>{const m=l.match(/(\d{1,2})[:h.](\d{2})\s*[-–a]+\s*(\d{1,2})[:h.](\d{2})/);if(!m){mal.push(l);return}
    const a=+m[1]*60+ +m[2],b=+m[3]*60+ +m[4];if(b>a)T.push([a,b]);else mal.push(l)});
  if(!T.length){toast("Não percebi nenhum tempo — use o formato 08:30-09:20");return}
  RC.cfg.tempos=T.sort((a,b)=>a[0]-b[0]);rcEspMudou();toast(T.length+" tempos guardados"+(mal.length?` · ${mal.length} linha(s) não percebida(s)`:""))});
$("#rcTemposRepor").onclick=()=>{delete RC.cfg.tempos;rcEspMudou();toast("Repostos os tempos da escola")};
$("#rcTemposES").onclick=()=>{const st=mhEstado(),T=(st&&st.periods||[]).map(p=>[rcMin(p.start),rcMin(p.end)]).filter(t=>Number.isFinite(t[0])&&Number.isFinite(t[1])&&t[1]>t[0]);
  if(!T.length){toast("O horário do Horários360 deste ano letivo ainda não tem tempos com horas");return}RC.cfg.tempos=T;rcEspMudou();toast(T.length+" tempos copiados do Horários360")};
// abre logo com a última análise guardada, sem voltar a ler a Box
const pronto=(async()=>{try{await migrarListagem;let root="";try{root=localStorage.getItem("box_last_root")||""}catch(e){}
  if(root){const j=await lerListagem(root);if(j){useListing(j,true);showLast();boxMsg(`Aberta a análise guardada de “${j.pasta}” (${j.quando}): ${files.length} ficheiros e ${folders.length} pastas.`,"ok")}}
  await carregarRef()}catch(e){console.warn(e)}})();
textosProntos.then(()=>{if(curTab==="rel")renderReport();if(curTab==="alt")renderAlt()});

// ===== src/js/core/entrada.js =====
/* ===================== EPISJ 360 0.9 — entrada com o Office 365 e perfis de utilizador ===================== */
// Todos entram com a conta do Office 365 da escola. O serviço da EPISJ 360 (o mesmo dos avisos, na Cloudflare) confirma a conta
// junto da Microsoft e devolve o perfil — Direção Executiva, Direção Pedagógica, Formador ou Formando — e os separadores que pode abrir.
// A Box deixa de ser a porta de entrada: liga-se só dentro do módulo BoxCheck.
const PERFIL_CURTO={dexec:"Direção Executiva",dped:"Direção Pedagógica",prof:"Formador",form:"Formando",econ:"Economato"};
const perfilAtual=()=>PREV||(EU&&EU.perfil)||"";
const soLeitura=()=>!!EU&&!EU.admin&&(EU.perfil==="prof"||EU.perfil==="form");
const podePublicar=()=>!!EU&&!EU.provisorio&&(EU.admin||EU.perfil==="dexec"||EU.perfil==="dped");
async function guideTok(force){const p=await msInit();if(!MSACC&&sbAtivo()&&EU)await msSilencioso(EU.email);if(!MSACC)throw new Error("Sem sessão Microsoft — volte a entrar.");
  try{return (await p.acquireTokenSilent({scopes:LOGIN_SCOPES,account:MSACC,forceRefresh:!!force})).accessToken}
  catch(e){return (await p.acquireTokenPopup({scopes:LOGIN_SCOPES,account:MSACC,redirectUri:MS_REDIR})).accessToken}}
async function guideApi(path,opts,again){opts=opts||{};
  if(sbAtivo()){const m=(opts.method||"GET").toUpperCase(),b=opts.body?JSON.parse(opts.body):null;
    if(path==="/guide/eu")return sbRpc("g360_eu");
    if(path==="/guide/perfis")return m==="GET"?sbRpc("g360_perfis_ler"):sbRpc("g360_perfis_gravar",{p_loja:b});
    if(path==="/guide/publico")return m==="GET"?sbRpc("g360_publico_ler"):sbRpc("g360_publico_gravar",{p:b})}
  const tok=await guideTok(again);let r;
  try{r=await fetch(srvUrl()+path,{method:opts.method||"GET",body:opts.body,cache:"no-store",headers:Object.assign({Authorization:"Bearer "+tok},opts.body?{"Content-Type":"application/json"}:{})})}
  catch(e){throw new Error("Não foi possível contactar o serviço da EPISJ 360.")}
  if(r.status===401&&!again)return guideApi(path,opts,true);
  const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.erro||("o serviço respondeu "+r.status));return j}

async function guideArranque(){
  gateState("wait","");prog(4,"A ligar ao serviço da EPISJ 360…");
  if(sbCfg()){prog(10,"A confirmar a sessão…");try{await gpAte(SB_PRONTO,12000)}catch(e){}
    if(SBSES)return guideEntrarSB();
    $("#msSetup").style.display="none";$("#msGo").disabled=false;gateState("login",SBERR?esc(SBERR):"");return}
  try{const r=await fetch(srvUrl()+"/guide/config",{cache:"no-store"});if(r.ok){const j=await r.json();if(j.clientId&&j.tenant){GMS={clientId:j.clientId,tenant:j.tenant};try{localStorage.setItem("guide_ms",JSON.stringify(GMS))}catch(e){}}}}catch(e){}
  const {id,ten}=msIds();
  if(!id||!ten){$("#msSetup").style.display="";$("#msSetup").open=true;$("#msGo").disabled=true;gateState("login","");return}
  $("#msSetup").style.display="none";$("#msGo").disabled=false;prog(14,"A ligar ao Office 365…");
  try{const p=await msInit();prog(22,"A confirmar a sessão…");
    if(MSACC){try{const t=(await p.acquireTokenSilent({scopes:LOGIN_SCOPES,account:MSACC})).accessToken;return guideEntrar(t)}catch(e){}}}
  catch(e){gateState("login",msErro(e));return}
  gateState("login","")}
$("#msGo").onclick=async()=>{if(sbCfg()){gateState("wait","");prog(18,"A abrir o login do Office 365…");try{await sbEntrar()}catch(e){gateState("login",esc(e.message||String(e)))}return}
  try{const p=await msInit();gateState("wait","");prog(22,"À espera do Office 365…");
    const r=await p.loginPopup({scopes:LOGIN_SCOPES,prompt:"select_account",redirectUri:MS_REDIR});MSACC=r.account;p.setActiveAccount(r.account);await guideEntrar(r.accessToken)}
  catch(e){gateState("login",msErro(e))}};
$("#gMsSave").onclick=()=>{const id=$("#gMsClient").value.trim(),ten=$("#gMsTenant").value.trim();if(!id||!ten){toast("Preencha os dois campos");return}
  GMS={clientId:id,tenant:ten};try{localStorage.setItem("guide_ms",JSON.stringify(GMS))}catch(e){}MSAL=null;guideArranque()};

/* 0.9.174: «permission denied for function g360_eu» (o pedido chegou sem sessão), falhas de rede ou de sessão na entrada são quase
   sempre um bloqueador de conteúdos ou de publicidade a cortar a ligação à Microsoft ou à base de dados: explica e mostra o erro técnico por baixo */
function gateErroEntrada(e){const m=String((e&&e.message)||e||"");
  if(!/permission denied|42501|JWT|not authenticated|401|failed to fetch|networkerror|load failed|network request failed|blocked|ERR_BLOCKED/i.test(m))return esc(m);
  return `<b>Não foi possível confirmar a sua entrada.</b><br>Isto acontece quase sempre por causa de um <b>bloqueador de conteúdos ou de publicidade</b> (uBlock Origin, AdBlock, AdGuard, Ghostery, Privacy Badger, os escudos do Brave ou a proteção contra rastreio do Safari, Edge ou Firefox), que corta a ligação ao Office 365 ou à base de dados da app.
    <ol style="margin:8px 0 6px;padding-left:20px;text-align:left"><li>Desative o bloqueador para <b>episj360.episj.com</b> (no ícone da extensão, «desativar neste site»).</li><li>No Safari, Edge ou Firefox, ponha a proteção contra rastreio em «normal» para este site.</li><li><a href="#" id="gTentar">Tente outra vez</a>.</li></ol>
    <small style="opacity:.7">Erro técnico: ${esc(m)}</small>`}
/* 0.9.179: se o acesso de administrador ou o perfil desta conta mudar (noutro computador, em Utilizadores), a app sai e volta
   a entrar para o acesso novo se aplicar. Verifica a cada minuto e quando a página volta a ficar visível. */
var EU_VIG=null;
function euVigiar(){if(EU_VIG)return;const ver=async()=>{try{if(!EU||!SBSES||document.visibilityState==="hidden")return;const j=await sbRpc("g360_eu");if(!j)return;
    if(!!j.admin!==!!EU.admin||(j.perfil||"")!==(EU.perfil||"")){clearInterval(EU_VIG);toast("O seu acesso à EPISJ 360 mudou — a sair para o aplicar…");setTimeout(()=>{try{nuvFilaJa()}catch(e){}guideSair()},2500)}}catch(e){}};
  EU_VIG=setInterval(ver,60000);addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")ver()})}
async function guideEntrarSB(){
  gateState("wait","");prog(30,"A confirmar o perfil…");
  let j=SBEU;if(!j||!j.perfil){try{j=await sbRpc("g360_eu");SBEU=j}catch(e){gateState("login",gateErroEntrada(e));const r=$("#gTentar");if(r)r.onclick=ev=>{ev.preventDefault();location.reload()};return}}
  if(!j||!j.perfil){const em=SBSES&&SBSES.user&&SBSES.user.email||"";gateState("login",`A conta <b>${esc(em)}</b> ainda não tem perfil na EPISJ 360. Peça à Direção que lho atribua. <a href="#" id="gSairSB">Entrar com outra conta</a>`);
    const a=$("#gSairSB");if(a)a.onclick=e=>{e.preventDefault();sbSair().then(()=>location.reload())};return}
  SBMEMBRO=j;EU=j;MODS_OFF=Array.isArray(j.modsOff)?j.modsOff:[];window.__guideLogin=EU.email;
  euVigiar();
  msSilencioso(EU.email); // o Office 365 (email e OneDrive) liga-se em segundo plano, sem pedir nada
  prog(40,"Perfil: "+(EU.admin?"Administrador":(EU.perfilNome||PERFIL_CURTO[EU.perfil]||"")));
  whoUI();aplicarPerfil();
  if(EU.admin)perfisMigrar();
  try{if(sbAtivo&&sbAtivo())prefsTrazer()}catch(e){} // 0.9.154: tema e widgets da conta logo no início
  await guideCarregarModulos();
  try{await lgMigrar();aplicarLogos()}catch(e){}
  if(curTab&&curTab.startsWith("rc"))try{rcRender(curTab)}catch(e){}
  prog(100,"Pronto!");await gpEspera(GP.v<99?650:350);
  gateState("off");try{sbUI();window.__subEst&&window.__subEst()}catch(e){}
  try{sbTempoReal()}catch(e){}
  try{if(curTab==="esc")renderEscPainel()}catch(e){}Promise.resolve(prefsTrazer()).catch(()=>{}).finally(()=>setTimeout(novVer,700)); // 0.9.50: widgets desenhados com os dados da escola e preferências da conta
  if(window.__goBox&&podeVer("box"))show("box")}
// liga o MSAL sem janelas (para enviar email e copiar para o OneDrive), aproveitando a sessão do Office 365 que já existe no navegador
async function msSilencioso(email){try{const p=await msInit();if(MSACC)return;const acc=p.getAllAccounts().find(a=>String(a.username).toLowerCase()===String(email).toLowerCase());
  if(acc){MSACC=acc;p.setActiveAccount(acc);return}
  const r=await p.ssoSilent({scopes:LOGIN_SCOPES,loginHint:email,redirectUri:MS_REDIR});if(r&&r.account){MSACC=r.account;p.setActiveAccount(r.account)}}catch(e){}}
// os perfis que estavam no serviço da Cloudflare passam para o Supabase (uma vez, sem apagar os de lá)
async function perfisMigrar(){try{const L=await sbRpc("g360_perfis_ler");const lj=L&&L.loja||{};
  if((lj.admins&&lj.admins.length>0)||Object.keys(lj.utilizadores||{}).length||(lj.formandos&&(lj.formandos.padrao||(lj.formandos.dominios||[]).length)))return;
  await msSilencioso(EU.email);if(!MSACC)return;const tok=await guideTok();const r=await fetch(srvUrl()+"/guide/perfis",{headers:{Authorization:"Bearer "+tok},cache:"no-store"});
  if(!r.ok)return;const j=await r.json();if(j&&j.loja){await sbRpc("g360_perfis_gravar",{p_loja:j.loja});toast("Perfis trazidos do serviço antigo para a base de dados")}}catch(e){}}
