/* ---------- 0.9.148: nada fica no computador ----------
   A app já não grava nada no navegador (ver src/js/inicio/sem-armazenamento.js e DB em box/armazenamento.js).
   O que versões antigas deixaram neste computador (localStorage, IndexedDB «boxcheck») foi copiado para a memória ao abrir;
   15 s depois de entrar, legadoLimpar() confirma que está tudo na nuvem e apaga-o do computador:
   · quem é da Direção: sincroniza (junta com a nuvem e envia o que só estava aqui) e confere peça a peça com a base de dados;
   · as outras contas não gravam na nuvem: se o computador tiver alterações da Direção ainda por enviar, fica para quando
     alguém da Direção entrar neste computador. Fica só a sessão de entrada do Supabase (sessionStorage). */
async function sairLocais(){ // [peça na nuvem, rótulo, data da cópia local]
  const kv=async k=>{try{const v=await DB.get("kv",k);return v&&+v.t||0}catch(e){return 0}};
  return [["estado","Configuração da escola",cfgT()],["ES","Horários360",await kv("esched")],["CR","Crono360",await kv("crono")],["PAP","PAP360",await kv("pap")],
    ["FD","Folder360",await kv("folder")],["EC","Econo360",await kv("econo")],["EF","Econo360 (faturas)",await kv("econofat")],["PW","Pass360",await kv("pw")],["H3","Horários360 (avisos e contactos)",await kv("h3")]]}
async function sairVerificar(msg){msg=msg||(()=>{});
  if(!navigator.onLine)return{ok:false,porque:"Este computador está sem Internet: não dá para confirmar que está tudo na nuvem."};
  let L=await sairLocais();
  if(nuvSB()){
    msg("A juntar com a nuvem e a enviar o que só está neste computador…");
    try{await nuvemSincMS()}catch(e){}
    try{let idx=(await (await nuvem("GET","")).json()).itens||{};
      if(cfgT()>((idx.estado&&idx.estado.t)||0)){await nuvemPut("estado",estadoAtual(),cfgT());idx=(await (await nuvem("GET","")).json()).itens||{}}
      L=await sairLocais();
      const falta=L.filter(([n,,t])=>t>0&&t>((idx[n]&&idx[n].t)||0)).map(x=>x[1]);
      if(typeof rcNuvErr!=="undefined"&&rcNuvErr)falta.push("Sala360");
      if(NUV.erro)falta.push("("+NUV.erro+")");
      return falta.length?{ok:false,porque:"Ainda não está na nuvem: "+falta.join(", ")+"."}:{ok:true}}
    catch(e){return{ok:false,porque:"Não foi possível falar com a base de dados ("+(e.message||e)+")."}}}
  // outras contas: confere com o registo do que este computador já enviou para a nuvem
  const env=nuvT(),falta=L.filter(([n,,t])=>t>0&&t>(+env[n]||0)).map(x=>x[1]);
  let rcLocal=false;try{const r=JSON.parse(localStorage.getItem("roomcheck")||"null");rcLocal=!!(r&&r.res&&Object.keys(r.res).length&&!(+env.rc||0))}catch(e){}
  if(rcLocal)falta.push("Sala360");
  return falta.length?{ok:false,porque:"Este computador tem dados da Direção que podem ainda não estar na nuvem ("+falta.join(", ")+"). Fica neste computador até alguém da Direção entrar nele."}:{ok:true}}
async function legadoApagar(){const R=(window.__g360Mem&&window.__g360Mem.real)||{};
  try{if(R.ls){const ks=[];for(let i=0;i<R.ls.length;i++)ks.push(R.ls.key(i));ks.forEach(k=>{try{R.ls.removeItem(k)}catch(e){}})}}catch(e){}
  try{if(R.ss){const ks=[];for(let i=0;i<R.ss.length;i++)ks.push(R.ss.key(i));ks.forEach(k=>{if(!String(k).startsWith(SB_SES_KEY))try{R.ss.removeItem(k)}catch(e){}})}}catch(e){}
  await new Promise(ok=>{try{if(!window.indexedDB)return ok();const r=indexedDB.deleteDatabase("boxcheck");r.onsuccess=r.onerror=r.onblocked=()=>ok()}catch(e){ok()}setTimeout(ok,4000)})}
let LEGADO_FEITO=false;
async function legadoLimpar(){if(LEGADO_FEITO||LIMPAR||!EU||!EU.email)return;
  try{await DB.carregarLegado()}catch(e){}
  const M=window.__g360Mem||{},havia=(M.legado||0)+(DB.legado||0);
  if(havia){const v=await sairVerificar();if(!v.ok){console.warn("EPISJ 360: dados antigos ficam neste computador por agora —",v.porque);if(nuvSB())try{toast("Ainda há dados deste computador por confirmar na nuvem. "+v.porque)}catch(e){}return}}
  await legadoApagar();LEGADO_FEITO=true;if(havia)console.info("EPISJ 360: apagados deste computador os dados de versões antigas (já estão na nuvem)")}
