  if(o&&M.manual){const e=crManEnt(o.manL,crSeg(asof));if(e)l2+=`   ·   Dias de aula: ${Array.isArray(e.dias)?CR_DSEM.slice(0,M.nD).map((n,q)=>e.dias[q]?n+" "+crNum(e.dias[q]):"").filter(Boolean).join(", "):crNum(e.tl)+" tempos por semana"}`}
